// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"ebastin":{"wirkmechanismus":"Lindert allergische Beschwerden, indem es die Wirkung von Histamin blockiert, ohne wesentlich ins Gehirn zu gelangen. Ebastin ist ein Prodrug: Es wird in der Leber über CYP3A4 rasch zum wirksamen Metaboliten Carebastin umgewandelt, einem selektiven, lang wirksamen Antagonisten an peripheren H1-Rezeptoren. Die Wirkung hält etwa 24 Stunden an.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Schläfrigkeit","Mundtrockenheit"],"selten":["Schwindel, Nervosität, Schlaflosigkeit","Bauchschmerzen, Übelkeit, Erbrechen, Verdauungsbeschwerden","Herzklopfen, Herzrasen (Tachykardie)","Überempfindlichkeitsreaktionen wie Hautausschlag, Nesselsucht, Ödeme","Erhöhte Leberwerte, Leberentzündung","Menstruationsstörungen","Schwäche (Asthenie)"]},"schwangerschaft":"Begrenzte Erfahrungen; vorsichtshalber vermeiden bzw. nur nach ärztlicher Abwägung.","stillzeit":"Ob Ebastin in die Muttermilch übergeht, ist nicht bekannt; in der Stillzeit nicht empfohlen.","hinweise":["Kann unabhängig von den Mahlzeiten eingenommen werden.","Vor Allergie-Hauttests einige Tage vorher absetzen, da das Ergebnis sonst verfälscht wird."],"darreichung":["Filmtabletten"]},"econazol":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen, indem es den Aufbau ihrer Zellmembran stört. Econazol blockiert das pilzeigene Enzym Lanosterol-14-alpha-Demethylase und damit die Bildung von Ergosterol, dem wichtigsten Baustein der Pilzzellmembran; die Membran wird durchlässig und der Pilz stirbt ab. Es wirkt gegen Dermatophyten, Hefen und Schimmelpilze sowie gegen einige grampositive Bakterien. Nur ein kleiner Teil gelangt ins Blut; Econazol hemmt jedoch die Leberenzyme CYP3A4 und CYP2C9, was bei Blutverdünnern bedeutsam sein kann.","nebenwirkungen":{"haeufig":["Juckreiz und Brennen an der Anwendungsstelle (Haut bzw. Scheide und Schamlippen)","Schmerzen an der Anwendungsstelle"],"gelegentlich":["Rötung (Erythem)","Unwohlsein und Schwellung an der Anwendungsstelle"],"unbekannt":["Überempfindlichkeitsreaktionen, Angioödem (Schwellung)","Kontaktdermatitis, Ausschlag, Nesselsucht, Bläschen, Hautschuppung"]},"schwangerschaft":"Im 1. Drittel nur, wenn ärztlich als notwendig erachtet; danach nach ärztlicher Rücksprache möglich (geringe Aufnahme ins Blut).","stillzeit":"Mit Vorsicht anwenden – nicht bekannt, ob Econazol in die Muttermilch übergeht; nicht im Brustbereich auftragen.","hinweise":["Hautpilz: auch nach Abklingen der Beschwerden noch etwa 2 Wochen weiterbehandeln.","Bei gleichzeitiger Einnahme von Blutverdünnern (Phenprocoumon, Acenocoumarol) den INR kontrollieren lassen.","Latex-Kondome und Diaphragmen sind während der vaginalen Behandlung nicht sicher.","Pevisone enthält zusätzlich das Kortison Triamcinolon, ist rezeptpflichtig und nur kurzzeitig anzuwenden."],"darreichung":["Creme","Vaginalzäpfchen (Ovula)"]},"eculizumab":{"wirkmechanismus":"Blockiert einen Teil des Komplementsystems, einer Abwehrkaskade im Blut, die bei diesen Krankheiten eigene Blutzellen, Gefässe oder Nerven angreift. Eculizumab ist ein humanisierter monoklonaler Antikörper, der das Komplementprotein C5 bindet und dessen Spaltung in C5a und C5b verhindert. Damit entstehen weder der entzündungsfördernde Botenstoff C5a noch der zellzerstörende Membranangriffskomplex (C5b-9). Weil dieser Komplex auch Meningokokken abtötet, steigt das Risiko für Meningokokken-Infektionen stark.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Atemwegs- und Harnwegsinfekte, Lippenherpes","Leukopenie, Anämie","Schwindel","Bluthochdruck","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Hautausschlag, Juckreiz, Haarausfall","Gelenk- und Muskelschmerzen","Fieber, Müdigkeit, grippeähnliche Beschwerden"],"gelegentlich":["Meningokokken-Infektionen (Hirnhautentzündung, Blutvergiftung)","Anaphylaxie und schwere Überempfindlichkeitsreaktionen"],"selten":["Gonokokken-Infektion (auch gestreut)"]},"schwangerschaft":"Anwendung nach ärztlicher Nutzen-Risiko-Abwägung möglich; bei PNH liegen Erfahrungen in der Schwangerschaft vor. Der Antikörper kann die Plazenta passieren.","stillzeit":"Geht kaum in die Muttermilch über; Stillen nach ärztlicher Abwägung möglich.","hinweise":["Patientenkarte immer mitführen. Bei Fieber, Kopfschmerzen mit Übelkeit, Nackensteifigkeit, Lichtempfindlichkeit oder Hautflecken sofort den Notfall aufsuchen.","Meningokokken-Impfung mindestens 2 Wochen vor Beginn, sonst vorbeugende Antibiotika; Auffrischimpfungen gemäss Plan.","Infusionstermine strikt einhalten und nicht eigenmächtig absetzen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"edoxaban":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es einen zentralen Gerinnungsfaktor direkt blockiert. Edoxaban bindet direkt, selektiv und reversibel an den Gerinnungsfaktor Xa, frei im Blut und im Gerinnsel. Dadurch wird weniger Thrombin gebildet und neue Gerinnsel entstehen nicht. Edoxaban wird kaum über CYP-Enzyme abgebaut, ist aber ein Substrat des Transporters P-Glykoprotein und wird zu etwa der Hälfte über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Schwindel, Kopfschmerzen","Nasenbluten","Magen-Darm-Blutungen, Blutungen in Mund und Rachen","Bauchschmerzen, Übelkeit","Erhöhte Leberwerte (Bilirubin, GGT)","Haut- und Weichteilblutungen, Hautausschlag, Juckreiz","Blut im Urin, Scheidenblutungen, Blutungen an Einstichstellen"],"gelegentlich":["Hirnblutung","Thrombozytopenie (verminderte Blutplättchen)","Überempfindlichkeitsreaktionen, Nesselsucht","Blutungen am oder im Auge","Bluthusten","Erhöhte Transaminasen und alkalische Phosphatase","Blutungen an Operationswunden"],"selten":["Anaphylaktische Reaktion, allergisches Ödem","Subarachnoidal- und Subduralblutung","Blutung in den Herzbeutel","Blutungen im hinteren Bauchraum (retroperitoneal), Muskel- und Gelenkblutungen"],"unbekannt":["Antikoagulanzien-assoziierte Nephropathie (Nierenschädigung durch Blutungen in der Niere)"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter sollen während der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – entweder abstillen oder die Behandlung absetzen.","hinweise":["Einmal täglich, mit oder ohne Essen einnehmen; Tabletten dürfen zerstossen werden.","Nicht eigenmächtig absetzen – Gefahr von Schlaganfall oder Thrombose.","Nierenfunktion vor Beginn und regelmässig kontrollieren lassen; neue Medikamente in der Apotheke prüfen lassen.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, starke Kopfschmerzen, ungewöhnliche Blutergüsse) sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"efavirenz":{"wirkmechanismus":"Hemmt die Vermehrung des HI-Virus. Efavirenz bindet nicht-kompetitiv an die Reverse Transkriptase von HIV-1 und blockiert so das Umschreiben der viralen RNA in DNA; gegen HIV-2 wirkt es nicht. Efavirenz wird hauptsächlich über CYP2B6 abgebaut – bei genetisch langsamen Verstoffwechslern sind Spiegel und Nebenwirkungen höher. Es induziert CYP3A4 und CYP2B6 und senkt so die Spiegel vieler anderer Medikamente.","nebenwirkungen":{"sehrHaeufig":["Hautausschlag"],"haeufig":["Schwindel, Kopfschmerzen, Benommenheit, Konzentrationsstörungen","Abnorme Träume, Schlaflosigkeit","Depression, Angst","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Erhöhte Leberwerte, erhöhte Triglyceride","Juckreiz","Müdigkeit"],"gelegentlich":["Psychose, Halluzinationen, Manie, Paranoia, Aggression","Suizidgedanken, Suizidversuch","Krampfanfälle, Gleichgewichtsstörungen, Gedächtnisstörungen, Verwirrtheit","Akute Hepatitis, Pankreatitis","Erythema multiforme, Stevens-Johnson-Syndrom","Gynäkomastie (Brustvergrösserung beim Mann), erhöhtes Cholesterin","Verschwommenes Sehen, Tinnitus, Drehschwindel"],"selten":["Leberversagen","Vollendeter Suizid, Wahnvorstellungen","Photoallergische Hautentzündung"],"unbekannt":["QT-Verlängerung","Verzögert auftretende Enzephalopathie (Gangunsicherheit, Verwirrtheit) bei hohen Spiegeln"]},"schwangerschaft":"Nur anwenden, wenn der Zustand der Patientin dies zwingend erfordert; im Tierversuch Fehlbildungen, beim Menschen Einzelfälle von Neuralrohrdefekten. Vor Beginn Schwangerschaftstest; zuverlässige Verhütung (zusätzlich Barrieremethode) bis 12 Wochen nach Absetzen.","stillzeit":"Menschen mit HIV wird generell vom Stillen abgeraten; allenfalls nach eingehender Beratung durch die HIV-Fachperson.","hinweise":["Auf nüchternen Magen, am besten vor dem Schlafengehen einnehmen – das vermindert Schwindel und andere zentralnervöse Nebenwirkungen.","Kann Schwindel und Konzentrationsstörungen verursachen: Vorsicht beim Autofahren und Bedienen von Maschinen; Alkohol meiden.","Bei depressiver Verstimmung, Suizidgedanken oder Verwirrtheit sofort ärztliche Hilfe holen.","Zur hormonalen Verhütung immer zusätzlich ein Kondom verwenden."],"darreichung":["Filmtabletten","Kapseln"]},"efavirenz-emtricitabin-tenofovirdisoproxil":{"wirkmechanismus":"Drei Wirkstoffe hemmen dasselbe Virusenzym, die Reverse Transkriptase, auf zwei Arten. Efavirenz (NNRTI) bindet direkt an das Enzym und blockiert es. Emtricitabin (ein Cytidin-Analogon) und Tenofovir (aus dem Prodrug Tenofovirdisoproxil) werden in den Zellen aktiviert und führen nach Einbau in die Virus-DNA zum Kettenabbruch. Emtricitabin und Tenofovir wirken auch gegen Hepatitis B; Efavirenz induziert die Abbauenzyme CYP3A4 und CYP2B6.","nebenwirkungen":{"sehrHaeufig":["Schwindel, Kopfschmerzen","Durchfall, Übelkeit, Erbrechen","Hautausschlag","Hypophosphatämie (Phosphatmangel im Blut)","Erhöhte Kreatinkinase (Muskelenzym)","Schwäche (Asthenie)"],"haeufig":["Depression, Angst, abnorme Träume, Schlaflosigkeit","Gleichgewichts- und Koordinationsstörungen, Schläfrigkeit, Konzentrationsstörungen","Bauchschmerzen, Verdauungsbeschwerden, erhöhte Amylase und Lipase","Erhöhte Leberwerte, Blutfette und Blutzucker","Juckreiz, Nesselsucht, Hautverfärbung (Hyperpigmentierung)","Neutropenie, allergische Reaktionen","Müdigkeit, Schmerzen"],"gelegentlich":["Suizidgedanken, Suizidversuch, Psychose, Manie, Paranoia, Halluzinationen, Verwirrtheit, Aggression","Krampfanfälle, Gedächtnisstörungen, Ataxie, Zittern","Pankreatitis, Hepatitis","Stevens-Johnson-Syndrom, Erythema multiforme, Angioödem","Proximale Tubulopathie der Niere einschliesslich Fanconi-Syndrom, Kreatininanstieg, Eiweiss im Urin","Rhabdomyolyse, Muskelschwäche, Kaliummangel","Anämie, Gynäkomastie, verschwommenes Sehen, Ohrensausen"],"selten":["Vollendeter Suizid, Wahnvorstellungen","Leberversagen, Fettleber","Akutes Nierenversagen, akute Tubulusnekrose, nephrogener Diabetes insipidus","Osteomalazie (Knochenerweichung) mit Knochenschmerzen und Brüchen","Laktatazidose (Übersäuerung des Blutes)","Photoallergische Hautentzündung"],"unbekannt":["QT-Verlängerung","Spät auftretende Enzephalopathie und Ataxie (v. a. bei langsamem Efavirenz-Abbau)"]},"schwangerschaft":"In der Schwangerschaft nur anwenden, wenn keine geeignete Alternative besteht (Fehlbildungen im Tierversuch, Einzelfälle von Neuralrohrdefekten). Vor Beginn Schwangerschaftstest; Barrieremethode bis 12 Wochen nach dem Absetzen.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV; die Wirkstoffe gehen in die Muttermilch über). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Nüchtern, am besten vor dem Schlafengehen einnehmen – Schwindel, Schlafstörungen und Konzentrationsprobleme sind dann weniger spürbar.","Alkohol und andere dämpfende Substanzen meiden; bei Schwindel oder Benommenheit nicht Auto fahren.","Nierenfunktion und Phosphat werden regelmässig kontrolliert.","Bei gleichzeitiger Hepatitis B nicht eigenmächtig absetzen (Gefahr eines schweren Hepatitis-Schubs)."],"darreichung":["Filmtabletten"]},"efeublaetter-extrakt":{"wirkmechanismus":"Löst zähen Schleim und erleichtert das Abhusten. Wirksame Inhaltsstoffe sind Triterpensaponine, vor allem Hederacosid C, das im Körper zu Alpha-Hederin umgewandelt wird. Alpha-Hederin hemmt die Verinnerlichung von Beta-2-Rezeptoren in Zellen der Bronchien und Lungenbläschen; dadurch wird mehr Surfactant gebildet, der Schleim wird dünnflüssiger und die Bronchien entspannen sich leicht.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Erbrechen, Durchfall)","Allergische Reaktionen (Nesselsucht, Hautausschlag, Atemnot)","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Mangels ausreichender Daten nicht empfohlen.","stillzeit":"Mangels ausreichender Daten nicht empfohlen.","hinweise":["Nicht gleichzeitig mit Hustenstillern einnehmen, ausser auf ärztlichen Rat.","Bei Atemnot, Fieber, eitrigem oder blutigem Auswurf oder Husten länger als eine Woche ärztlich abklären lassen.","Ausreichend trinken unterstützt die Schleimlösung."],"darreichung":["Sirup (Hustensaft)","Brausetabletten"]},"efgartigimod-alfa":{"wirkmechanismus":"Senkt die Menge an IgG-Antikörpern im Blut, darunter die Autoantikörper, die bei Myasthenia gravis die Signalübertragung vom Nerv auf den Muskel stören. Efgartigimod alfa ist ein gentechnisch verändertes Fc-Fragment von menschlichem IgG1, das mit hoher Affinität an den neonatalen Fc-Rezeptor (FcRn) bindet. Dadurch werden IgG-Antikörper nicht mehr vor dem Abbau geschützt und in den Kreislauf zurückgeführt, sondern vermehrt abgebaut. Andere Antikörperklassen und Albumin werden nicht relevant beeinflusst.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege","Reaktionen an der Injektionsstelle bei subkutaner Gabe (Rötung, Juckreiz, Schmerz)"],"haeufig":["Harnwegsinfektionen, Bronchitis","Muskelschmerzen","Kopfschmerzen, auch nach der Infusion"],"unbekannt":["Überempfindlichkeitsreaktionen (Ausschlag, Angioödem, Atemnot), Anaphylaxie","Infusionsbedingte Reaktionen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung. Da weniger mütterliche Antikörper auf das Kind übergehen, Impfungen des Säuglings ärztlich besprechen.","stillzeit":"Keine ausreichenden Daten; Nutzen des Stillens und der Behandlung ärztlich abwägen.","hinweise":["Wird in Behandlungszyklen gegeben; Infusion bzw. Injektion in Klinik oder Praxis, danach auf allergische Reaktionen achten.","Impfstatus vor Beginn überprüfen; keine Lebendimpfungen während der Behandlung.","Fieber oder andere Infektzeichen ärztlich melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung zur subkutanen Anwendung (mit Hyaluronidase)"]},"eisen-ii-gluconat":{"wirkmechanismus":"Füllt die Eisenspeicher wieder auf, damit genügend roter Blutfarbstoff (Hämoglobin) gebildet werden kann. Zweiwertiges Eisen (Fe2+) wird vor allem im Zwölffingerdarm über den Transporter DMT1 aufgenommen, im Blut an Transferrin gebunden und zum Knochenmark sowie zu den Speichern (Ferritin) gebracht. Die Aufnahme ist bei Eisenmangel gesteigert, wird durch Vitamin C gefördert und durch Tee, Kaffee, Milch oder Phytate gehemmt.","nebenwirkungen":{"haeufig":["Magenbeschwerden, Übelkeit, Bauchschmerzen","Verstopfung oder Durchfall","Dunkle bis schwarze Verfärbung des Stuhls (harmlos)"],"selten":["Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz)"],"unbekannt":["Vorübergehende Verfärbung der Zähne","Erbrechen"]},"schwangerschaft":"Bei nachgewiesenem Eisenmangel oder erhöhtem Bedarf in der Schwangerschaft anwendbar.","stillzeit":"Kann in der Stillzeit angewendet werden.","hinweise":["Am besten vor einer Mahlzeit in einem Glas Wasser aufgelöst einnehmen; bei Magenbeschwerden zum Essen.","Nicht zusammen mit Tee, Kaffee, Milch oder Milchprodukten einnehmen; zu anderen Medikamenten mindestens 2 Stunden Abstand halten.","Für Kinder unerreichbar aufbewahren: eine Eisenüberdosierung ist für Kleinkinder lebensgefährlich.","Wirkung mit Blutbild und Ferritin kontrollieren; die Behandlung dauert meist mehrere Monate."],"darreichung":["Brausetabletten"]},"eisen-ii-sulfat":{"wirkmechanismus":"Ersetzt fehlendes Eisen, das der Körper für die Bildung des roten Blutfarbstoffs braucht. Zweiwertiges Eisen (Fe2+) wird vor allem im Zwölffingerdarm über einen Transporter (DMT1) in die Darmzellen aufgenommen, dort zu dreiwertigem Eisen oxidiert und an Transferrin gebunden im Blut transportiert. Im Knochenmark wird es in das Hämoglobin der roten Blutkörperchen eingebaut, der Rest wird als Ferritin gespeichert. Die Retardform gibt das Eisen langsam ab, um den Magen weniger zu reizen.","nebenwirkungen":{"haeufig":["Verstopfung (Obstipation)","Durchfall","Bauchschmerzen, Blähbauch","Übelkeit","Dunkle bis schwarze Verfärbung des Stuhls (harmlos)"],"gelegentlich":["Erbrechen","Dyspepsie (Verdauungsbeschwerden)","Gastritis (Magenschleimhautentzündung)","Juckreiz, Hautausschlag","Kehlkopfschwellung (Larynxödem)"],"unbekannt":["Überempfindlichkeitsreaktionen, Nesselsucht","Zahnverfärbungen","Geschwüre im Mund oder in der Speiseröhre bei falscher Einnahme (Tablette gelutscht, zerkaut oder stecken geblieben)","Schleimhautschäden der Bronchien, wenn die Tablette in die Atemwege gelangt"]},"schwangerschaft":"Kann bei nachgewiesenem Eisenmangel angewendet werden; Eisen- und Folsäurebedarf sind in der Schwangerschaft erhöht.","stillzeit":"Kann angewendet werden; Eisen geht nur in geringer Menge in die Muttermilch über.","hinweise":["Tablette unzerkaut mit einem Glas Wasser schlucken, nicht lutschen; nicht im Liegen einnehmen.","Am besten nüchtern oder vor dem Essen einnehmen; Tee, Kaffee, Milch und Vollkornprodukte vermindern die Aufnahme. Bei Magenbeschwerden zum Essen einnehmen.","Schwarzer Stuhl ist harmlos. Für Kinder unerreichbar aufbewahren – Eisenvergiftung ist bei Kleinkindern lebensgefährlich.","Behandlungserfolg mit Blutbild und Ferritin kontrollieren; die Eisenspeicher füllen sich erst nach mehreren Monaten."],"darreichung":["Retardtabletten (Filmtabletten mit verzögerter Freisetzung)"]},"eisen-iii-carboxymaltose":{"wirkmechanismus":"Füllt die Eisenspeicher direkt über die Vene auf, unter Umgehung des Darms. Eisencarboxymaltose ist ein stabiler Komplex aus einem Eisen(III)-hydroxid-Kern und einer Kohlenhydrathülle, der kaum freies Eisen abgibt. Er wird von Fresszellen (Makrophagen) in Leber, Milz und Knochenmark aufgenommen; das freigesetzte Eisen wird an Transferrin gebunden oder als Ferritin gespeichert und für die Hämoglobinbildung genutzt. Dank der Stabilität können bis zu 1000 mg Eisen in einer Kurzinfusion gegeben werden.","nebenwirkungen":{"haeufig":["Hypophosphatämie (Phosphatmangel im Blut)","Kopfschmerzen","Schwindel","Flush (Hitzegefühl, Hautrötung)","Bluthochdruck","Übelkeit","Reaktionen an der Infusionsstelle (Schmerzen, Bluterguss, Verfärbung, Paravasat)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Kribbeln (Parästhesien), Geschmacksstörung","Herzrasen, Blutdruckabfall","Atemnot","Erbrechen, Bauchschmerzen, Durchfall, Verstopfung","Juckreiz, Nesselsucht, Hautausschlag","Muskel-, Gelenk- und Rückenschmerzen","Fieber, Müdigkeit, Schüttelfrost, Wassereinlagerungen","Erhöhte Leberwerte"],"selten":["Anaphylaktische Reaktionen (allergischer Schock)","Bronchospasmus (Verkrampfung der Atemwege)","Kurze Bewusstlosigkeit (Synkope)","Venenentzündung","Angst"],"unbekannt":["Hypophosphatämische Osteomalazie (Knochenerweichung durch Phosphatmangel), Knochenbrüche","Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)","Gesichtsschwellung (Angioödem)"]},"schwangerschaft":"Im 1. Drittel nicht anwenden. Im 2. und 3. Drittel nur, wenn der Nutzen das Risiko klar überwiegt; eine allergische Reaktion der Mutter kann beim Ungeborenen eine Verlangsamung des Herzschlags auslösen.","stillzeit":"Es geht nur sehr wenig Eisen in die Muttermilch über; die Anwendung ist nach ärztlicher Abwägung möglich.","hinweise":["Wird nur in Praxis oder Spital gegeben, wo eine allergische Reaktion sofort behandelt werden kann; nach der Infusion mindestens 30 Minuten beobachten.","Bei wiederholten Infusionen oder Knochenschmerzen und Muskelschwäche den Phosphatwert kontrollieren lassen.","Der Behandlungserfolg (Ferritin, Hämoglobin) wird frühestens nach etwa 4 Wochen kontrolliert.","Eisentabletten erst 5 Tage nach der letzten Infusion wieder einnehmen."],"darreichung":["Injektions- und Infusionslösung (Durchstechflaschen)"]},"eisen-iii-derisomaltose":{"wirkmechanismus":"Füllt die Eisenspeicher über die Vene rasch auf, unabhängig von der Aufnahme im Darm. Dreiwertiges Eisen ist in einem stabilen Komplex mit dem Kohlenhydrat Derisomaltose gebunden, sodass nur wenig freies Eisen ins Blut gelangt. Der Komplex wird von Makrophagen in Leber, Milz und Knochenmark aufgenommen; das Eisen wird schrittweise freigesetzt, an Transferrin gebunden und zur Hämoglobinbildung verwendet oder als Ferritin gespeichert. Dadurch kann der Eisenbedarf oft mit einer einzigen Infusion gedeckt werden.","nebenwirkungen":{"haeufig":["Übelkeit","Hautausschlag","Reaktionen an der Injektions- oder Infusionsstelle (Schmerzen, Schwellung, Rötung)"],"gelegentlich":["Überempfindlichkeitsreaktionen, auch schwere","Kopfschmerzen, Missempfindungen, Geschmacksstörungen","Blutdruckabfall oder -anstieg, Herzrasen","Erbrechen, Bauchschmerzen, Verstopfung, Durchfall","Juckreiz, Nesselsucht, Hautrötung (Flush)","Muskel- und Rückenschmerzen, Fieber, Müdigkeit, Schüttelfrost"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Hypophosphatämie (Phosphatmangel), bei wiederholter Anwendung mit Knochenerweichung (Osteomalazie) und Knochenbrüchen","Kounis-Syndrom (allergisch ausgelöste Herzkranzgefässverengung)"]},"schwangerschaft":"Im ersten Schwangerschaftsdrittel nicht anwenden. Im 2. und 3. Drittel nur, wenn eindeutig erforderlich, da allergische Reaktionen beim Ungeborenen einen verlangsamten Herzschlag auslösen können.","stillzeit":"Geht höchstens in geringen Mengen in die Muttermilch über; ein Risiko für den Säugling ist unwahrscheinlich.","hinweise":["Wird nur dort gegeben, wo eine allergische Notfallbehandlung sofort möglich ist; nach jeder Gabe mindestens 30 Minuten Beobachtung.","Juckreiz, Atemnot, Schwindel oder Hautausschlag während der Infusion sofort melden.","Eisentabletten nicht gleichzeitig einnehmen.","Bei wiederholten Gaben Phosphat kontrollieren lassen; Knochenschmerzen oder Muskelschwäche melden."],"darreichung":["Injektions- bzw. Infusionslösung"]},"eisen-iii-hydroxid-polymaltose-komplex":{"wirkmechanismus":"Ersetzt fehlendes Eisen für die Blutbildung. Das dreiwertige Eisen liegt als Eisen(III)-hydroxid-Kern vor, der von Polymaltose (einem Zuckerpolymer) umhüllt ist; dadurch wird im Darm kaum freies, reizendes Eisen frei. Die Aufnahme erfolgt über einen aktiven, vom Körper gesteuerten Mechanismus, sodass bei vollen Speichern weniger aufgenommen wird. Das Eisen wird an Transferrin gebunden, ins Hämoglobin eingebaut oder als Ferritin gespeichert. Nahrungsbestandteile beeinflussen die Aufnahme weniger stark als bei zweiwertigem Eisen.","nebenwirkungen":{"sehrHaeufig":["Dunkle Verfärbung des Stuhls (harmlos)"],"haeufig":["Durchfall","Übelkeit","Dyspepsie (Verdauungsbeschwerden)"],"gelegentlich":["Erbrechen","Verstopfung (Obstipation)","Bauchschmerzen","Gastritis (Magenschleimhautentzündung)","Zahnverfärbung (v. a. Tropfen und Sirup)","Kopfschmerzen","Juckreiz, Hautausschlag, Nesselsucht"],"unbekannt":["Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Im 2. und 3. Drittel ohne Hinweise auf Schäden für Mutter oder Kind untersucht und anwendbar; im 1. Drittel nur nach ärztlicher Abwägung.","stillzeit":"Kann angewendet werden; Eisen geht nur in geringer Menge in die Muttermilch über.","hinweise":["Während oder unmittelbar nach einer Mahlzeit einnehmen; Tropfen und Sirup können mit Fruchtsaft oder Brei gemischt werden.","Dunkler Stuhl ist harmlos und beeinflusst Tests auf verborgenes Blut im Stuhl nicht wesentlich.","Die Behandlung dauert meist mehrere Monate, bis die Eisenspeicher (Ferritin) aufgefüllt sind – Blutwerte kontrollieren lassen.","Für Kinder unerreichbar aufbewahren."],"darreichung":["Filmtabletten","Kautabletten","Tropfen","Sirup"]},"eisen-iii-saccharose":{"wirkmechanismus":"Füllt die Eisenspeicher direkt über die Vene auf, unter Umgehung des Darms. Eisensaccharose besteht aus einem Eisen(III)-hydroxid-Kern, der von Saccharose (Zucker) umhüllt ist. Der Komplex wird von Fresszellen (Makrophagen) in Leber, Milz und Knochenmark aufgenommen; das Eisen wird an Transferrin gebunden, ins Hämoglobin eingebaut oder als Ferritin gespeichert. Weil der Komplex weniger stabil ist als neuere Präparate, werden kleinere Einzeldosen in mehreren Sitzungen gegeben.","nebenwirkungen":{"haeufig":["Geschmacksstörung (Dysgeusie)","Blutdruckabfall oder Blutdruckanstieg","Übelkeit","Reaktionen an der Injektions- oder Infusionsstelle (Schmerzen, Brennen, Verfärbung)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Kopfschmerzen, Schwindel, Kribbeln (Parästhesien)","Flush (Hitzegefühl), Venenentzündung","Atemnot","Erbrechen, Bauchschmerzen, Durchfall, Verstopfung","Juckreiz, Hautausschlag","Muskelkrämpfe, Muskel- und Gelenkschmerzen","Schüttelfrost, Müdigkeit, Wassereinlagerungen","Erhöhte Leberwerte, erhöhtes Ferritin"],"selten":["Kurze Bewusstlosigkeit (Synkope), Schläfrigkeit","Herzklopfen","Brustschmerzen","Verfärbung des Urins","Fieber, vermehrtes Schwitzen"],"unbekannt":["Anaphylaktische Reaktionen (allergischer Schock), Angioödem","Kreislaufkollaps","Bronchospasmus (Verkrampfung der Atemwege)","Verwirrtheit, Bewusstseinsstörung","Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)","Langsamer oder schneller Herzschlag"]},"schwangerschaft":"Im 1. Drittel nicht anwenden. Im 2. und 3. Drittel nur, wenn der Nutzen das Risiko klar überwiegt; eine allergische Reaktion der Mutter kann das Ungeborene gefährden.","stillzeit":"Unverändertes Eisensaccharose geht kaum in die Muttermilch über; die Anwendung ist nach ärztlicher Abwägung möglich.","hinweise":["Wird nur in Praxis oder Spital gegeben, wo eine allergische Reaktion sofort behandelt werden kann; nach jeder Gabe mindestens 30 Minuten beobachten.","Der gesamte Eisenbedarf wird meist auf mehrere Termine verteilt.","Eisentabletten erst 5 Tage nach der letzten Gabe wieder einnehmen."],"darreichung":["Injektions- und Infusionslösung (Ampullen)"]},"elacestrant":{"wirkmechanismus":"Blockiert den Östrogenrezeptor in Brustkrebszellen und lässt ihn abbauen, sodass das Hormonsignal für das Tumorwachstum entfällt. Elacestrant bindet an den Östrogenrezeptor alpha, hemmt ihn und führt zu seinem Abbau (SERD). Es wirkt auch bei Rezeptoren mit aktivierender ESR1-Mutation, die nach Behandlung mit Aromatasehemmern häufig auftreten. Anders als Fulvestrant wird es als Tablette eingenommen.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen, Durchfall, Verstopfung, Bauchschmerzen, Verdauungsbeschwerden","Müdigkeit, Schwäche","Appetitlosigkeit","Kopfschmerzen","Muskel-, Knochen- und Gelenkschmerzen","Erhöhte Blutfette (Cholesterin, Triglyceride)","Erhöhte Leberwerte","Hitzewallungen"],"haeufig":["Schlaflosigkeit, Schwindel","Husten, Atemnot"],"unbekannt":["Venöse Thromboembolien (Blutgerinnsel)"]},"schwangerschaft":"Nicht anwenden (kann das ungeborene Kind schädigen). Frauen im gebärfähigen Alter und Männer mit Partnerin müssen während und bis 1 Woche nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Mit einer Mahlzeit einnehmen (bessere Verträglichkeit und Aufnahme).","Grapefruit und Johanniskraut meiden.","Blutfette und Leberwerte vor Beginn und regelmässig kontrollieren."],"darreichung":["Filmtabletten"]},"elafibranor":{"wirkmechanismus":"Verringert die Belastung der Leber durch Gallensäuren und dämpft die Entzündung der kleinen Gallengänge. Elafibranor aktiviert die Kernrezeptoren PPAR-alpha und PPAR-delta, die den Gallensäure- und Fettstoffwechsel steuern. Dadurch wird die Neubildung von Gallensäuren in der Leber (über das Enzym CYP7A1) gedrosselt, ihr Abtransport gefördert und Entzündungsvorgänge gehemmt; die alkalische Phosphatase als Marker der Krankheitsaktivität sinkt. Ein aktiver Hauptmetabolit trägt zur Wirkung bei.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen","Durchfall","Übelkeit","Erbrechen"],"unbekannt":["Muskelschmerzen, erhöhte Kreatinkinase (CK), Myopathie bis Rhabdomyolyse","Knochenbrüche","Erhöhte Leberwerte"]},"schwangerschaft":"Kontraindiziert, da Tierversuche eine Schädigung des Ungeborenen zeigten. Vor Beginn eine Schwangerschaft ausschliessen und bis 3 Wochen nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Nicht empfohlen, da keine Daten vorliegen.","hinweise":["Mit oder ohne Mahlzeit einnehmen; Gallensäurebinder mindestens 4 Stunden zeitversetzt.","Unerklärliche Muskelschmerzen oder Muskelschwäche umgehend melden, besonders bei gleichzeitiger Einnahme eines Statins.","Hormonelle Verhütung allein reicht nicht – zusätzlich Kondom verwenden."],"darreichung":["Filmtabletten"]},"eletriptan":{"wirkmechanismus":"Lindert den Migränekopfschmerz, indem es erweiterte Blutgefässe im Kopf verengt und die Ausschüttung entzündlicher Botenstoffe hemmt. Eletriptan ist ein selektiver Agonist an Serotonin-5-HT1B- und -5-HT1D-Rezeptoren an Hirngefässen und Trigeminusnerven und hemmt die Freisetzung von Neuropeptiden. Im Unterschied zu anderen Triptanen wird es hauptsächlich über CYP3A4 abgebaut und ist daher empfindlich für CYP3A4-Hemmer.","nebenwirkungen":{"haeufig":["Schläfrigkeit, Schwindel, Kopfschmerzen, Kribbeln oder Taubheitsgefühl","Herzklopfen, Herzrasen, Hitzewallungen","Engegefühl im Hals, Rachenentzündung","Übelkeit, Bauchschmerzen, Mundtrockenheit, Verdauungsbeschwerden","Schwitzen","Rücken- und Muskelschmerzen, Muskelschwäche","Wärmegefühl, Schwäche, Schmerzen oder Engegefühl in der Brust, Schüttelfrost"],"gelegentlich":["Verwirrtheit, Unruhe, Depression, Schlaflosigkeit","Zittern, Koordinations- und Sprachstörungen","Sehstörungen, Augenschmerzen, Lichtscheu, Ohrensausen","Atemnot, Gähnen","Durchfall","Hautausschlag, Juckreiz","Häufiges Wasserlassen, Wassereinlagerungen (Ödeme)"],"selten":["Verlangsamter Puls (Bradykardie)","Kreislaufschock","Asthma","Verstopfung","Nesselsucht"],"unbekannt":["Überempfindlichkeitsreaktionen einschliesslich Angioödem","Serotoninsyndrom","Ohnmacht (Synkope)","Herzinfarkt, koronare Gefässkrämpfe","Blutdruckanstieg","Ischämische Kolitis (Darmentzündung durch Minderdurchblutung)","Erbrechen"]},"schwangerschaft":"Nur begrenzte Erfahrungen; nur anwenden, wenn eindeutig erforderlich.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nach der Einnahme 24 Stunden nicht stillen.","hinweise":["Vor einer Behandlung mit Antibiotika, Pilz- oder HIV-Mitteln die Einnahme von Eletriptan angeben (gefährliche Wechselwirkungen).","Akutmittel gegen Migräne an höchstens 10 Tagen pro Monat verwenden, sonst droht Kopfschmerz durch Medikamentenübergebrauch.","Kann Schläfrigkeit und Schwindel verursachen – Vorsicht beim Autofahren."],"darreichung":["Filmtabletten"]},"elexacaftor-tezacaftor-ivacaftor":{"wirkmechanismus":"Verbessert die Funktion des defekten Chloridkanals CFTR, dessen Fehlfunktion bei Mukoviszidose zu zähem Schleim in Lunge, Bauchspeicheldrüse und anderen Organen führt. Elexacaftor und Tezacaftor sind CFTR-Korrektoren: Sie helfen dem fehlgefalteten CFTR-Protein (v. a. bei der F508del-Mutation), sich richtig zu falten und an die Zelloberfläche zu gelangen. Ivacaftor ist ein CFTR-Potentiator und erhöht die Öffnungswahrscheinlichkeit des Kanals an der Zelloberfläche. Zusammen steigt der Chloridtransport, was sich an tieferen Schweisschloridwerten und einer besseren Lungenfunktion zeigt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Schwindel","Infektionen der oberen Atemwege, Nasen-Rachen-Entzündung","Halsschmerzen, verstopfte Nase","Durchfall, Bauchschmerzen","Hautausschlag","Bakterien im Sputum (Auswurf)"],"haeufig":["Erhöhte Leberwerte (Transaminasen), erhöhte Kreatinkinase und Bilirubin","Grippe (Influenza), Schnupfen","Hypoglykämie (Unterzuckerung)","Ohrenschmerzen, Ohrgeräusche (Tinnitus), Gleichgewichtsstörungen","Übelkeit, Blähungen","Akne, Juckreiz","Knoten in der Brust"],"gelegentlich":["Vergrösserung der Brustdrüse beim Mann (Gynäkomastie)","Pfeifende Atmung (Giemen)","Druckgefühl im Ohr"],"unbekannt":["Schwere Leberschädigung bis Leberversagen","Depression, Angst, Schlafstörungen, Suizidgedanken","Linsentrübung (Katarakt) bei Kindern und Jugendlichen"]},"schwangerschaft":"Begrenzte Erfahrungen; vorsichtshalber möglichst vermeiden und nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nicht bekannt, ob die Wirkstoffe beim Menschen in die Muttermilch übergehen (im Tierversuch ja); nur nach ärztlicher Abwägung.","hinweise":["Morgens die Kombinationstablette und abends die Ivacaftor-Tablette jeweils mit einer fetthaltigen Mahlzeit einnehmen (z. B. mit Butter, Käse, Eiern oder Vollmilch).","Grapefruit und Bitterorangen meiden.","Leberwerte vor Beginn und regelmässig während der Behandlung kontrollieren; bei Kindern zusätzlich Augenkontrollen.","Vor jedem neuen Medikament (auch Antibiotika, Antimykotika oder Johanniskraut) Wechselwirkungen prüfen lassen."],"darreichung":["Filmtabletten"]},"eliglustat":{"wirkmechanismus":"Vermindert die Bildung von Glucosylceramid, das sich bei Morbus Gaucher in Milz, Leber und Knochenmark anhäuft. Eliglustat hemmt spezifisch die Glucosylceramid-Synthase, das erste Enzym der Glykosphingolipid-Bildung (Substratreduktion). Dadurch gehen Milz- und Lebervergrösserung zurück, und Hämoglobin und Blutplättchen steigen. Abgebaut wird es vor allem über CYP2D6 und CYP3A4, weshalb vor Beginn der CYP2D6-Genotyp bestimmt wird.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Geschmacksstörung","Palpitationen (Herzklopfen)","Halsreizung","Dyspepsie (Verdauungsbeschwerden), Oberbauchschmerzen, Sodbrennen","Durchfall, Übelkeit, Verstopfung, Blähungen","Gelenkschmerzen","Müdigkeit"]},"schwangerschaft":"Vorsichtshalber in der Schwangerschaft vermeiden.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen; über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Vor Beginn wird mit einem Gentest bestimmt, wie schnell das Enzym CYP2D6 arbeitet; davon hängen Eignung und Dosis ab.","Grapefruit und Grapefruitsaft meiden.","Vor jedem neuen Medikament (auch rezeptfreie und pflanzliche Mittel wie Johanniskraut) ärztlich oder in der Apotheke nachfragen: viele Wechselwirkungen.","Kapseln ganz schlucken, mit oder ohne Essen."],"darreichung":["Hartkapseln"]},"elinzanetant":{"wirkmechanismus":"Lindert Hitzewallungen, ohne Hormone zuzuführen, indem es eine überaktive Schaltstelle der Temperaturregulation im Gehirn dämpft. Nach der Menopause fällt die bremsende Wirkung der Östrogene auf bestimmte Nervenzellen im Hypothalamus (KNDy-Neuronen) weg; diese stören dann über die Botenstoffe Neurokinin B und Substanz P das Wärmeregulationszentrum. Elinzanetant blockiert die Neurokinin-3- und Neurokinin-1-Rezeptoren und normalisiert so diese Signale.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Müdigkeit (Fatigue)","Somnolenz (Schläfrigkeit)","Schwindel"]},"schwangerschaft":"Nicht anwenden: für die Schwangerschaft nicht bestimmt, es liegen keine Erfahrungen vor. Tritt eine Schwangerschaft ein, die Behandlung beenden.","stillzeit":"Nicht anwenden (keine Erfahrungen).","hinweise":["Einmal täglich vor dem Schlafengehen einnehmen; die Kapseln ganz schlucken.","Wegen möglicher Schläfrigkeit Alkohol meiden und die Fahrtüchtigkeit besonders zu Beginn kritisch prüfen.","Vor Beginn alle anderen Medikamente angeben – viele Mittel beeinflussen den Abbau über CYP3A4."],"darreichung":["Weichkapseln"]},"elosulfase-alfa":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, damit sich Zuckerketten nicht mehr vor allem in Knorpel und Knochen anhäufen. Elosulfase alfa ist eine gentechnisch hergestellte N-Acetylgalactosamin-6-Sulfatase (GALNS). Sie wird über Mannose-6-Phosphat-Rezeptoren in die Zellen aufgenommen und baut in den Lysosomen Keratansulfat und Chondroitin-6-sulfat ab. Dadurch sinkt die Ausscheidung von Keratansulfat im Urin, und die Gehstrecke kann sich bessern.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen, Schwindel","Atemnot","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Schmerzen in Mund und Rachen","Fieber, Schüttelfrost"],"haeufig":["Anaphylaxie (schwere allergische Reaktion)","Muskelschmerzen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen. Nur anwenden, wenn eindeutig nötig.","stillzeit":"Nicht bekannt, ob Elosulfase alfa in die Muttermilch übergeht. Stillen nur nach ärztlicher Abwägung.","hinweise":["Wird wöchentlich als Infusion in eine Vene gegeben (über mehrere Stunden), meist nach Vorbehandlung mit einem Antihistaminikum.","Atemnot, Schwellungen oder Ausschlag während oder nach der Infusion sofort melden.","Neue Nackenschmerzen, Kribbeln oder Schwäche in Armen oder Beinen sofort ärztlich abklären lassen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"elotuzumab":{"wirkmechanismus":"Stärkt die körpereigene Abwehr gegen Myelomzellen. Elotuzumab ist ein humanisierter IgG1-Antikörper gegen SLAMF7 (CS1), ein Oberflächenprotein auf Myelomzellen und auf natürlichen Killerzellen (NK-Zellen). Er aktiviert NK-Zellen direkt und markiert gleichzeitig die Myelomzellen für die antikörperabhängige zellvermittelte Zytotoxizität (ADCC). Lenalidomid und Pomalidomid stimulieren ebenfalls NK-Zellen, was die Wirkung in der Kombination verstärkt.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege, Nasopharyngitis (Erkältung)","Lungenentzündung","Lymphopenie (Mangel an Lymphozyten)","Husten","Durchfall","Fieber, Müdigkeit","Gewichtsabnahme"],"haeufig":["Herpes zoster (Gürtelrose)","Infusionsreaktionen","Leukopenie (Mangel an weissen Blutkörperchen)","Hypästhesie (vermindertes Berührungsempfinden)","Stimmungsschwankungen","Tiefe Venenthrombose","Schmerzen in Mund und Rachen","Nachtschweiss, Brustschmerzen"],"gelegentlich":["Überempfindlichkeitsreaktionen bis Anaphylaxie"],"unbekannt":["Zweite Krebserkrankungen (z. B. Hautkrebs, solide Tumoren) unter der Kombinationstherapie"]},"schwangerschaft":"Keine Erfahrungen. Wegen der Kombination mit Lenalidomid bzw. Pomalidomid in der Schwangerschaft kontraindiziert; deren Schwangerschaftsverhütungsprogramm ist einzuhalten.","stillzeit":"Nicht bekannt, ob Elotuzumab in die Muttermilch übergeht; wegen der Kombinationspartner nicht stillen.","hinweise":["Vor jeder Infusion werden Medikamente gegen Infusionsreaktionen gegeben; Fieber, Schüttelfrost oder Atemnot während der Infusion sofort melden.","Bei Fieber oder anderen Infektzeichen rasch ärztlich abklären lassen.","Das Schwangerschaftsverhütungsprogramm von Lenalidomid bzw. Pomalidomid gilt auch für die Kombinationstherapie."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"elranatamab":{"wirkmechanismus":"Verbindet körpereigene Abwehrzellen (T-Zellen) mit Myelomzellen, damit diese zerstört werden. Elranatamab ist ein humanisierter bispezifischer IgG2-Antikörper gegen BCMA (B-Zell-Reifungsantigen) auf Myelomzellen und CD3 auf T-Zellen. Die so aktivierten T-Zellen setzen Zytokine und zytotoxische Proteine frei und töten die BCMA-tragenden Zellen. Weil auch gesunde Plasmazellen BCMA tragen, sinken die Antikörperspiegel im Blut.","nebenwirkungen":{"sehrHaeufig":["Zytokin-Freisetzungs-Syndrom","Infektionen (Lungenentzündung, Atemwegsinfekte)","Anämie, Neutropenie, Thrombozytopenie, Lymphopenie","Reaktionen an der Injektionsstelle","Durchfall, Appetitlosigkeit","Müdigkeit, Fieber"],"haeufig":["ICANS (immuneffektorzell-assoziiertes Neurotoxizitätssyndrom)","Sepsis (Blutvergiftung)","Febrile Neutropenie (Fieber bei Mangel an Abwehrzellen)","Periphere Neuropathie (Kribbeln, Taubheit)","Erhöhte Leberwerte"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, seltene Hirninfektion)"]},"schwangerschaft":"Kann beim Ungeborenen Blutbildveränderungen und Antikörpermangel verursachen; in der Schwangerschaft nicht empfohlen. Frauen verhüten während und mehrere Monate nach der letzten Dosis (Dauer gemäss ärztlicher Anweisung).","stillzeit":"Während der Behandlung und einige Monate danach nicht stillen.","hinweise":["Die Aufbaudosen werden unter Überwachung im Spital gegeben; Fieber, Schüttelfrost, Atemnot, Schwindel oder Verwirrtheit sofort melden.","Nach den Aufbaudosen und bei neurologischen Beschwerden kein Fahrzeug lenken und keine Maschinen bedienen.","Infektzeichen umgehend melden; Blutbild und Immunglobuline werden regelmässig kontrolliert.","Patientenkarte immer mitführen."],"darreichung":["Injektionslösung zur subkutanen Anwendung"]},"eltrombopag":{"wirkmechanismus":"Regt das Knochenmark an, mehr Blutplättchen zu bilden. Eltrombopag ist ein kleines, oral wirksames Molekül, das an die Transmembrandomäne des Thrombopoetin-Rezeptors (c-Mpl) bindet – an einer anderen Stelle als das körpereigene Thrombopoetin. Dadurch werden Vermehrung und Reifung der Megakaryozyten gefördert. Bei aplastischer Anämie kann auch die Bildung roter und weisser Blutkörperchen zunehmen.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erhöhte Leberwerte (ALT)"],"haeufig":["Atemwegsinfekte (z. B. Nasen-Rachen-Entzündung, Grippe)","Erbrechen, Bauchschmerzen, Mundgeschwüre","Hautausschlag, Juckreiz, Haarausfall","Muskel-, Rücken- und Knochenschmerzen","Müdigkeit, Wassereinlagerungen (Ödeme)","Schlafstörungen, Missempfindungen (Kribbeln)","Trockene Augen","Erhöhtes Bilirubin im Blut"],"gelegentlich":["Thromboembolien (z. B. tiefe Venenthrombose, Lungenembolie, Pfortaderthrombose)","Katarakt (Grauer Star)","Leberentzündung, arzneimittelbedingte Leberschädigung"],"unbekannt":["Verfärbung der Haut (Hyperpigmentierung, Gelbfärbung)","Thrombotische Mikroangiopathie mit akutem Nierenversagen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; im Tierversuch schädlich. Während der Schwangerschaft nicht empfohlen; Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob Eltrombopag in die Muttermilch übergeht. Stillen oder Behandlung nur nach ärztlicher Abwägung.","hinweise":["Nüchtern oder mit einer kalziumarmen Mahlzeit einnehmen; mindestens 2 Stunden vor oder 4 Stunden nach Milchprodukten, Antazida und Mineralstoffpräparaten.","Leberwerte vor Beginn, während der Dosisfindung alle 2 Wochen und danach monatlich kontrollieren.","Nicht eigenmächtig absetzen: die Plättchen können rasch abfallen."],"darreichung":["Filmtabletten"]},"elvitegravir-cobicistat-emtricitabin-tenofoviralafenamid":{"wirkmechanismus":"Vier Wirkstoffe hemmen die Vermehrung des HI-Virus. Elvitegravir blockiert die Integrase und verhindert den Einbau des Virus-Erbguts in die Wirtszelle. Emtricitabin und Tenofovir (aus dem Prodrug Tenofoviralafenamid, das vor allem in den Zellen aktiviert wird) hemmen die Reverse Transkriptase durch Kettenabbruch. Cobicistat wirkt nicht gegen das Virus, sondern hemmt das Abbauenzym CYP3A und erhöht so die Elvitegravir-Spiegel; dadurch beeinflusst es auch viele andere Arzneimittel.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Kopfschmerzen, Schwindel","Abnorme Träume","Durchfall, Erbrechen, Blähungen","Hautausschlag","Müdigkeit"],"gelegentlich":["Depression (v. a. bei psychischer Vorerkrankung)","Anämie","Verdauungsbeschwerden","Angioödem, Juckreiz, Nesselsucht"],"unbekannt":["Nierenfunktionsstörungen einschliesslich proximaler Tubulopathie (Berichte nach Markteinführung bei Tenofoviralafenamid)"]},"schwangerschaft":"Nicht in der Schwangerschaft beginnen: Die Spiegel von Elvitegravir und Cobicistat sind im 2. und 3. Drittel zu tief – bei Eintritt einer Schwangerschaft auf eine andere Therapie umstellen.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Einmal täglich zu einer Mahlzeit einnehmen.","Antazida und Mineralstoffpräparate (Calcium, Magnesium, Eisen, Zink) mindestens 4 Stunden versetzt einnehmen.","Sehr viele Wechselwirkungen – vor jedem neuen Medikament (auch Asthmasprays, Potenzmittel, pflanzliche Mittel) Rücksprache halten; bei Hepatitis B nicht eigenmächtig absetzen."],"darreichung":["Filmtabletten"]},"emicizumab":{"wirkmechanismus":"Ersetzt die Funktion des bei Hämophilie A fehlenden Gerinnungsfaktors VIII. Emicizumab ist ein humanisierter, bispezifischer IgG4-Antikörper, der gleichzeitig aktivierten Faktor IX und Faktor X bindet und so zusammenbringt. Dadurch wird Faktor X aktiviert und die Gerinnung mit Thrombinbildung fortgesetzt. Da Emicizumab anders gebaut ist als Faktor VIII, wird es durch Faktor-VIII-Hemmkörper nicht neutralisiert.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Rötung, Juckreiz, Schmerzen)","Kopfschmerzen","Gelenkschmerzen (Arthralgie)"],"haeufig":["Fieber","Durchfall","Muskelschmerzen (Myalgie)"],"gelegentlich":["Thrombotische Mikroangiopathie (Schädigung kleiner Blutgefässe, u. a. mit Nierenschaden) bei gleichzeitiger Gabe von aPCC","Thrombosen (z. B. Sinusvenenthrombose) bei gleichzeitiger Gabe von aPCC","Hautnekrose","Oberflächliche Venenentzündung (Thrombophlebitis)","Angioödem (Schwellung von Haut und Schleimhäuten)"]},"schwangerschaft":"Keine Erfahrungen. Nur anwenden, wenn der Nutzen das Risiko eindeutig überwiegt; Frauen im gebärfähigen Alter sollen während und bis 6 Monate nach der Behandlung verhüten.","stillzeit":"Nicht bekannt, ob Emicizumab in die Muttermilch übergeht. Stillen nur nach ärztlicher Abwägung.","hinweise":["Bei jeder Laboruntersuchung und in jedem Notfall die Behandlung angeben (Patientenausweis mitführen): gewisse Gerinnungstests sind verfälscht.","Durchbruchblutungen nur nach Absprache mit dem Hämophiliezentrum mit Bypass-Präparaten behandeln; aPCC möglichst meiden.","Wird je nach Schema wöchentlich, alle 2 oder alle 4 Wochen unter die Haut gespritzt."],"darreichung":["Injektionslösung (subkutan)"]},"empagliflozin":{"wirkmechanismus":"Senkt den Blutzucker, indem die Nieren überschüssigen Zucker mit dem Urin ausscheiden. Empagliflozin hemmt hochselektiv und reversibel den Natrium-Glukose-Cotransporter 2 (SGLT2) im proximalen Nierentubulus und vermindert so die Rückresorption von Glukose; pro Tag gehen etwa 60–80 g Zucker mit dem Urin verloren. Die Wirkung ist unabhängig vom Insulin und geht mit einer leichten osmotischen Diurese, vermehrter Natriumausscheidung und einer mässigen Senkung von Blutdruck und Gewicht einher. Die Schutzwirkung auf Herz und Nieren beruht vermutlich auf der Entlastung des Herzens und der Senkung des Drucks in den Nierenkörperchen (tubuloglomerulärer Feedback).","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) bei Kombination mit Insulin oder Sulfonylharnstoffen"],"haeufig":["Genitalinfektionen wie Scheidenpilz (Vulvovaginitis) oder Eichelentzündung (Balanitis)","Harnwegsinfekte, einschliesslich Nierenbeckenentzündung","Vermehrtes Wasserlassen","Durst","Verstopfung","Juckreiz am ganzen Körper, Hautausschlag","Anstieg der Blutfette"],"gelegentlich":["Volumenmangel (Austrocknung, tiefer Blutdruck)","Nesselsucht (Urtikaria)","Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Schmerzen beim Wasserlassen (Dysurie)","Anstieg von Kreatinin bzw. Abnahme der Nierenfunktion (eGFR), Anstieg des Hämatokrits"],"selten":["Diabetische Ketoazidose (lebensbedrohliche Übersäuerung, auch bei fast normalem Blutzucker)","Fournier-Gangrän (nekrotisierende Fasziitis im Genital- und Dammbereich)"],"sehrSelten":["Tubulointerstitielle Nephritis (Nierenentzündung)"]},"schwangerschaft":"Nicht anwenden: vorsichtshalber während der ganzen Schwangerschaft meiden (Nierenschäden im Tierversuch). Bei Eintritt einer Schwangerschaft ärztlich auf eine andere Behandlung umstellen.","stillzeit":"Nicht anwenden, da Empagliflozin im Tierversuch in die Milch übergeht und ein Risiko für das gestillte Kind nicht ausgeschlossen werden kann.","hinweise":["Der Urin-Zuckertest fällt unter der Behandlung immer positiv aus – zur Kontrolle den Blutzucker messen.","Bei akuten Erkrankungen mit Erbrechen, Durchfall oder wenig Trinken sowie vor grösseren Operationen nach ärztlicher Anweisung pausieren (Ketoazidose- und Austrocknungsgefahr).","Warnzeichen einer Ketoazidose (Übelkeit, Erbrechen, Bauchschmerzen, starker Durst, rasche Atmung, Verwirrtheit, ungewöhnliche Müdigkeit) sofort ärztlich abklären lassen.","Ausreichend trinken und auf Intimhygiene achten; Einnahme einmal täglich, unabhängig von den Mahlzeiten."],"darreichung":["Filmtabletten"]},"emtricitabin":{"wirkmechanismus":"Hemmt die Vermehrung des HI-Virus. Emtricitabin ist ein Abkömmling des Erbgutbausteins Cytidin und wird in den Körperzellen zu Emtricitabin-Triphosphat umgewandelt. Dieses hemmt die virale Reverse Transkriptase und führt nach Einbau in die virale DNA zum Kettenabbruch. Es wirkt auch gegen das Hepatitis-B-Virus.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Durchfall, Übelkeit","Erhöhte Kreatinkinase (CK) im Blut"],"haeufig":["Neutropenie","Allergische Reaktionen","Erhöhter Blutzucker, erhöhte Triglyceride","Schlaflosigkeit, abnorme Träume, Schwindel","Erbrechen, Verdauungsbeschwerden, Bauchschmerzen, erhöhte Pankreasenzyme","Erhöhte Leberwerte und Bilirubin","Ausschlag, Juckreiz, Nesselsucht, Hautverfärbung (dunkle Flecken an Handflächen und Fusssohlen)","Schmerzen, Schwäche"],"gelegentlich":["Anämie","Angioödem"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit angewendet werden; umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Menschen mit HIV wird generell vom Stillen abgeraten; allenfalls nach eingehender Beratung durch die HIV-Fachperson.","hinweise":["Vor Beginn auf Hepatitis B testen lassen; bei Hepatitis B nie eigenmächtig absetzen.","Unabhängig von den Mahlzeiten einnehmen.","Dunkle Hautverfärbungen an Handflächen oder Fusssohlen sind harmlos und kommen vor allem bei Kindern vor."],"darreichung":["Kapseln","Filmtabletten (Kombinationspräparate)"]},"emtricitabin-rilpivirin-tenofoviralafenamid":{"wirkmechanismus":"Drei Wirkstoffe hemmen die Reverse Transkriptase des HI-Virus auf zwei Arten. Rilpivirin (NNRTI) bindet direkt an das Enzym und blockiert das Umschreiben der Virus-RNA in DNA. Emtricitabin (ein Cytidin-Analogon) und Tenofovir (aus dem Prodrug Tenofoviralafenamid, das vor allem in den Zellen aktiviert wird) führen nach Einbau in die Virus-DNA zum Kettenabbruch. Durch die gezielte Aktivierung in den Zellen sind die Tenofovir-Spiegel im Blut viel tiefer als bei Tenofovirdisoproxil, was Niere und Knochen weniger belastet.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Schlaflosigkeit","Übelkeit","Erhöhtes Cholesterin und LDL (nüchtern)","Erhöhte Leberwerte und Pankreas-Amylase"],"haeufig":["Schwindel, Schläfrigkeit","Depression, depressive Verstimmung, Schlafstörungen, abnorme Träume","Bauchschmerzen, Erbrechen, Durchfall, Blähungen, Mundtrockenheit","Verminderter Appetit, erhöhte Triglyceride","Erhöhte Lipase, Bilirubinanstieg","Hautausschlag","Müdigkeit"],"gelegentlich":["Anämie","Immunrekonstitutionssyndrom","Schwere Hautreaktionen mit Allgemeinsymptomen, Angioödem","Juckreiz, Nesselsucht","Gelenkschmerzen"],"unbekannt":["Nierenfunktionsstörungen einschliesslich proximaler Tubulopathie (Berichte nach Markteinführung bei Tenofoviralafenamid)"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen das mögliche Risiko rechtfertigt; die Rilpivirin-Spiegel sind in der Schwangerschaft tiefer – Viruslast engmaschig kontrollieren.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Einmal täglich zu einer Mahlzeit einnehmen – ein Proteindrink allein genügt nicht für eine ausreichende Aufnahme.","Keine Protonenpumpenhemmer (z. B. Omeprazol, Pantoprazol); Antazida und H2-Blocker nur mit dem vorgeschriebenen Zeitabstand.","Bei Hepatitis B nicht eigenmächtig absetzen (Gefahr eines schweren Hepatitis-Schubs)."],"darreichung":["Filmtabletten"]},"emtricitabin-rilpivirin-tenofovirdisoproxil":{"wirkmechanismus":"Drei Wirkstoffe hemmen die Reverse Transkriptase des HI-Virus auf zwei Arten. Rilpivirin (NNRTI) bindet direkt an das Enzym und blockiert das Umschreiben der Virus-RNA in DNA. Emtricitabin (ein Cytidin-Analogon) und Tenofovir (aus dem Prodrug Tenofovirdisoproxil) werden in den Zellen aktiviert und führen nach Einbau in die Virus-DNA zum Kettenabbruch. Emtricitabin und Tenofovir wirken auch gegen Hepatitis B; Rilpivirin braucht für die Aufnahme Magensäure und eine Mahlzeit.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen, Schwindel","Schlaflosigkeit","Übelkeit, Durchfall, Erbrechen","Hautausschlag","Erhöhtes Cholesterin und LDL, Hypophosphatämie (Phosphatmangel)","Erhöhte Leberwerte und Pankreas-Amylase","Erhöhte Kreatinkinase (Muskelenzym)","Schwäche (Asthenie)"],"haeufig":["Depression, depressive Verstimmung, Schlafstörungen, abnorme Träume","Schläfrigkeit","Bauchschmerzen, Blähungen, Mundtrockenheit, Verdauungsbeschwerden","Verminderter Appetit, erhöhte Triglyceride und Blutzucker","Juckreiz, Nesselsucht, Hautverfärbung","Neutropenie, allergische Reaktionen","Bilirubinanstieg","Müdigkeit, Schmerzen"],"gelegentlich":["Anämie","Immunrekonstitutionssyndrom","Schwere Hautreaktionen mit Allgemeinsymptomen, Angioödem","Proximale Tubulopathie der Niere einschliesslich Fanconi-Syndrom, Kreatininanstieg, Eiweiss im Urin","Rhabdomyolyse, Muskelschwäche","Kaliummangel"],"selten":["Laktatazidose (Übersäuerung des Blutes)","Fettleber, Hepatitis","Akutes Nierenversagen, akute Tubulusnekrose, nephrogener Diabetes insipidus","Osteomalazie (Knochenerweichung) mit Knochenschmerzen und Brüchen"]},"schwangerschaft":"Nur anwenden, wenn der Nutzen das mögliche Risiko rechtfertigt; die Rilpivirin-Spiegel sind in der Schwangerschaft tiefer – Viruslast engmaschig kontrollieren.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Einmal täglich zu einer Mahlzeit einnehmen – ein Proteindrink allein genügt nicht für eine ausreichende Aufnahme.","Keine Protonenpumpenhemmer (z. B. Omeprazol, Pantoprazol); Antazida und H2-Blocker nur mit dem vorgeschriebenen Zeitabstand.","Nierenfunktion und Phosphat werden regelmässig kontrolliert; bei Hepatitis B nicht eigenmächtig absetzen."],"darreichung":["Filmtabletten"]},"emtricitabin-tenofoviralafenamid":{"wirkmechanismus":"Hemmt die Vermehrung von HIV. Emtricitabin (ein Cytidin-Analogon) wird in den Zellen zum aktiven Triphosphat phosphoryliert; Tenofoviralafenamid ist eine im Blut stabile Vorstufe, die vor allem in Lymphozyten zu Tenofovir gespalten und zum aktiven Diphosphat umgewandelt wird. Beide werden von der Reversen Transkriptase in die Virus-DNA eingebaut und führen zum Kettenabbruch. Dank der tiefen Tenofovir-Spiegel im Blut werden Nieren und Knochen weniger belastet als mit Tenofovirdisoproxil; beide Wirkstoffe wirken auch gegen das Hepatitis-B-Virus.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Kopfschmerzen, Schwindel","Abnorme Träume","Durchfall, Erbrechen","Bauchschmerzen, Blähungen","Hautausschlag","Müdigkeit"],"gelegentlich":["Anämie","Dyspepsie (Verdauungsbeschwerden)","Angioödem (Schwellung von Haut und Schleimhäuten)","Juckreiz, Nesselsucht","Gelenkschmerzen"]},"schwangerschaft":"In der Schwangerschaft nach Abwägung durch die HIV-Fachperson anwendbar; die bisherigen Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit einnehmen; keine Dosis auslassen.","Bei Hepatitis B nicht eigenmächtig absetzen.","Nierenfunktion regelmässig kontrollieren lassen."],"darreichung":["Filmtabletten"]},"emtricitabin-tenofovirdisoproxil":{"wirkmechanismus":"Hemmt die Vermehrung von HIV und verhindert bei vorbeugender Einnahme, dass sich das Virus nach einer Ansteckung im Körper festsetzt. Emtricitabin (ein Cytidin-Analogon) und Tenofovir (ein Adenosin-Nukleotid-Analogon, aus der Vorstufe Tenofovirdisoproxil freigesetzt) werden in den Zellen zu ihren aktiven Triphosphat- bzw. Diphosphat-Formen umgewandelt. Diese werden von der Reversen Transkriptase in die Virus-DNA eingebaut und führen zum Kettenabbruch. Beide Wirkstoffe wirken auch gegen das Hepatitis-B-Virus.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen","Kopfschmerzen, Schwindel","Hautausschlag","Asthenie (Schwäche)","Hypophosphatämie (zu wenig Phosphat im Blut)","Erhöhte Kreatinkinase (CK)"],"haeufig":["Bauchschmerzen, Verdauungsbeschwerden, Blähungen","Schlaflosigkeit, abnorme Träume","Juckreiz, Nesselsucht, Hautverfärbung (vor allem an Handflächen und Fusssohlen)","Neutropenie (Mangel an weissen Blutkörperchen)","Allergische Reaktionen","Erhöhte Leber-, Bauchspeicheldrüsen-, Blutzucker- oder Triglyceridwerte","Müdigkeit, Schmerzen"],"gelegentlich":["Proximale Tubulopathie der Niere (inkl. Fanconi-Syndrom), Kreatininanstieg, Eiweiss im Urin","Anämie","Hypokaliämie (Kaliummangel)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Angioödem (Schwellung von Haut und Schleimhäuten)","Rhabdomyolyse (Muskelzerfall), Muskelschwäche"],"selten":["Akutes Nierenversagen, Nierenentzündung, nephrogener Diabetes insipidus","Osteomalazie (Knochenerweichung) mit Knochenschmerzen und Brüchen","Laktatazidose (Übersäuerung des Blutes)","Fettleber, Hepatitis"]},"schwangerschaft":"Kann bei Bedarf in der Schwangerschaft angewendet werden; umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Beide Wirkstoffe gehen in die Muttermilch über; gemäss Fachinformation in der Stillzeit nicht anwenden. HIV-positive Mütter sollen grundsätzlich nicht stillen; bei PrEP das Vorgehen mit der Fachperson besprechen.","hinweise":["Mit einer Mahlzeit einnehmen.","PrEP: vor Beginn und danach alle 3 Monate HIV-Test sowie Kontrollen auf sexuell übertragbare Infektionen und der Nierenfunktion; PrEP schützt nicht vor anderen Geschlechtskrankheiten.","Regelmässig einnehmen – vergessene Dosen vermindern Wirkung bzw. Schutz.","Bei Hepatitis B nicht eigenmächtig absetzen."],"darreichung":["Filmtabletten"]},"enalapril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II blockiert. Enalapril ist ein Prodrug, das in der Leber zu Enalaprilat aktiviert wird; dieses hemmt das Angiotensin-Konversionsenzym (ACE). Dadurch sinken Angiotensin II und Aldosteron: Die Gefässe weiten sich, die Niere scheidet mehr Salz und Wasser aus, und Herz und Gefässe werden langfristig entlastet. Weil ACE auch Bradykinin abbaut, steigt dessen Spiegel an – das erklärt Reizhusten und Angioödeme.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Trockener Reizhusten","Übelkeit","Verschwommenes Sehen","Schwäche (Asthenie)"],"haeufig":["Kopfschmerzen, Depression","Hypotonie (tiefer Blutdruck), auch beim Aufstehen; Synkope (Ohnmacht)","Brustschmerzen, Herzrhythmusstörungen, Angina pectoris, beschleunigter Puls","Atemnot","Durchfall, Bauchschmerzen, Geschmacksveränderungen","Hautausschlag; Überempfindlichkeit mit Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen)","Müdigkeit","Hyperkaliämie (erhöhtes Kalium), Kreatininanstieg"],"gelegentlich":["Anämie (Blutarmut)","Hypoglykämie (Unterzuckerung)","Verwirrtheit, Schläfrigkeit, Schlaflosigkeit, Kribbeln, Ohrensausen","Herzinfarkt oder Schlaganfall (infolge starken Blutdruckabfalls bei Risikopatienten)","Pankreatitis (Bauchspeicheldrüsenentzündung), Ileus, Magengeschwür, Erbrechen","Nierenfunktionsstörung, Nierenversagen, Eiweiss im Urin","Juckreiz, Nesselsucht, Haarausfall, vermehrtes Schwitzen, Erektionsstörungen","Hyponatriämie (Natriummangel), Muskelkrämpfe"],"selten":["Neutropenie, Agranulozytose, Thrombozytopenie, Knochenmarkdepression","Leberversagen, Hepatitis, cholestatische Gelbsucht","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme, Pemphigus","Raynaud-Syndrom, Lungeninfiltrate, eosinophile Pneumonie","Autoimmunerkrankungen, Lymphknotenschwellung","Entzündungen der Mundschleimhaut und Zunge"],"sehrSelten":["Intestinales Angioödem (Schwellung der Darmwand mit Bauchschmerzen)"],"unbekannt":["SIADH (Syndrom der inadäquaten ADH-Sekretion)"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über. In den ersten Wochen nach der Geburt und bei Frühgeborenen nicht empfohlen; bei älteren Säuglingen nach ärztlicher Abwägung möglich.","hinweise":["Bei Schwellung von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notruf wählen (Angioödem, auch nach langer Einnahme möglich).","Ein anhaltender trockener Reizhusten ist eine typische Nebenwirkung – ärztlich besprechen, nicht eigenmächtig absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Tabletten"]},"encorafenib":{"wirkmechanismus":"Hemmt ein krankhaft dauerhaft eingeschaltetes Wachstumssignal in Tumorzellen mit BRAF-Mutation. Encorafenib ist ein ATP-kompetitiver Hemmer der mutierten BRAF-V600-Kinase mit sehr langer Bindungsdauer am Zielenzym und blockiert den MAPK-Signalweg (RAF-MEK-ERK). Mit dem MEK-Hemmer Binimetinib wird der Signalweg doppelt gehemmt; bei Darmkrebs verhindert der Antikörper Cetuximab, dass die Tumorzellen die Hemmung über den EGF-Rezeptor umgehen.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit, Fieber, Wassereinlagerungen in den Beinen","Übelkeit, Erbrechen, Durchfall, Verstopfung, Bauchschmerzen","Gelenk- und Muskelschmerzen, erhöhte CK (Muskelenzym)","Sehstörungen, seröse Retinopathie (Flüssigkeit unter der Netzhaut)","Hautausschlag, trockene Haut, Juckreiz, Haarausfall, Hyperkeratose (Hautverhornung)","Kopfschmerzen, Schwindel, periphere Neuropathie (Nervenstörungen)","Bluthochdruck, Blutungen","Blutarmut, erhöhte Leberwerte"],"haeufig":["Plattenepithelkarzinom der Haut, Basalzellkarzinom, Hautpapillome","Venöse Thromboembolien (Thrombose, Lungenembolie)","Verminderte Herzpumpfunktion","Uveitis (Entzündung im Auge)","Gesichtsnervenlähmung, Geschmacksstörung","Lichtempfindlichkeit, Hand-Fuss-Syndrom, Pannikulitis","Nierenversagen, erhöhtes Kreatinin","Überempfindlichkeitsreaktionen"],"gelegentlich":["Neues Melanom","Pankreatitis (Bauchspeicheldrüsenentzündung), Kolitis (Dickdarmentzündung)"],"unbekannt":["QT-Verlängerung im EKG"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig. Frauen im gebärfähigen Alter müssen während und mindestens 1 Monat nach der Behandlung zuverlässig verhüten; hormonale Verhütungsmittel können weniger wirksam sein.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten einnehmen; keine Grapefruit und kein Grapefruitsaft.","Haut, Augen, EKG, Blutdruck, Herzfunktion und Leberwerte regelmässig kontrollieren lassen.","Sehstörungen, Blutungen oder neue Hautveränderungen ärztlich melden."],"darreichung":["Hartkapseln"]},"enfortumab-vedotin":{"wirkmechanismus":"Bringt ein starkes Zellgift gezielt in Krebszellen. Enfortumab Vedotin besteht aus einem Antikörper gegen Nectin-4, ein Haftprotein, das auf den meisten Urothelkarzinomen reichlich vorkommt, und dem daran gekoppelten Zellgift Monomethylauristatin E (MMAE). Nach der Bindung wird das Konjugat in die Zelle aufgenommen; MMAE wird abgespalten und blockiert die Mikrotubuli (Zellskelett). Die Zelle kann sich nicht mehr teilen und stirbt ab (Apoptose).","nebenwirkungen":{"sehrHaeufig":["Periphere Neuropathie (Kribbeln, Taubheit in Händen und Füssen)","Hautausschlag, Juckreiz, trockene Haut","Alopezie (Haarausfall)","Geschmacksstörungen, Appetitlosigkeit, Gewichtsabnahme","Durchfall, Übelkeit, Erbrechen","Trockene Augen","Hyperglykämie (erhöhter Blutzucker)","Müdigkeit, Anämie, erhöhte Leberwerte"],"haeufig":["Pneumonitis (Lungenentzündung durch das Medikament)","Blasenbildende Hautreaktionen, Hand-Fuss-Syndrom","Muskelschwäche, Gangstörungen","Augenentzündungen (Hornhaut, Lider, Bindehaut)","Paravasat-Reaktionen an der Infusionsstelle","Neutropenie (Mangel an Abwehrzellen)"],"unbekannt":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (lebensbedrohliche Hautablösung)","Diabetische Ketoazidose (lebensbedrohliche Stoffwechselentgleisung)"]},"schwangerschaft":"Kann das Ungeborene schädigen (Zellgift MMAE); in der Schwangerschaft nicht anwenden. Frauen und Männer verhüten während und mehrere Monate nach der Behandlung zuverlässig (Dauer gemäss ärztlicher Anweisung).","stillzeit":"Während der Behandlung und einige Zeit danach nicht stillen.","hinweise":["Hautveränderungen, Blasen, wunde Schleimhäute oder Fieber mit Ausschlag sofort melden.","Starker Durst, häufiges Wasserlassen, Müdigkeit oder Verwirrtheit: Blutzucker prüfen lassen.","Gegen trockene Augen Tränenersatzmittel verwenden; Sehstörungen melden.","Kribbeln, Taubheit oder Schwäche in Händen und Füssen melden – die Dosis wird gegebenenfalls angepasst."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"enoxaparin":{"wirkmechanismus":"Hemmt die Blutgerinnung und verhindert so, dass sich Blutgerinnsel bilden oder vergrössern. Enoxaparin ist ein niedermolekulares Heparin, das an den körpereigenen Hemmstoff Antithrombin bindet und dessen Wirkung vor allem gegen den Gerinnungsfaktor Xa, in geringerem Mass auch gegen Thrombin (Faktor IIa), stark verstärkt. Gegenüber unfraktioniertem Heparin ist die Wirkung besser vorhersehbar und hält länger an, sodass ein bis zwei Spritzen unter die Haut pro Tag genügen. Die Ausscheidung erfolgt überwiegend über die Nieren; die Wirkung kann über die Anti-Xa-Aktivität gemessen werden.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Leberwerte (vor allem Transaminasen)"],"haeufig":["Blutungen, Blutarmut infolge Blutungen","Thrombozytopenie (verminderte Blutplättchen) oder Thrombozytose (vermehrte Blutplättchen)","Bluterguss, Schmerzen und andere Reaktionen an der Einstichstelle","Allergische Reaktionen","Kopfschmerzen","Nesselsucht, Juckreiz, Hautrötung"],"gelegentlich":["Hirnblutungen und Blutungen im hinteren Bauchraum (retroperitoneal)","Blasenbildende Hautentzündung","Hautreizung und Hautnekrose an der Einstichstelle","Leberzellschädigung"],"selten":["Anaphylaktische und anaphylaktoide Reaktionen bis Schock","Heparininduzierte Thrombozytopenie Typ II mit Thrombosen (Gefässverschlüsse bis Organinfarkt oder Gliedmassenischämie)","Spinale oder epidurale Hämatome nach rückenmarksnaher Anästhesie","Hyperkaliämie (erhöhtes Kalium)","Gallestauung (cholestatische Leberschädigung)","Haarausfall, Hautgefässentzündung","Osteoporose bei Langzeitanwendung über 3 Monate"]},"schwangerschaft":"Keine Hinweise auf Fruchtschädigung; Enoxaparin passiert die Plazenta im 2. Drittel nicht. Anwendung nur nach ärztlicher Abwägung; Schwangere mit künstlicher Herzklappe brauchen eine besonders enge Überwachung.","stillzeit":"Geht kaum in die Muttermilch über und wird vom Säugling über den Darm nicht aufgenommen; Anwendung in der Stillzeit möglich.","hinweise":["Unter die Haut spritzen (Bauch, abwechselnd links und rechts), nie in den Muskel; die Luftblase in der Fertigspritze nicht entfernen und die Einstichstelle nicht reiben.","Blutplättchen vor und während der Behandlung kontrollieren lassen (heparininduzierte Thrombozytopenie).","Vor Operationen, Zahnbehandlungen und Spinal- oder Periduralanästhesie die Behandlung angeben.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, starke Blutergüsse) oder neuen Thrombosezeichen sofort ärztlichen Rat holen."],"darreichung":["Injektionslösung in Fertigspritzen","Injektionslösung in Durchstechflaschen"]},"entacapon":{"wirkmechanismus":"Verlängert und verstärkt die Wirkung von Levodopa, indem es dessen Abbau im Körper bremst. Entacapon hemmt reversibel und vorwiegend ausserhalb des Gehirns die Catechol-O-Methyltransferase (COMT), die Levodopa zu 3-O-Methyldopa abbaut. Dadurch bleibt der Levodopa-Spiegel im Blut länger erhalten, und mehr Levodopa gelangt ins Gehirn, wo es zu Dopamin umgewandelt wird. Allein eingenommen wirkt Entacapon nicht gegen Parkinson.","nebenwirkungen":{"sehrHaeufig":["Dyskinesien (unwillkürliche Überbewegungen)","Übelkeit","Rotbraune Verfärbung des Urins (harmlos)"],"haeufig":["Schlaflosigkeit, Albträume","Halluzinationen, Verwirrtheit","Verstärkte Parkinson-Symptome, Dystonie (Muskelverkrampfungen), Schwindel","Durchfall, Bauchschmerzen, Verstopfung, Erbrechen, Mundtrockenheit","Angina-pectoris-Beschwerden (Durchblutungsstörung des Herzens)","Müdigkeit, vermehrtes Schwitzen, Stürze"],"gelegentlich":["Herzinfarkt"],"selten":["Hautausschlag","Veränderte Leberwerte"],"sehrSelten":["Unruhe (Agitiertheit)","Appetitlosigkeit, Gewichtsverlust","Nesselsucht (Urtikaria)"],"unbekannt":["Kolitis (Dickdarmentzündung) mit anhaltendem Durchfall","Hepatitis (Leberentzündung), vorwiegend mit Gallenstau","Verfärbung von Haut, Haaren, Bart und Nägeln","Impulskontrollstörungen (z. B. Spielsucht, Kaufsucht)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; während der Schwangerschaft nur anwenden, wenn der Nutzen das mögliche Risiko klar überwiegt.","stillzeit":"Ging im Tierversuch in die Milch über; während der Behandlung nicht stillen.","hinweise":["Immer gleichzeitig mit jeder Levodopa-Dosis einnehmen, mit oder ohne Essen.","Der Urin kann sich rotbraun verfärben – das ist harmlos.","Nicht abrupt absetzen; beim Absetzen muss die Levodopa-Dosis meist ärztlich angepasst werden.","Plötzliches Einschlafen ist möglich – in diesem Fall nicht Auto fahren."],"darreichung":["Filmtabletten"]},"entecavir":{"wirkmechanismus":"Hemmt die Vermehrung des Hepatitis-B-Virus in der Leber. Entecavir ist ein Guanosin-Analogon, das in den Zellen zum aktiven Entecavir-Triphosphat phosphoryliert wird. Dieses konkurriert mit dem natürlichen Baustein Desoxyguanosintriphosphat und hemmt die virale Polymerase an drei Stellen: beim Start der DNA-Synthese (Priming), beim Umschreiben der prägenomischen RNA in DNA und bei der Synthese des zweiten DNA-Strangs. Gegen HIV wirkt es nur schwach, kann aber HIV-Resistenzen fördern.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Müdigkeit","Schwindel","Schläfrigkeit","Schlaflosigkeit","Übelkeit, Erbrechen, Durchfall","Dyspepsie (Verdauungsbeschwerden)","Erhöhte Leberwerte (Transaminasen)"],"gelegentlich":["Hautausschlag","Haarausfall"],"selten":["Anaphylaktoide Reaktion (schwere allergische Reaktion)"],"unbekannt":["Laktatazidose (Übersäuerung des Blutes), vor allem bei dekompensierter Lebererkrankung","Schwere Hepatitisschübe nach dem Absetzen"]},"schwangerschaft":"Nur anwenden, wenn unbedingt nötig (begrenzte Erfahrungen); Frauen im gebärfähigen Alter sollen wirksam verhüten.","stillzeit":"Gemäss Fachinformation nicht stillen (Übergang in die Muttermilch beim Menschen nicht bekannt).","hinweise":["Auf nüchternen Magen einnehmen: mindestens 2 Stunden nach und 2 Stunden vor einer Mahlzeit.","Nicht eigenmächtig absetzen – nach dem Absetzen Leberwerte regelmässig kontrollieren lassen.","Vor Beginn einen HIV-Test machen.","Die Behandlung schützt nicht vor einer Übertragung von Hepatitis B auf andere (z. B. beim Geschlechtsverkehr)."],"darreichung":["Filmtabletten"]},"enterococcus-faecium-sf68":{"wirkmechanismus":"Enthält lebende Milchsäurebakterien, die die Darmflora unterstützen sollen. Enterococcus faecium SF68 siedelt sich vorübergehend im Darm an, bildet Milchsäure und senkt dadurch den pH-Wert. Die Bakterien konkurrieren mit krankmachenden Keimen um Nährstoffe und Haftstellen an der Schleimhaut. Sie werden nicht ins Blut aufgenommen und nach dem Absetzen mit dem Stuhl ausgeschieden.","nebenwirkungen":{},"schwangerschaft":"Schädliche Wirkungen sind nicht bekannt; Anwendung nach Rücksprache mit Ärztin, Arzt oder Apotheke.","stillzeit":"Schädliche Wirkungen sind nicht bekannt; Anwendung nach Rücksprache mit Ärztin, Arzt oder Apotheke.","hinweise":["Kapseln mit etwas Flüssigkeit einnehmen, nicht zusammen mit heissen Getränken oder Speisen (Wärme schädigt die Bakterien).","Während einer Antibiotikabehandlung zeitversetzt zum Antibiotikum einnehmen.","Bei Durchfall viel trinken; hält er länger als 2 Tage an oder treten Fieber oder Blut im Stuhl auf, ärztlich abklären lassen."],"darreichung":["Kapseln"]},"entrectinib":{"wirkmechanismus":"Blockiert Wachstumssignale, die durch bestimmte Genfusionen im Tumor dauerhaft eingeschaltet sind. Entrectinib hemmt die Tyrosinkinasen TRKA, TRKB, TRKC, ROS1 und ALK, die bei NTRK- bzw. ROS1-Genfusionen das Tumorwachstum antreiben; ihre Hemmung führt zum Zelltod. Entrectinib gelangt gut ins Gehirn und wirkt auch bei Hirnmetastasen; der Hauptmetabolit M5 ist ebenfalls aktiv.","nebenwirkungen":{"sehrHaeufig":["Geschmacksstörungen, Schwindel, Kribbeln oder Missempfindungen","Gedächtnis- und Konzentrationsstörungen (kognitive Störungen)","Verstopfung, Durchfall, Übelkeit, Erbrechen","Müdigkeit, Ödeme, Fieber","Gewichtszunahme","Muskel- und Gelenkschmerzen","Blutarmut, erhöhte Leberwerte, erhöhtes Kreatinin","Husten, Atemnot, verschwommenes Sehen"],"haeufig":["Herzinsuffizienz","QT-Verlängerung im EKG, Ohnmacht (Synkope)","Knochenbrüche","Stimmungsstörungen (Angst, Depression)","Lungenentzündung, Pleuraerguss","Hyperurikämie (erhöhte Harnsäure), Flüssigkeitsmangel","Lichtempfindlichkeit der Haut","Harnverhalt, Schluckbeschwerden"],"gelegentlich":["Tumorlyse-Syndrom"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nur bei zwingender Notwendigkeit. Frauen müssen während der Behandlung und bis 5 Wochen danach, Männer mit Partnerin im gebärfähigen Alter bis 3 Monate danach zuverlässig verhüten; bei hormonaler Verhütung zusätzlich eine Barrieremethode.","stillzeit":"Während der Behandlung und bis 7 Tage nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich mit oder ohne Mahlzeit; Kapseln unzerkaut schlucken; keine Grapefruit, kein Johanniskraut.","Schwindel, Gedächtnisstörungen oder Ohnmacht können die Fahrtüchtigkeit beeinträchtigen.","Atemnot, Schwellungen oder rasche Gewichtszunahme melden (Herzinsuffizienz).","Sonnenschutz verwenden."],"darreichung":["Hartkapseln"]},"enzalutamid":{"wirkmechanismus":"Blockiert die Wirkung von Testosteron in Prostatakrebszellen an mehreren Stellen. Enzalutamid bindet mit hoher Affinität an den Androgenrezeptor, verhindert seine Wanderung in den Zellkern, seine Bindung an die DNA und das Anlagern von Ko-Aktivatoren. Dadurch wird das Wachstum androgenabhängiger Tumorzellen gehemmt. Enzalutamid ist ein starker CYP3A4-Induktor und verursacht dadurch viele Wechselwirkungen.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit und Schwäche","Hitzewallungen","Hypertonie (Bluthochdruck)","Stürze","Knochenbrüche"],"haeufig":["Kopfschmerzen","Gedächtnis- und Konzentrationsstörungen","Angst","Restless-Legs-Syndrom","Gynäkomastie, Brustschmerzen","Trockene Haut, Juckreiz","Ischämische Herzkrankheit (z. B. Angina pectoris, Herzinfarkt)"],"gelegentlich":["Krampfanfälle","Leukopenie, Neutropenie","Halluzinationen","Erhöhte Leberwerte"],"unbekannt":["Posteriores reversibles Enzephalopathie-Syndrom (PRES)","QT-Verlängerung","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom)","Gesichts-, Zungen- oder Lippenschwellung","Übelkeit, Erbrechen, Durchfall","Thrombozytopenie"]},"schwangerschaft":"Kontraindiziert; nicht für Frauen bestimmt. Männer sollen mit Kondom und einer zusätzlichen Methode verhüten, wenn die Partnerin schwanger werden kann – während und bis 3 Monate nach der Behandlung.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Kapseln bzw. Tabletten ganz schlucken, mit oder ohne Essen; Schwangere sollen sie nicht berühren.","Wegen vieler Wechselwirkungen jedes neue Medikament mit Ärztin, Arzt oder Apotheke abklären.","Bei Krampfanfall, Verwirrtheit oder Sehstörungen sofort Notfall; vorsichtig beim Autofahren.","Blutdruck regelmässig kontrollieren; Sturzprophylaxe beachten."],"darreichung":["Weichkapseln","Filmtabletten"]},"enzianwurzel-primelblueten-ampferkraut-holunderblueten-eisenkraut":{"wirkmechanismus":"Verflüssigt zähen Schleim und fördert seinen Abtransport aus Nase und Nebenhöhlen. In Labor- und Tierstudien wirkt die Pflanzenkombination sekretolytisch (fördert die Flüssigkeitsabgabe der Schleimhaut und die Tätigkeit der Flimmerhärchen), entzündungshemmend und antiviral. Die Bestandteile Enzianwurzel, Primelblüten, Ampferkraut, Holunderblüten und Eisenkraut enthalten unter anderem Bitterstoffe, Saponine und Flavonoide.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden (Bauchschmerzen, Übelkeit, Blähungen, Durchfall)"],"gelegentlich":["Überempfindlichkeitsreaktionen der Haut (Ausschlag, Rötung, Juckreiz)"],"unbekannt":["Schwere allergische Reaktionen (Angioödem, Atemnot, Gesichtsschwellung)","Schwindel"]},"schwangerschaft":"Mangels ausreichender Daten nicht empfohlen.","stillzeit":"Mangels ausreichender Daten nicht empfohlen.","hinweise":["Dragées unzerkaut mit etwas Flüssigkeit einnehmen; bei empfindlichem Magen nach dem Essen.","Die Tropfen enthalten Alkohol.","Bei anhaltenden oder sich verschlechternden Beschwerden, Fieber oder starken Gesichtsschmerzen ärztlich abklären lassen."],"darreichung":["Überzogene Tabletten (Dragées)","Tropfen (Lösung zum Einnehmen)"]},"epcoritamab":{"wirkmechanismus":"Verbindet körpereigene Abwehrzellen (T-Zellen) mit bösartigen B-Zellen, damit diese zerstört werden. Epcoritamab ist ein bispezifischer IgG1-Antikörper gegen CD20 auf B-Zellen und CD3 auf T-Zellen. Die Bindung aktiviert die T-Zellen, die Zytokine und zytotoxische Proteine freisetzen und die CD20-tragenden Zellen abtöten. Auch gesunde B-Zellen werden über längere Zeit vermindert.","nebenwirkungen":{"sehrHaeufig":["Zytokin-Freisetzungs-Syndrom","Reaktionen an der Injektionsstelle","Neutropenie, Anämie, Thrombozytopenie","Müdigkeit, Fieber","Durchfall, Übelkeit, Bauchschmerzen","Appetitlosigkeit"],"haeufig":["ICANS (immuneffektorzell-assoziiertes Neurotoxizitätssyndrom)","Lungenentzündung, Atemwegsinfekte","Febrile Neutropenie (Fieber bei Mangel an Abwehrzellen)","Tumorlysesyndrom","Tumor-Flare","Elektrolytstörungen (Kalium, Phosphat oder Magnesium zu tief)"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, seltene Hirninfektion)"]},"schwangerschaft":"Kann beim Ungeborenen die B-Zellen vermindern; in der Schwangerschaft nicht empfohlen. Frauen verhüten während und mindestens 4 Monate nach der letzten Dosis.","stillzeit":"Während und mindestens 4 Monate nach der letzten Dosis nicht stillen.","hinweise":["Bei DLBCL wird nach der ersten vollen Dosis 24 Stunden im Spital überwacht; Fieber, Schüttelfrost, Atemnot, Schwindel oder Verwirrtheit sofort melden.","Viel trinken in den Tagen nach den ersten Dosen (Vorbeugung eines Tumorlysesyndroms), wie ärztlich angewiesen.","Infektzeichen umgehend ärztlich abklären lassen.","Patientenkarte immer mitführen."],"darreichung":["Injektionslösung zur subkutanen Anwendung"]},"ephedrin":{"wirkmechanismus":"Hebt den Blutdruck, indem es Herz und Gefässe anregt. Ephedrin setzt vor allem Noradrenalin aus den Nervenendigungen frei (indirekte Wirkung) und stimuliert zusätzlich direkt Alpha- und Beta-Rezeptoren. Dadurch steigen Herzfrequenz, Schlagkraft und Gefässtonus. Bei wiederholter Gabe lässt die Wirkung nach (Tachyphylaxie), weil die Noradrenalinspeicher erschöpft werden.","nebenwirkungen":{"unbekannt":["Herzklopfen, Herzrasen (Tachykardie), Blutdruckanstieg","Herzrhythmusstörungen","Unruhe, Angst, Verwirrtheit, Schlaflosigkeit, Zittern","Kopfschmerzen, Schwitzen","Übelkeit, Erbrechen","Atemnot","Harnverhalt","Akuter Glaukomanfall (Engwinkelglaukom)"]},"schwangerschaft":"Kann zur Behandlung eines Blutdruckabfalls bei einer Spinalanästhesie für den Kaiserschnitt eingesetzt werden; hohe Dosen können beim Kind eine Übersäuerung (Azidose) begünstigen.","stillzeit":"Geht in die Muttermilch über; beim Säugling wurden Unruhe und Schlafstörungen beschrieben. Stillen nach der Gabe nur nach ärztlicher Rücksprache.","hinweise":["Wird nur durch Fachpersonal im Spital, meist während einer Narkose, unter Blutdruck- und Pulskontrolle gespritzt.","Ephedrin steht auf der Dopingliste."],"darreichung":["Injektionslösung (Ampullen, Fertigspritzen)"]},"epinastin":{"wirkmechanismus":"Lindert Juckreiz und Rötung bei Augenallergien. Epinastin blockiert den Histamin-H1-Rezeptor und hat zusätzlich Affinität zum H2-Rezeptor sowie zu Alpha-1-, Alpha-2- und 5-HT2-Rezeptoren. Ausserdem stabilisiert es Mastzellen und hemmt so die Freisetzung von Entzündungsbotenstoffen. Es überwindet die Blut-Hirn-Schranke nicht.","nebenwirkungen":{"haeufig":["Brennen im Auge, Augenreizung"],"gelegentlich":["Augenrötung, Augenausfluss","Trockenes Auge, Augenjucken","Sehstörungen","Kopfschmerzen","Nasenreizung, Schnupfen","Geschmacksstörung"],"unbekannt":["Vermehrter Tränenfluss, Augenschmerzen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung anwenden; Daten beim Menschen fehlen.","stillzeit":"Im Tierversuch geht Epinastin in die Milch über; nur nach ärztlicher Abwägung anwenden.","hinweise":["Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen.","Nach dem Eintropfen kann das Sehen kurz verschwommen sein – erst danach Auto fahren.","Andere Augentropfen mit mindestens 5 Minuten Abstand anwenden."],"darreichung":["Augentropfen"]},"epirubicin":{"wirkmechanismus":"Schädigt das Erbgut von Krebszellen und verhindert so deren Teilung. Epirubicin lagert sich zwischen die DNA-Basenpaare ein, hemmt die Topoisomerase II und bildet freie Radikale; dadurch werden DNA- und RNA-Synthese gehemmt. Als Stereoisomer von Doxorubicin wird es rascher abgebaut (u. a. durch Glucuronidierung) und ist bei vergleichbarer Wirkung etwas weniger herzschädigend. Die kumulative Herzschädigung bleibt dennoch dosisbegrenzend.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung: Leukopenie, Neutropenie, Anämie, febrile Neutropenie","Haarausfall","Rotfärbung des Urins 1–2 Tage nach der Gabe","Ausbleiben der Regelblutung (Amenorrhö)"],"haeufig":["Infektionen","Übelkeit, Erbrechen, Durchfall","Mukositis, Stomatitis, Ösophagitis (Schleimhautentzündungen)","Appetitlosigkeit, Austrocknung","Hitzewallungen","Rötung an der Infusionsstelle","Nach Blasenspülung: chemische Blasenentzündung, teils mit Blutungen; allergische Reaktionen"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Venenentzündung (Phlebitis, Thrombophlebitis)"],"selten":["Herzschwäche, ventrikuläre Tachykardie, AV-Block, Bradykardie","Akute Leukämie (Zweiterkrankung)","Anaphylaxie (schwere allergische Reaktion)","Nesselsucht","Fieber, Schüttelfrost, Unwohlsein","Erhöhte Harnsäure, veränderte Leberwerte","Azoospermie (fehlende Spermien)"],"unbekannt":["Asymptomatische Abnahme der Herzpumpfunktion (LVEF)","Blutungen","Schock, Embolien","Haut- und Nagelverfärbung, Lichtempfindlichkeit, Strahlen-Recall-Reaktion","Gewebsnekrose bei Paravasat"]},"schwangerschaft":"Fruchtschädigend; in der Schwangerschaft nur bei zwingender Indikation. Frauen und Männer müssen während und mehrere Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Der Urin kann sich 1–2 Tage nach der Gabe rot verfärben – das ist harmlos.","Herzfunktion vor Beginn und regelmässig kontrollieren; Atemnot, Herzklopfen oder geschwollene Beine melden.","Die Einnahme von Cimetidin (Magenmittel) angeben – es muss während der Behandlung abgesetzt werden.","Bei der Blasenspülung die Anweisungen zu Trinkmenge und Verweildauer der Lösung genau befolgen."],"darreichung":["Injektionslösung (auch zur Blasenspülung)"]},"eplerenon":{"wirkmechanismus":"Entlastet das Herz, indem es die schädlichen Wirkungen des Hormons Aldosteron blockiert. Eplerenon bindet selektiv an den Mineralokortikoid-Rezeptor und verhindert so, dass Aldosteron Salz- und Wasserrückhaltung, Kaliumverlust sowie Umbau- und Vernarbungsprozesse an Herz und Gefässen fördert. Im Gegensatz zu Spironolacton bindet es kaum an Androgen- und Progesteronrezeptoren, weshalb hormonelle Nebenwirkungen wie eine Brustvergrösserung selten sind. Eplerenon wird fast ausschliesslich über CYP3A4 abgebaut.","nebenwirkungen":{"haeufig":["Hyperkaliämie (erhöhtes Kalium), erhöhtes Cholesterin","Schwindel, Ohnmacht (Synkope), Kopfschmerzen, Schlaflosigkeit","Hypotonie (niedriger Blutdruck)","Verschlechterung der Herzinsuffizienz, Vorhofflimmern","Husten","Durchfall, Übelkeit, Erbrechen, Verstopfung","Hautausschlag, Juckreiz, Muskelkrämpfe, Rückenschmerzen","Eingeschränkte Nierenfunktion, Anstieg von Kreatinin und Harnstoff","Schwäche (Asthenie)"],"gelegentlich":["Hyponatriämie (Natriummangel), Flüssigkeitsmangel, erhöhte Triglyceride","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Schnellerer Puls, Blutdruckabfall beim Aufstehen, arterielle Thrombose in den Beinen","Gynäkomastie (Brustvergrösserung beim Mann)","Schilddrüsenunterfunktion","Gallenblasenentzündung","Nierenbeckenentzündung, Rachenentzündung","Vermehrtes Schwitzen, Unwohlsein","Angioödem (Schwellung von Haut und Schleimhäuten)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach sorgfältiger ärztlicher Abwägung anwenden.","stillzeit":"Nicht bekannt, ob Eplerenon in die Muttermilch übergeht; entweder abstillen oder die Behandlung absetzen.","hinweise":["Kalium vor Beginn, in der ersten Woche, nach einem Monat und danach regelmässig kontrollieren lassen.","Keine Kaliumpräparate, kaliumhaltigen Salzersatzmittel oder NSAR ohne ärztliche Rücksprache.","Vor jedem neuen Medikament, besonders Antibiotika und Pilzmitteln, auf Eplerenon hinweisen (CYP3A4-Wechselwirkungen)."],"darreichung":["Filmtabletten"]},"eplontersen":{"wirkmechanismus":"Verringert in der Leber die Herstellung des Eiweisses Transthyretin, das sich bei der Amyloidose in Nerven und Herz ablagert. Eplontersen ist ein kurzes, chemisch verändertes Antisense-Oligonukleotid, das an N-Acetylgalactosamin (GalNAc) gekoppelt ist und so gezielt in Leberzellen gelangt. Es bindet an die Boten-RNA von Transthyretin und führt über das Enzym RNase H1 zu deren Abbau – bei der normalen wie der mutierten Form. Mit dem Transthyretin sinkt auch der Vitamin-A-Spiegel im Blut.","nebenwirkungen":{"sehrHaeufig":["Verminderter Vitamin-A-Spiegel im Blut"],"haeufig":["Erbrechen","Reaktionen an der Injektionsstelle (Rötung, Schmerz, Juckreiz)"]},"schwangerschaft":"Nicht empfohlen. Sowohl ein zu tiefer als auch ein zu hoher Vitamin-A-Spiegel kann dem ungeborenen Kind schaden; vor Behandlungsbeginn Schwangerschaft ausschliessen.","stillzeit":"Nicht bekannt, ob Eplontersen in die Muttermilch übergeht; Stillen nur nach ärztlicher Abwägung.","hinweise":["Einmal monatlich unter die Haut spritzen; nach Schulung auch durch die Patientin oder den Patienten selbst.","Täglich Vitamin A in der empfohlenen Menge ergänzen.","Augenbeschwerden wie Nachtblindheit oder trockene Augen ärztlich melden."],"darreichung":["Injektionslösung im Fertigpen"]},"epoetin-alfa":{"wirkmechanismus":"Regt das Knochenmark an, mehr rote Blutkörperchen zu bilden. Epoetin alfa hat dieselbe Aminosäuresequenz wie das körpereigene Hormon Erythropoetin, das normalerweise vor allem in den Nieren gebildet wird. Es bindet an Erythropoetin-Rezeptoren auf Vorläuferzellen der roten Blutkörperchen im Knochenmark und fördert deren Vermehrung und Ausreifung. Nach einigen Tagen steigen die jungen roten Blutkörperchen (Retikulozyten), nach Wochen das Hämoglobin; dafür muss genügend Eisen vorhanden sein.","nebenwirkungen":{"sehrHaeufig":["Fieber","Übelkeit"],"haeufig":["Bluthochdruck","Venöse und arterielle Thrombosen (z. B. Shunt-Thrombose bei Dialyse)","Kopfschmerzen","Husten","Erbrechen, Durchfall","Gelenk-, Knochen- und Muskelschmerzen","Grippeähnliche Beschwerden, Schüttelfrost","Hautausschlag, Reaktionen an der Injektionsstelle, Wassereinlagerungen"],"gelegentlich":["Krampfanfälle","Hyperkaliämie (erhöhtes Kalium)","Nesselsucht","Überempfindlichkeitsreaktionen"],"selten":["Erythroblastopenie (PRCA) durch Antikörper gegen Erythropoetin, v. a. nach Spritzen unter die Haut bei Nierenkranken"],"unbekannt":["Hypertensive Krise mit Hirnfunktionsstörung (Enzephalopathie)","Herzinfarkt, Schlaganfall, Lungenembolie","Anaphylaxie, Angioödem (Schwellung von Gesicht und Rachen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung; die Erfahrungen sind begrenzt. Bei schwangeren Frauen nicht zur Eigenblutspende vor Operationen empfohlen.","stillzeit":"Nicht bekannt, ob Epoetin in die Muttermilch übergeht; Anwendung nur nach Abwägung.","hinweise":["Blutdruck regelmässig messen; bei starken Kopfschmerzen, Verwirrtheit oder Sehstörungen sofort ärztliche Hilfe holen.","Hämoglobin und Eisenwerte werden regelmässig kontrolliert; meist ist zusätzlich Eisen nötig.","Fertigspritzen im Kühlschrank (2–8 °C) lagern, nicht einfrieren oder schütteln.","Missbrauch als Dopingmittel ist verboten und gefährlich (Thrombosen, Herzinfarkt)."],"darreichung":["Injektionslösung in Fertigspritzen (Spritze unter die Haut oder in die Vene)"]},"epoetin-beta":{"wirkmechanismus":"Regt das Knochenmark an, mehr rote Blutkörperchen zu bilden – wie das körpereigene Hormon Erythropoetin, das bei Nierenschwäche zu wenig gebildet wird. Epoetin beta ist gentechnisch hergestelltes humanes Erythropoetin und bindet an den Erythropoetin-Rezeptor auf Vorläuferzellen der roten Blutkörperchen. Dadurch werden deren Überleben, Vermehrung und Reifung gefördert; Retikulozyten, Hämoglobin und Hämatokrit steigen an. Für die Wirkung muss genügend Eisen vorhanden sein.","nebenwirkungen":{"haeufig":["Blutdruckanstieg (Hypertonie)","Kopfschmerzen","Thromboembolische Ereignisse (z. B. Venenthrombose, Lungenembolie) bei Krebspatienten"],"unbekannt":["Hypertensive Krise mit Hirnfunktionsstörung und Krampfanfällen","Shunt-Thrombose bei Dialysepatienten","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Nesselsucht) bis Anaphylaxie","Erythroblastopenie (Pure Red Cell Aplasia: Ausfall der Bildung roter Blutkörperchen durch Antikörper)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Grippeähnliche Beschwerden zu Behandlungsbeginn"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen; Tierstudien ohne Hinweis auf direkte Schädigung. Nur nach sorgfältiger ärztlicher Abwägung anwenden.","stillzeit":"Nicht bekannt, ob Epoetin beta in die Muttermilch übergeht. Stillen nur nach ärztlicher Abwägung.","hinweise":["Blutdruck und Hämoglobin regelmässig kontrollieren; das Hämoglobin soll langsam steigen (nicht mehr als 2 g/dl in 4 Wochen).","Eisenstatus vor und während der Behandlung prüfen und bei Bedarf Eisen ergänzen.","Fertigspritzen im Kühlschrank lagern.","Steht auf der Dopingliste – im Wettkampfsport verboten."],"darreichung":["Injektionslösung in Fertigspritze (subkutan oder intravenös)"]},"epoprostenol":{"wirkmechanismus":"Erweitert die Blutgefässe der Lunge und entlastet so das rechte Herz. Epoprostenol ist synthetisch hergestelltes Prostacyclin und aktiviert Prostacyclin-(IP-)Rezeptoren; der Anstieg von cAMP entspannt die glatte Gefässmuskulatur in Lungen- und Körperkreislauf. Zusätzlich hemmt es stark die Verklumpung der Blutplättchen. Wegen einer Halbwertszeit von nur wenigen Minuten muss es ohne Unterbruch über einen zentralen Venenkatheter infundiert werden.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Gesichtsrötung (Flush)","Übelkeit, Erbrechen","Durchfall","Kieferschmerzen"],"haeufig":["Sepsis und Katheterinfektionen","Thrombozytopenie (Mangel an Blutplättchen), Blutungen","Blutdruckabfall (Hypotonie)","Herzrasen oder verlangsamter Puls","Bauchkrämpfe","Hautausschlag","Gelenkschmerzen, Brustschmerzen","Angst, Nervosität"],"gelegentlich":["Schwitzen","Mundtrockenheit"],"unbekannt":["Lungenödem","Aszites (Bauchwasser)","Vergrösserte Milz","Herzinsuffizienz mit hohem Herzzeitvolumen"]},"schwangerschaft":"Nur bei klarer Notwendigkeit; eine pulmonale Hypertonie ist in der Schwangerschaft sehr gefährlich, deshalb wirksame Verhütung und spezialisierte ärztliche Begleitung.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen; während der Behandlung nicht stillen.","hinweise":["Dauerinfusion mit tragbarer Pumpe über einen zentralen Venenkatheter: Unterbrechungen unbedingt vermeiden, Ersatzpumpe und Infusionsmaterial bereithalten.","Katheter steril pflegen; Fieber, Rötung oder Schmerzen an der Austrittsstelle sofort melden.","Dosis nur nach ärztlicher Anweisung ändern; Schwindel beim Aufstehen kann auf zu tiefen Blutdruck hinweisen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"eptacog-alfa-aktiviert":{"wirkmechanismus":"Löst die Blutgerinnung direkt an der Verletzungsstelle aus und umgeht dabei die fehlenden oder blockierten Faktoren VIII und IX. In therapeutischer Dosis bindet Faktor VIIa an den freigelegten Gewebefaktor und an die Oberfläche aktivierter Blutplättchen und aktiviert dort direkt Faktor X. So entsteht rasch viel Thrombin, das ein stabiles Fibringerinnsel ermöglicht. Die Wirkung hält nur wenige Stunden an, weshalb oft wiederholte Gaben nötig sind.","nebenwirkungen":{"gelegentlich":["Venöse Thromboembolien (tiefe Venenthrombose, Lungenembolie)","Hautausschlag, Juckreiz, Nesselsucht","Fieber","Verminderte Wirksamkeit"],"selten":["Arterielle Thromboembolien (Herzinfarkt, Schlaganfall)","Disseminierte intravasale Gerinnung (Verbrauchskoagulopathie)","Angina pectoris (Brustenge)","Überempfindlichkeitsreaktionen","Kopfschmerzen","Übelkeit","Erhöhte Leberwerte"],"unbekannt":["Anaphylaktische Reaktion (schwere allergische Reaktion)","Angioödem (Schwellung von Haut und Schleimhäuten)","Hitzegefühl (Flush)","Blutgerinnsel im Herzen (intrakardialer Thrombus)"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden; begrenzte Erfahrungen zeigen keine Schädigung des Kindes.","stillzeit":"Unbekannt, ob Eptacog alfa in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Wird als rasche Injektion in die Vene gegeben; wegen der kurzen Wirkdauer sind oft mehrere Gaben nötig.","Bei Zeichen einer Thrombose (Brustschmerz, Atemnot, Lähmungen, Beinschwellung) sofort den Notfall aufsuchen.","Bei Heimbehandlung Dosis und Zeitpunkt jeder Gabe dokumentieren; Blutungen, die nicht ansprechen, rasch ärztlich abklären lassen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"eptifibatid":{"wirkmechanismus":"Verhindert, dass Blutplättchen miteinander verkleben und ein Gerinnsel in den Herzkranzgefässen bilden. Eptifibatid ist ein ringförmiges Peptid, das reversibel den Glykoprotein-IIb/IIIa-Rezeptor auf den Blutplättchen blockiert, über den Fibrinogen und von-Willebrand-Faktor die Plättchen vernetzen. Damit wird der gemeinsame Endweg der Plättchenaggregation gehemmt, unabhängig vom Auslöser. Nach Ende der Infusion normalisiert sich die Plättchenfunktion innerhalb von etwa 4–8 Stunden.","nebenwirkungen":{"sehrHaeufig":["Blutungen (v. a. an der Punktionsstelle, auch Magen-Darm-, Harnwegs-, Zahnfleisch- und Nasenbluten)","Abfall des Hämoglobins (Blutverlust)"],"haeufig":["Blutdruckabfall (Hypotonie)","Phlebitis (Venenentzündung)"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Zerebrale Ischämie (Durchblutungsstörung des Gehirns)"],"sehrSelten":["Tödliche Blutungen, Hirn- und Lungenblutung","Akuter schwerer Abfall der Blutplättchen","Anaphylaxie (schwere allergische Reaktion)","Hautausschlag, Nesselsucht"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn klar notwendig.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird nur im Spital als Injektion und Infusion gegeben, in der Regel zusammen mit ASS und Heparin.","Blutbild, Thrombozyten und Gerinnungswerte werden vor und während der Behandlung kontrolliert.","Blutungen, schwarzen Stuhl, Blut im Urin oder plötzliche starke Kopfschmerzen sofort melden."],"darreichung":["Injektionslösung","Infusionslösung"]},"eptinezumab":{"wirkmechanismus":"Vermindert die Zahl der Migränetage, indem es einen Botenstoff abfängt, der bei Migräne Gefässerweiterung und Schmerz auslöst. Eptinezumab ist ein humanisierter monoklonaler IgG1-Antikörper, der den Liganden CGRP (Calcitonin Gene-Related Peptide, alpha- und beta-Form) bindet und so dessen Andocken an den Rezeptor verhindert. Durch die Gabe in die Vene ist der Wirkstoff sofort vollständig verfügbar, die Wirkung kann bereits am Tag nach der Infusion einsetzen. Der Abbau erfolgt wie bei anderen Eiweissen durch Proteolyse, nicht über Leberenzyme.","nebenwirkungen":{"haeufig":["Nasopharyngitis (Erkältungssymptome)","Überempfindlichkeitsreaktionen (Ausschlag, Juckreiz, Nesselsucht, Hautrötung, Schwellung)","Müdigkeit"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Nur begrenzte Daten; vorsichtshalber während der Schwangerschaft vermeiden.","stillzeit":"Keine Daten; Antikörper gehen vor allem in den ersten Tagen nach der Geburt in die Muttermilch über – Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird alle 12 Wochen als etwa 30-minütige Infusion in Praxis oder Spital gegeben; danach kurz auf allergische Reaktionen achten.","Der Nutzen wird nach einigen Monaten ärztlich überprüft.","Mittel zur Behandlung akuter Migräneanfälle bleiben weiterhin nötig.","Keine Wechselwirkungen über Leberenzyme bekannt; andere Medikamente können in der Regel weiter eingenommen werden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"erdafitinib":{"wirkmechanismus":"Bremst das Wachstum von Krebszellen, die durch ein verändertes Wachstumssignal angetrieben werden. Erdafitinib hemmt die Tyrosinkinasen der Fibroblasten-Wachstumsfaktor-Rezeptoren FGFR1 bis FGFR4. Bei Tumoren mit aktivierenden FGFR3-Mutationen oder -Fusionen werden dadurch Signalwege für Zellteilung und Überleben blockiert. Weil FGFR auch den Phosphathaushalt steuert, steigt unter der Behandlung typischerweise das Phosphat im Blut an.","nebenwirkungen":{"sehrHaeufig":["Hyperphosphatämie (erhöhtes Phosphat im Blut)","Stomatitis (Entzündung der Mundschleimhaut), Mundtrockenheit","Durchfall","Nagelveränderungen (Nagelablösung, Nagelbettentzündung)","Hand-Fuss-Syndrom (schmerzhafte Rötung von Handflächen und Fusssohlen), trockene Haut, Haarausfall","Trockene Augen","Zentrale seröse Retinopathie (Flüssigkeitsansammlung unter der Netzhaut)","Geschmacksstörungen, Appetitverlust, erhöhte Leberwerte"],"haeufig":["Konjunktivitis (Bindehautentzündung), Keratitis (Hornhautentzündung)","Verschwommenes Sehen, vermehrter Tränenfluss"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nur bei zwingender Notwendigkeit. Frauen im gebärfähigen Alter und Männer mit Partnerin im gebärfähigen Alter müssen während der Behandlung und bis 1 Monat danach zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 1 Monat nach der letzten Dosis nicht stillen.","hinweise":["Tabletten unzerkaut mit oder ohne Mahlzeit einnehmen.","Das Phosphat im Blut wird regelmässig kontrolliert; phosphatreiche Lebensmittel und Phosphatzusätze (z. B. in Fertiggerichten, Cola) einschränken.","Sehstörungen sofort melden; regelmässige augenärztliche Kontrollen. Gegen trockene Augen benetzende Augentropfen verwenden.","Kein Johanniskraut; neue Medikamente nur nach Rücksprache."],"darreichung":["Filmtabletten"]},"erenumab":{"wirkmechanismus":"Beugt Migräneanfällen vor, indem es die Andockstelle eines Botenstoffs blockiert, der bei der Migräne Gefässerweiterung und Schmerz vermittelt. Erenumab ist ein vollständig humaner IgG2-Antikörper, der hochaffin an den Rezeptor für CGRP (Calcitonin Gene-Related Peptide) bindet und dessen Aktivierung verhindert. Als Eiweiss wird es nicht über Leberenzyme (CYP) abgebaut, sondern wie körpereigene Antikörper zerlegt; die lange Halbwertszeit erlaubt eine Gabe alle 4 Wochen.","nebenwirkungen":{"haeufig":["Reaktionen an der Injektionsstelle (Schmerzen, Rötung, Juckreiz)","Obstipation (Verstopfung)","Muskelkrämpfe","Pruritus (Juckreiz)","Überempfindlichkeitsreaktionen (Ausschlag, Schwellungen, Nesselsucht)"],"unbekannt":["Schwere Verstopfung mit Komplikationen","Blutdruckanstieg (Hypertonie)","Schwere allergische Reaktionen (Anaphylaxie, Angioödem)","Mundgeschwüre, Mundschleimhautentzündung","Haarausfall"]},"schwangerschaft":"Nur begrenzte Erfahrungen; aus Vorsicht während der Schwangerschaft nicht anwenden.","stillzeit":"Unbekannt, ob Erenumab in die Muttermilch übergeht; besonders in den ersten Tagen nach der Geburt möglich – nur nach ärztlicher Abwägung.","hinweise":["Den Fertigpen vor der Injektion etwa 30 Minuten bei Raumtemperatur liegen lassen; im Kühlschrank lagern, nicht einfrieren.","Die Wirkung wird nach etwa 3 Monaten ärztlich beurteilt; Akutmittel gegen Migräneanfälle weiter wie verordnet verwenden.","Anhaltende oder starke Verstopfung und steigende Blutdruckwerte ärztlich melden."],"darreichung":["Injektionslösung im Fertigpen (subkutan)"]},"eribulin":{"wirkmechanismus":"Verhindert, dass sich Krebszellen teilen. Eribulin ist ein synthetischer Abkömmling von Halichondrin B, einem Naturstoff aus Meeresschwämmen. Es hemmt das Wachstum der Mikrotubuli (Bestandteile des Zellskeletts) und bindet Tubulin in nicht funktionsfähigen Aggregaten. Dadurch wird der Spindelapparat gestört, die Zellen bleiben in der Teilung stecken (G2/M-Block) und sterben ab.","nebenwirkungen":{"sehrHaeufig":["Neutropenie (Mangel an weissen Blutkörperchen), Leukopenie, Anämie","Periphere Neuropathie (Kribbeln, Taubheit in Händen und Füssen)","Haarausfall","Müdigkeit, Schwäche, Fieber","Übelkeit, Verstopfung, Durchfall, Erbrechen","Appetitlosigkeit, Gewichtsverlust","Gelenk-, Muskel- und Rückenschmerzen","Atemnot, Husten, Kopfschmerzen"],"haeufig":["Febrile Neutropenie (Fieber bei Neutropenie), Thrombozytopenie","Infektionen (Harnwege, Lungenentzündung, Mundsoor)","Kalium- und Magnesiummangel","Mundschleimhautentzündung, Geschmacksstörungen","Schwindel, Schlaflosigkeit, Depression","Erhöhte Leberwerte","Hautausschlag, Hand-Fuss-Syndrom","Lungenembolie, Herzrasen"],"gelegentlich":["Sepsis (Blutvergiftung)","Interstitielle Lungenerkrankung","Tiefe Venenthrombose","Angioödem (Schwellung von Haut und Schleimhäuten)","Nierenversagen, Eiweiss oder Blut im Urin"],"selten":["Disseminierte intravasale Gerinnung (lebensbedrohliche Gerinnungsstörung)","Pankreatitis (Bauchspeicheldrüsenentzündung)"],"unbekannt":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","QT-Verlängerung im EKG"]},"schwangerschaft":"Nicht anwenden, ausser wenn eindeutig erforderlich (im Tierversuch fruchtschädigend). Frauen und Männer müssen während und noch einige Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Vor jeder Gabe wird das Blutbild kontrolliert; Fieber über 38 °C oder Infektzeichen sofort melden.","Kribbeln oder Taubheit in Händen und Füssen melden (Dosisanpassung möglich).","Haarausfall ist häufig und meist vorübergehend."],"darreichung":["Injektionslösung"]},"erlotinib":{"wirkmechanismus":"Blockiert ein Enzym, über das Krebszellen Wachstumssignale erhalten. Erlotinib hemmt reversibel die Tyrosinkinase des epidermalen Wachstumsfaktor-Rezeptors (EGFR, HER1), indem es mit ATP um die Bindungsstelle konkurriert; dadurch werden Teilung und Überleben der Tumorzellen gebremst. Bei Tumoren mit aktivierenden EGFR-Mutationen ist die Wirkung besonders ausgeprägt.","nebenwirkungen":{"sehrHaeufig":["Hautausschlag (oft akneähnlich), Juckreiz, trockene Haut","Durchfall","Appetitlosigkeit, Übelkeit, Erbrechen, Stomatitis (Mundschleimhautentzündung)","Müdigkeit","Atemnot, Husten","Infektionen","Bindehautentzündung, trockenes Auge"],"haeufig":["Magen-Darm-Blutungen, Nasenbluten","Haarausfall, Paronychie (Nagelbettentzündung)","Keratitis (Hornhautentzündung)","Erhöhte Leberwerte"],"gelegentlich":["Interstitielle Lungenerkrankung (teils tödlich)","Magen-Darm-Durchbruch (Perforation)","Veränderungen der Wimpern, vermehrte Körperbehaarung"],"selten":["Leberversagen"],"sehrSelten":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Hornhautgeschwür oder -durchbruch"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen während und mindestens 2 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und mindestens 2 Wochen danach nicht stillen.","hinweise":["Nüchtern einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach dem Essen.","Rauchen senkt die Wirkstoffspiegel deutlich – ein Rauchstopp wird empfohlen.","Haut pflegen und vor Sonne schützen; starken Ausschlag oder Durchfall früh melden.","Plötzliche Atemnot, Husten oder Fieber sofort ärztlich abklären."],"darreichung":["Filmtabletten"]},"ertapenem":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Ertapenem bindet an die Penicillin-bindenden Proteine (vor allem PBP 2 und 3) und hemmt die Quervernetzung des Zellwandbausteins Peptidoglykan. Es ist gegen die meisten Betalaktamasen einschliesslich ESBL stabil. Anders als andere Carbapeneme wirkt es kaum gegen Pseudomonas, Acinetobacter und Enterokokken; dank langer Halbwertszeit genügt eine Gabe pro Tag.","nebenwirkungen":{"haeufig":["Durchfall, Übelkeit, Erbrechen","Kopfschmerzen","Hautausschlag, Juckreiz","Venenentzündung oder Reizung an der Infusionsstelle","Erhöhte Leberwerte"],"gelegentlich":["Schwindel, Schläfrigkeit, Schlaflosigkeit, Verwirrtheit","Krampfanfälle","Blutdruckabfall, Atemnot","Pilzinfektionen im Mund (Soor), Verstopfung, Verdauungsbeschwerden","Clostridioides-difficile-assoziierter Durchfall","Nesselsucht, Hautrötung","Erhöhte Bilirubin- und Kreatininwerte"],"selten":["Neutropenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Allergische Reaktionen","Unruhe, Angst, Depression","Hypoglykämie (Unterzuckerung)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Halluzinationen, Bewusstseinsveränderungen, Aggression, Delir","Muskelzuckungen (Myoklonien), Zittern, Gangstörung, Muskelschwäche","DRESS und akute generalisierte exanthematische Pustulose (schwere Hautreaktionen)","Zahnverfärbungen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen bei Schwangeren. Anwendung nur, wenn der Nutzen das mögliche Risiko für das Kind klar überwiegt.","stillzeit":"Geht in die Muttermilch über. Nur nach ärztlicher Nutzen-Risiko-Abwägung anwenden.","hinweise":["Wird einmal täglich als Infusion gegeben (im Spital oder ambulant); Dosis bei schwacher Nierenfunktion angepasst.","Unbedingt angeben, wenn Valproinsäure eingenommen wird oder eine Antibiotika-Allergie besteht.","Bei starkem oder anhaltendem Durchfall – auch nach Behandlungsende – ärztliche Hilfe holen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"ertugliflozin":{"wirkmechanismus":"Senkt den Blutzucker, indem die Nieren mehr Zucker mit dem Urin ausscheiden. Ertugliflozin hemmt selektiv den Natrium-Glucose-Cotransporter 2 (SGLT2) im proximalen Nierentubulus, der normalerweise den grössten Teil der gefilterten Glucose zurück ins Blut holt. Die Wirkung ist unabhängig vom Insulin; zusätzlich gehen Kalorien sowie etwas Salz und Wasser verloren, was Gewicht und Blutdruck leicht senkt. Abgebaut wird Ertugliflozin vor allem durch Glucuronidierung (UGT1A9, UGT2B7).","nebenwirkungen":{"sehrHaeufig":["Pilzinfektionen der Scheide und andere genitale Pilzinfektionen bei Frauen"],"haeufig":["Pilzinfektion oder Entzündung der Eichel (Balanitis) bei Männern","Hypoglykämie (Unterzuckerung) in Kombination mit Insulin oder Sulfonylharnstoffen","Flüssigkeitsmangel (Schwindel, tiefer Blutdruck, Austrocknung)","Vermehrtes Wasserlassen","Durst","Juckreiz im Scheidenbereich","Veränderte Blutfettwerte, erhöhtes Hämoglobin"],"gelegentlich":["Dysurie (Schmerzen beim Wasserlassen)","Anstieg des Kreatinins, verminderte Nierenfunktion"],"selten":["Diabetische Ketoazidose"],"unbekannt":["Fournier-Gangrän (nekrotisierende Fasziitis im Genital- und Dammbereich)"]},"schwangerschaft":"Nicht anwenden; im Tierversuch wurden die sich entwickelnden Nieren geschädigt (entspricht dem 2. und 3. Schwangerschaftsdrittel). In der Schwangerschaft wird Insulin verwendet.","stillzeit":"Nicht anwenden.","hinweise":["Auf gute Intimhygiene achten; bei Juckreiz, Ausfluss oder Rötung im Genitalbereich ärztlichen Rat einholen.","Vor grösseren Operationen und bei akuten Erkrankungen mit Erbrechen, Durchfall oder Fasten nach ärztlicher Anweisung pausieren.","Bei Übelkeit, Erbrechen, Bauchschmerzen, starkem Durst oder Atemnot sofort ärztlich abklären lassen – eine Ketoazidose ist auch bei normalem Blutzucker möglich."],"darreichung":["Filmtabletten"]},"erythromycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Erythromycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und blockiert die Verlängerung der Eiweisskette; es wirkt vorwiegend bakteriostatisch, vor allem gegen grampositive Kokken und atypische Erreger. Zusätzlich regt es als Motilin-Agonist die Darmbewegungen an, was die häufigen Magen-Darm-Beschwerden erklärt. Erythromycin hemmt das Abbauenzym CYP3A4 und den Transporter P-Glykoprotein.","nebenwirkungen":{"haeufig":["Bauchschmerzen, Übelkeit, Erbrechen, Durchfall, Appetitlosigkeit (dosisabhängig)","Bei Anwendung auf der Haut: Brennen, Rötung, Trockenheit, Schuppung"],"gelegentlich":["Hautausschlag, Juckreiz, Nesselsucht"],"unbekannt":["QT-Verlängerung, Torsade de pointes und andere ventrikuläre Herzrhythmusstörungen","Cholestatische Hepatitis mit Gelbsucht, Leberfunktionsstörungen","Pseudomembranöse Kolitis (schwere Dickdarmentzündung)","Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)","Reversibler Hörverlust, Tinnitus (vor allem bei hohen Dosen oder Niereninsuffizienz)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Pylorusstenose (Magenpförtnerverengung) bei Säuglingen; Venenreizung bei Infusion"]},"schwangerschaft":"Langjährige Erfahrung, kein eindeutiges Fehlbildungsrisiko; einzelne Studien deuten auf ein leicht erhöhtes Risiko für Herzfehler bei Einnahme im 1. Drittel hin. Systemisch nur nach ärztlicher Abwägung; Anwendung auf der Haut gilt als unbedenklich.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall und selten eine Magenpförtnerverengung möglich. Systemisch nur nach ärztlicher Abwägung; Anwendung auf der Haut (nicht im Brustbereich) ist vertretbar.","hinweise":["Vor Beginn alle anderen Medikamente angeben: Erythromycin hat viele gefährliche Wechselwirkungen.","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztliche Hilfe holen.","Akne-Lösung und -Salbe nicht auf Schleimhäute oder in die Augen bringen; die Hautanwendung hat praktisch keine Wechselwirkungen."],"darreichung":["Filmtabletten","Pulver zur Herstellung einer Infusionslösung","Lösung und Salbe zum Auftragen auf die Haut","Augensalbe (Kombination)"]},"escitalopram":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Angst, indem es die Menge des Botenstoffs Serotonin zwischen den Nervenzellen erhöht. Escitalopram ist die wirksame Hälfte (S-Enantiomer) von Citalopram und hemmt hochselektiv den Serotonin-Transporter. Es wird über CYP2C19, CYP3A4 und CYP2D6 abgebaut; die Halbwertszeit beträgt etwa 30 Stunden. Dosisabhängig kann es die QT-Zeit im EKG verlängern.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit"],"haeufig":["Verminderter oder gesteigerter Appetit, Gewichtszunahme","Angst, Unruhe, ungewöhnliche Träume, Schlaflosigkeit, Schläfrigkeit","Verminderte Libido, Orgasmus- und Ejakulationsstörungen, Impotenz","Schwindel, Zittern, Kribbeln (Parästhesien)","Nasennebenhöhlenentzündung, Gähnen","Durchfall, Verstopfung, Erbrechen, Mundtrockenheit","Vermehrtes Schwitzen, Gelenk- und Muskelschmerzen","Müdigkeit, Fieber"],"gelegentlich":["Gewichtsabnahme","Zähneknirschen, Nervosität, Panikattacken, Verwirrtheit","Geschmacksstörungen, Schlafstörungen, Ohnmacht (Synkope)","Erweiterte Pupillen, Sehstörungen, Ohrgeräusche","Herzrasen (Tachykardie)","Nasenbluten, Magen-Darm-Blutungen","Nesselsucht, Haarausfall, Hautausschlag, Juckreiz","Zwischen- und starke Menstruationsblutungen, Wassereinlagerungen"],"selten":["Anaphylaktische Reaktion","Aggressivität, Depersonalisation, Halluzinationen","Serotoninsyndrom","Langsamer Puls (Bradykardie)"],"unbekannt":["QT-Verlängerung, ventrikuläre Herzrhythmusstörungen inkl. Torsade de pointes","Hyponatriämie, inadäquate ADH-Sekretion (SIADH)","Suizidgedanken und suizidales Verhalten, Manie","Krampfanfälle, Akathisie (Bewegungsunruhe), Bewegungsstörungen","Thrombozytopenie, Blutergüsse, Angioödem","Leberentzündung, erhöhte Leberwerte","Blutdruckabfall beim Aufstehen, Harnverhalt","Milchfluss (Galaktorrhö), Priapismus, Nachblutungen nach der Geburt"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung, nicht abrupt absetzen. Bei Einnahme in der Spätschwangerschaft sind beim Neugeborenen Anpassungsstörungen (z. B. Atemprobleme, Trinkschwäche, Zittern) und ein erhöhtes Risiko für Lungenhochdruck (PPHN) möglich.","stillzeit":"Escitalopram geht in die Muttermilch über; Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Höchstdosis 20 mg pro Tag; bei Menschen über 65 Jahren, eingeschränkter Leberfunktion oder langsamem CYP2C19-Abbau meist höchstens 10 mg pro Tag.","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztlich abklären lassen.","Die Wirkung setzt nach 2–4 Wochen ein; nicht abrupt absetzen, sondern über 1–2 Wochen ausschleichen.","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Filmtabletten"]},"esketamin":{"wirkmechanismus":"Hellt bei schwerer Depression die Stimmung oft schon innert Stunden bis Tagen auf und wirkt in höherer Dosis als Narkose- und Schmerzmittel. Esketamin ist die stärker wirksame Spiegelbildform (S-Enantiomer) von Ketamin und blockiert den NMDA-Rezeptor für den erregenden Botenstoff Glutamat. In Narkosedosis führt dies zu Bewusstlosigkeit und starker Schmerzlinderung bei weitgehend erhaltener Atmung. In niedriger Dosis bewirkt die Blockade vermutlich eine vorübergehende Glutamatfreisetzung und die Neubildung von Nervenzellverbindungen, was die antidepressive Wirkung erklärt.","nebenwirkungen":{"sehrHaeufig":["Dissoziation (Gefühl, neben sich zu stehen; veränderte Wahrnehmung)","Schwindel, Drehschwindel","Kopfschmerzen","Schläfrigkeit","Taubheitsgefühl, Geschmacksstörung","Übelkeit, Erbrechen","Blutdruckanstieg"],"haeufig":["Angst, Euphorie, Verwirrtheit, Halluzinationen (bei Injektion auch Aufwachreaktionen mit Albträumen)","Sedierung, Zittern, verwaschene Sprache","Verschwommensehen","Tinnitus (Ohrgeräusche)","Herzrasen","Beschwerden in Nase und Rachen","Vermehrtes Schwitzen","Häufiger Harndrang, Schmerzen beim Wasserlassen"],"gelegentlich":["Nystagmus (Augenzittern)","Verlangsamtes Denken und Handeln","Vermehrter Speichelfluss","Gangstörung"],"unbekannt":["Atemdepression, besonders zusammen mit anderen dämpfenden Mitteln","Missbrauch und Abhängigkeit"]},"schwangerschaft":"Nasenspray: nicht empfohlen; Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten (im Tierversuch schädliche Wirkungen auf das sich entwickelnde Nervensystem). Injektion nur nach strenger ärztlicher Abwägung, bei Präeklampsie und Eklampsie kontraindiziert.","stillzeit":"Esketamin geht in die Muttermilch über. Ob abgestillt oder die Behandlung unterbrochen wird, entscheidet die Ärztin oder der Arzt nach Abwägung.","hinweise":["Der Nasenspray wird nur unter Aufsicht in der Praxis oder Klinik angewendet; danach bleibt man zur Überwachung von Blutdruck und Befinden, bis der Zustand stabil ist.","Bis zum nächsten Tag nach einem erholsamen Schlaf nicht Auto fahren und keine Maschinen bedienen.","Mindestens 2 Stunden vorher nichts essen und 30 Minuten vorher nichts trinken (Übelkeit)."],"darreichung":["Nasenspray","Injektionslösung"]},"eslicarbazepin":{"wirkmechanismus":"Beruhigt überaktive Nervenzellen im Gehirn. Eslicarbazepinacetat ist ein Prodrug, das rasch zum Wirkstoff Eslicarbazepin (S-Licarbazepin) umgewandelt wird. Dieser stabilisiert den inaktiven Zustand spannungsabhängiger Natriumkanäle und verhindert so wiederholte, rasche Entladungen von Nervenzellen.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Schläfrigkeit"],"haeufig":["Hyponatriämie (Natriummangel)","Kopfschmerzen, Konzentrationsstörungen","Gleichgewichts- und Koordinationsstörungen (Ataxie), Zittern","Doppelbilder, verschwommenes Sehen","Übelkeit, Erbrechen, Durchfall","Hautausschlag","Müdigkeit, Gangstörungen","Schlaflosigkeit"],"gelegentlich":["Blutarmut (Anämie)","Schilddrüsenunterfunktion","Depression","Langsamer Puls (Bradykardie), Blutdruckveränderungen","Leberfunktionsstörungen","Überempfindlichkeitsreaktionen"],"unbekannt":["Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautreaktionen)","DRESS (Arzneimittelreaktion mit Fieber, Ausschlag und Organbeteiligung)","Verminderung der Blutplättchen und weissen Blutkörperchen","Bauchspeicheldrüsenentzündung (Pankreatitis)","Angioödem (Schwellung von Haut und Schleimhäuten)","SIADH (Wassereinlagerung mit Natriummangel)"]},"schwangerschaft":"Nur nach sorgfältiger ärztlicher Abwägung; eine Schwangerschaft möglichst planen. Eslicarbazepin schwächt die Wirkung hormonaler Verhütungsmittel ab.","stillzeit":"Es ist nicht bekannt, ob Eslicarbazepin in die Muttermilch übergeht; während der Behandlung nicht stillen.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten einnehmen.","Nicht abrupt absetzen – Gefahr gehäufter Anfälle.","Bei Übelkeit, Verwirrtheit, Benommenheit oder zunehmenden Anfällen an Natriummangel denken; Natrium wird kontrolliert.","Kann Reaktionsvermögen und Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Tabletten"]},"esmolol":{"wirkmechanismus":"Verlangsamt rasch den Herzschlag und senkt den Blutdruck. Esmolol blockiert selektiv die Beta-1-Rezeptoren des Herzens ohne Eigenwirkung und vermindert so Herzfrequenz, Erregungsleitung im AV-Knoten und Herzkraft. Es wird durch Esterasen in den roten Blutkörperchen sehr schnell abgebaut (Halbwertszeit etwa 9 Minuten); die Wirkung klingt deshalb rund 10–30 Minuten nach Infusionsende ab und lässt sich gut steuern.","nebenwirkungen":{"sehrHaeufig":["Hypotonie (Blutdruckabfall), oft ohne Beschwerden","Vermehrtes Schwitzen"],"haeufig":["Schwindel, Schläfrigkeit, Kopfschmerzen, Kribbeln","Verwirrtheit, Unruhe, Angst, depressive Verstimmung, Konzentrationsstörungen","Übelkeit, Erbrechen, Appetitlosigkeit","Müdigkeit, Schwächegefühl","Reizung, Entzündung oder Verhärtung an der Infusionsstelle"],"gelegentlich":["Bradykardie (langsamer Puls)","Bronchospasmus (Verkrampfung der Atemwege), Atemnot","Ohnmacht (Synkope), kalte Hände und Füsse","Geschmacksstörungen"],"selten":["Sinusarrest, Asystolie (Herzstillstand)","Hautnekrose bei Austritt der Lösung ins Gewebe"],"unbekannt":["Hyperkaliämie (erhöhtes Kalium)"]},"schwangerschaft":"Nur bei klarer Notwendigkeit; kann beim Ungeborenen den Puls verlangsamen. Neugeborene nach Anwendung kurz vor der Geburt auf langsamen Puls, Unterzuckerung und Atemprobleme überwachen.","stillzeit":"Keine Daten; während der Behandlung nicht stillen.","hinweise":["Wird nur im Spital unter laufender Überwachung von Puls, Blutdruck und EKG gegeben.","Die Wirkung klingt nach Ende der Infusion innerhalb von etwa 30 Minuten ab."],"darreichung":["Injektionslösung","Infusionslösung","Pulver zur Herstellung einer Infusionslösung"]},"esomeprazol":{"wirkmechanismus":"Senkt die Bildung von Magensäure stark und anhaltend. Esomeprazol ist das S-Enantiomer (eine der beiden Spiegelbildformen) von Omeprazol und wird langsamer abgebaut, wodurch höhere und gleichmässigere Spiegel erreicht werden. In den sauren Belegzellen der Magenschleimhaut wird es in die aktive Form umgewandelt und blockiert irreversibel die Protonenpumpe (H+/K+-ATPase), den letzten Schritt der Säurebildung. Esomeprazol wird über CYP2C19 und CYP3A4 abgebaut und hemmt selbst CYP2C19.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen, Blähungen","Durchfall oder Verstopfung","Übelkeit, Erbrechen","Gutartige Drüsenpolypen im Magen (Fundusdrüsenpolypen)"],"gelegentlich":["Wassereinlagerungen in den Beinen","Schlafstörungen","Schwindel, Kribbeln (Parästhesien), Schläfrigkeit","Mundtrockenheit","Erhöhte Leberwerte","Hautausschlag, Juckreiz, Nesselsucht","Knochenbrüche (Hüfte, Handgelenk, Wirbelsäule)"],"selten":["Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Überempfindlichkeitsreaktionen wie Fieber, Angioödem oder anaphylaktischer Schock","Hyponatriämie (Natriummangel)","Unruhe, Verwirrtheit, Depression","Geschmacksstörungen, verschwommenes Sehen","Bronchospasmus (Verkrampfung der Atemwege)","Hepatitis, Mundschleimhautentzündung, Pilzbefall im Magen-Darm-Trakt","Lichtempfindlichkeit, Haarausfall, Gelenk- und Muskelschmerzen"],"sehrSelten":["Agranulozytose, Panzytopenie (schwerer Mangel an Blutzellen)","Leberversagen, hepatische Enzephalopathie","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme","Halluzinationen, Aggressivität","Interstitielle Nephritis (Nierenentzündung)","Muskelschwäche, Gynäkomastie (Brustvergrösserung beim Mann)"],"unbekannt":["Hypomagnesiämie (Magnesiummangel), dadurch auch Calcium- und Kaliummangel","Mikroskopische Kolitis","Subakuter kutaner Lupus erythematodes","DRESS (schwere Arzneimittelreaktion mit Ausschlag, Fieber und Organbeteiligung)"]},"schwangerschaft":"Kann nach ärztlicher Abwägung angewendet werden; Daten zu Esomeprazol und umfangreiche Erfahrungen mit Omeprazol zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Es ist nicht bekannt, ob Esomeprazol in die Muttermilch übergeht; laut Fachinformation soll es in der Stillzeit nicht angewendet werden.","hinweise":["Tablette ganz mit Wasser schlucken, nicht kauen oder zerdrücken; bei Schluckbeschwerden darf sie in kohlensäurefreiem Wasser zerfallen gelassen werden.","Rezeptfreie Selbstbehandlung (20 mg) höchstens 14 Tage; ohne Besserung ärztlich abklären.","Nach längerer Einnahme nicht abrupt absetzen: vorübergehend vermehrte Säurebildung (Rebound) möglich.","Bei Langzeitbehandlung regelmässig die Notwendigkeit sowie Magnesium und Vitamin B12 überprüfen lassen."],"darreichung":["Magensaftresistente Tabletten","Magensaftresistentes Granulat zur Herstellung einer Suspension (Beutel)","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"estetrol-drospirenon":{"wirkmechanismus":"Verhindert eine Schwangerschaft, indem sie den Eisprung unterdrückt. Drospirenon ist ein vom Spironolacton abgeleitetes Gestagen: Es hemmt die Ausschüttung von LH und damit den Eisprung und wirkt zusätzlich antimineralokortikoid (leicht entwässernd, kaliumsparend) und antiandrogen. Estetrol ist ein natürliches, in der Schwangerschaft von der Leber des Fötus gebildetes Östrogen; es stabilisiert die Gebärmutterschleimhaut und damit das Blutungsmuster.","nebenwirkungen":{"haeufig":["Stimmungsschwankungen, Libidostörungen","Kopfschmerzen","Bauchschmerzen, Übelkeit","Akne","Brustschmerzen","Zwischenblutungen, Regelschmerzen, starke Regelblutung","Gewichtsschwankungen"],"gelegentlich":["Vaginale Pilzinfektion, Scheiden- oder Harnwegsinfektion","Depression, Angst, Schlafstörungen","Migräne, Schwindel","Hitzewallungen","Blähbauch, Erbrechen, Durchfall","Haarausfall, vermehrtes Schwitzen, Hautausschlag","Müdigkeit, Wassereinlagerungen","Erhöhte Leberwerte"],"selten":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)"],"unbekannt":["Überempfindlichkeitsreaktionen","Hyperkaliämie (erhöhtes Kalium)"]},"schwangerschaft":"Nicht anwenden. Tritt unter der Einnahme eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Nicht empfohlen: kann die Milchmenge vermindern, kleine Hormonmengen gehen in die Muttermilch über. Bis zum Abstillen anders verhüten.","hinweise":["Täglich zur gleichen Zeit einnehmen, 24 Hormontabletten und anschliessend 4 Placebotabletten ohne Pause.","Bei vergessener Einnahme, Erbrechen oder starkem Durchfall kann der Schutz vermindert sein – Packungsbeilage beachten, gegebenenfalls zusätzlich Kondome verwenden.","Bei Anzeichen einer Thrombose (geschwollenes, schmerzendes Bein, plötzliche Atemnot, Brustschmerzen) oder eines Schlaganfalls sofort ärztliche Hilfe holen.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Filmtabletten"]},"estradiol":{"wirkmechanismus":"Ersetzt das nach den Wechseljahren fehlende körpereigene Östrogen. Estradiol ist chemisch identisch mit dem natürlichen 17-beta-Estradiol und bindet an Östrogenrezeptoren in Gehirn, Knochen, Haut, Scheide und Gebärmutter. Dadurch werden Hitzewallungen gelindert, der Knochenabbau gebremst und die Scheidenschleimhaut wieder aufgebaut. Da Östrogen allein die Gebärmutterschleimhaut wuchern lässt, brauchen Frauen mit Gebärmutter zusätzlich ein Gestagen.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen, Übelkeit","Brustspannen, Brustschmerzen, Brustvergrösserung","Zwischen- oder Schmierblutungen","Wassereinlagerungen (Ödeme), Gewichtszunahme","Wadenkrämpfe","Hautreaktionen an der Auftragsstelle (Pflaster, Gel)","Scheidenpilz (vaginale Candidose)"],"gelegentlich":["Depressive Verstimmung, Nervosität","Schwindel, Sehstörungen","Migräne","Blähungen, Völlegefühl","Hautausschlag, Juckreiz"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Gallenblasenerkrankungen","Überempfindlichkeitsreaktionen bis Anaphylaxie"],"unbekannt":["Brustkrebs (Risiko steigt mit der Dauer, vor allem bei Kombination mit Gestagen)","Gebärmutterschleimhautkrebs bei Östrogen-Monotherapie ohne Gestagenschutz","Eierstockkrebs (leicht erhöhtes Risiko)","Schlaganfall, koronare Herzkrankheit bei späterem Therapiebeginn","Chloasma (Pigmentflecken), Erythema nodosum oder multiforme","Wahrscheinliche Demenz bei Beginn nach dem 65. Lebensjahr"]},"schwangerschaft":"Kontraindiziert – nicht für die Anwendung in der Schwangerschaft bestimmt; tritt eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Kontraindiziert – nicht für die Anwendung in der Stillzeit bestimmt.","hinweise":["Frauen mit Gebärmutter benötigen zusätzlich ein Gestagen; unerwartete oder anhaltende Blutungen ärztlich abklären.","So niedrig dosiert und so kurz wie nötig anwenden; mindestens jährlich ärztlich neu beurteilen lassen, Brustkrebs-Früherkennung wahrnehmen.","Gel und Pflaster: auf saubere, trockene, unverletzte Haut, nie auf die Brüste oder Schleimhäute; nach dem Auftragen des Gels Hände waschen und Hautkontakt mit Kindern vermeiden, bis es getrocknet ist.","Bei Beinschwellung, plötzlicher Atemnot, Brustschmerzen, Gelbsucht oder plötzlichen starken Kopfschmerzen sofort absetzen und ärztliche Hilfe holen."],"darreichung":["Tabletten","Transdermales Pflaster","Gel","Vaginaltabletten"]},"estradiol-dienogest":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem sie den Eisprung unterdrückt. Estradiolvalerat wird im Körper zu Estradiol, dem körpereigenen Östrogen, umgewandelt; Dienogest ist ein Gestagen mit antiandrogener Wirkung, das die Gebärmutterschleimhaut dünn hält und so die Blutungsmenge vermindert. Die Dosierung der beiden Hormone ändert sich über den 28-tägigen Zyklus in vier Stufen (26 Hormon- und 2 Placebotabletten), um das Blutungsmuster zu stabilisieren.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen","Akne","Ausbleiben der Monatsblutung (Amenorrhö)","Brustbeschwerden, Regelschmerzen","Zwischenblutungen","Gewichtszunahme"],"gelegentlich":["Vaginale Pilzinfektion","Appetitsteigerung","Depression, Stimmungsschwankungen, Libidoabnahme, Schlaflosigkeit","Schwindel, Migräne","Hitzewallungen, Bluthochdruck","Übelkeit, Erbrechen, Durchfall","Haarausfall, vermehrtes Schwitzen, Juckreiz, Hautausschlag","Wassereinlagerungen (Ödeme), Reizbarkeit, Müdigkeit"],"selten":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)"],"unbekannt":["Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Kontraindiziert. Tritt unter der Einnahme eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Nicht empfohlen: kann die Milchmenge vermindern, kleine Hormonmengen gehen in die Muttermilch über. Bis zum Abstillen anders verhüten.","hinweise":["Die Tabletten genau in der Reihenfolge der Packung einnehmen, täglich zur gleichen Zeit und ohne Pause zwischen den Packungen.","Bei vergessener Einnahme hängt das Vorgehen vom Zyklustag ab – Packungsbeilage beachten, gegebenenfalls zusätzlich Kondome verwenden.","Bei Anzeichen einer Thrombose (geschwollenes, schmerzendes Bein, plötzliche Atemnot, Brustschmerzen) oder eines Schlaganfalls sofort ärztliche Hilfe holen.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Filmtabletten"]},"estradiol-drospirenon":{"wirkmechanismus":"Ersetzt die nach den Wechseljahren fehlenden weiblichen Hormone und lindert so Hitzewallungen und Schweissausbrüche. Estradiol entspricht dem körpereigenen Östrogen, bindet an Östrogenrezeptoren und bremst auch den Knochenabbau. Das täglich mitgegebene Gestagen Drospirenon schützt die Gebärmutterschleimhaut vor übermässigem Wachstum; als Spironolacton-Abkömmling wirkt es zudem antimineralokortikoid (leicht entwässernd, kaliumsparend) und antiandrogen.","nebenwirkungen":{"haeufig":["Brustschmerzen, Brustspannen, Brustvergrösserung","Vaginale Blutungen und Schmierblutungen","Kopfschmerzen","Bauchschmerzen, Übelkeit, Blähbauch","Stimmungsschwankungen","Ausfluss","Schwächegefühl, lokale Wassereinlagerungen","Gutartige Brust- oder Gebärmutterhalsveränderungen"],"gelegentlich":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Brustkrebs, Verdickung der Gebärmutterschleimhaut","Depression, Nervosität, Schlafstörungen, Libidoabnahme","Schwindel, Migräne, Bluthochdruck","Durchfall, Verstopfung, Erbrechen","Gallensteine, veränderte Leberwerte","Akne, Haarausfall, Juckreiz, Hautausschlag","Muskelkrämpfe, Rücken- und Gelenkschmerzen"],"selten":["Anämie (Blutarmut)","Ohrgeräusche (Tinnitus), Drehschwindel","Muskelschmerzen"],"unbekannt":["Hyperkaliämie (erhöhtes Kalium)","Schlaganfall","Eierstockkrebs (Risiko leicht erhöht)","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Kontraindiziert. Tritt eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Kontraindiziert.","hinweise":["Täglich ohne Pause eine Tablette einnehmen; eine regelmässige Monatsblutung tritt nicht auf, anfangs sind Schmierblutungen häufig.","So niedrig dosiert und so kurz wie möglich anwenden; Nutzen und Risiken mindestens einmal jährlich ärztlich besprechen.","Regelmässige Brustuntersuchungen und Mammografien gemäss Empfehlung; Blutungen nach den ersten Monaten abklären lassen.","Bei Anzeichen einer Thrombose, plötzlichen starken Kopfschmerzen oder Sehstörungen sofort ärztliche Hilfe holen; vor Operationen die Einnahme angeben."],"darreichung":["Filmtabletten"]},"estradiol-dydrogesteron":{"wirkmechanismus":"Ersetzt die nach den Wechseljahren fehlenden weiblichen Hormone. Estradiol entspricht dem körpereigenen Östrogen, lindert Wechseljahresbeschwerden und bremst den Knochenabbau. Dydrogesteron ist ein dem natürlichen Progesteron ähnliches Gestagen, das die Gebärmutterschleimhaut vor übermässigem Wachstum schützt. Femoston wird sequenziell (mit Abbruchblutung) oder als Femoston conti durchgehend eingenommen.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Bauchschmerzen","Rückenschmerzen","Brustspannen, Brustschmerzen"],"haeufig":["Scheidenpilz","Depression, Nervosität","Migräne, Schwindel","Übelkeit, Erbrechen, Blähungen","Allergische Hautreaktionen (Ausschlag, Juckreiz)","Zwischenblutungen, Menstruationsstörungen, Unterleibsschmerzen","Schwächegefühl, Ödeme, Gewichtsveränderungen"],"gelegentlich":["Blasenentzündungsähnliche Beschwerden","Vergrösserung von Myomen","Libidoveränderungen","Venöse Thromboembolie (Thrombose, Lungenembolie)","Bluthochdruck, Durchblutungsstörungen","Gallenblasenerkrankungen, Leberfunktionsstörungen"],"selten":["Herzinfarkt","Angioödem, Gefässpurpura"],"unbekannt":["Erhöhtes Risiko für Brustkrebs, Eierstockkrebs und Gebärmutterschleimhautkrebs","Schlaganfall","Wahrscheinliche Demenz bei Beginn nach 65 Jahren"]},"schwangerschaft":"Nicht angezeigt; bei Eintritt einer Schwangerschaft sofort absetzen.","stillzeit":"Nicht angezeigt.","hinweise":["So niedrig dosiert und so kurz wie nötig anwenden; jährlich ärztlich überprüfen lassen.","Bei Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Sehstörungen oder starken Kopfschmerzen sofort ärztliche Hilfe holen.","Täglich etwa zur gleichen Zeit einnehmen; Reihenfolge der Tabletten bei Sequenzpackungen einhalten.","Regelmässige Brustkontrollen und Mammografie; ungewöhnliche Blutungen abklären lassen."],"darreichung":["Filmtabletten"]},"estradiol-nomegestrol":{"wirkmechanismus":"Verhindert eine Schwangerschaft, indem sie den Eisprung unterdrückt. Nomegestrolacetat ist ein stark wirksames, vom Progesteron abgeleitetes Gestagen: Es hemmt die Ausschüttung von LH aus der Hirnanhangsdrüse und damit den Eisprung und macht den Schleim im Gebärmutterhals für Spermien schwer durchlässig. Das enthaltene Estradiol entspricht dem körpereigenen Östrogen und stabilisiert die Gebärmutterschleimhaut und damit das Blutungsmuster.","nebenwirkungen":{"sehrHaeufig":["Akne","Ausbleibende oder veränderte Abbruchblutungen"],"haeufig":["Libidoabnahme","Depressive Verstimmung, Stimmungsschwankungen","Kopfschmerzen, Migräne","Übelkeit","Zwischenblutungen, starke Regelblutungen","Brustschmerzen","Unterleibsschmerzen","Gewichtszunahme"],"gelegentlich":["Appetitsteigerung","Wassereinlagerungen (Ödeme)","Hitzewallungen","Blähbauch","Vermehrtes Schwitzen, Haarausfall, Juckreiz","Reizbarkeit","Erhöhte Leberwerte"],"selten":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Gallensteine, Gallenblasenentzündung","Chloasma (bräunliche Hautflecken)","Kontaktlinsenunverträglichkeit"],"unbekannt":["Meningiom (gutartiger Hirnhauttumor), vor allem bei hohen Dosen und langer Anwendung von Nomegestrolacetat beschrieben"]},"schwangerschaft":"Kontraindiziert. Tritt unter der Einnahme eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Nicht empfohlen: kann die Milchmenge vermindern, kleine Hormonmengen gehen in die Muttermilch über. Bis zum Abstillen anders verhüten.","hinweise":["Täglich zur gleichen Zeit einnehmen, 24 weisse Hormontabletten und anschliessend 4 gelbe Placebotabletten ohne Pause.","Bei vergessener Einnahme, Erbrechen oder starkem Durchfall kann der Schutz vermindert sein – Packungsbeilage beachten, gegebenenfalls zusätzlich Kondome verwenden.","Bei Anzeichen einer Thrombose (geschwollenes, schmerzendes Bein, plötzliche Atemnot, Brustschmerzen) oder eines Schlaganfalls sofort ärztliche Hilfe holen.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Filmtabletten"]},"estradiol-norethisteron":{"wirkmechanismus":"Ersetzt die nach den Wechseljahren fehlenden weiblichen Hormone. Estradiol ist identisch mit dem körpereigenen Östrogen und lindert Hitzewallungen, Schlafstörungen und Scheidentrockenheit; es bremst zudem den Knochenabbau. Norethisteron ist ein Gestagen, das das Wachstum der Gebärmutterschleimhaut hemmt und so das östrogenbedingte Risiko für Schleimhautwucherung und Gebärmutterkrebs senkt. Je nach Präparat werden die Hormone durchgehend (kontinuierlich) oder in Phasen (sequenziell, mit Monatsblutung) gegeben.","nebenwirkungen":{"sehrHaeufig":["Brustspannen, Brustschmerzen","Vaginale Blutungen, Schmierblutungen (besonders in den ersten Monaten)"],"haeufig":["Kopfschmerzen","Übelkeit, Bauchschmerzen","Gewichtszunahme, Ödeme (Wassereinlagerungen)","Depression oder Verschlechterung einer Depression","Scheidenpilz, Scheidenentzündung","Wachstum oder Neuauftreten von Myomen","Pflaster: Hautreaktionen an der Klebestelle"],"gelegentlich":["Venenentzündung (Thrombophlebitis)","Migräne, Libidoveränderungen, Nervosität","Blähungen","Haarausfall, vermehrte Behaarung, Akne, Juckreiz","Wadenkrämpfe"],"selten":["Tiefe Venenthrombose, Lungenembolie"],"unbekannt":["Erhöhtes Risiko für Brustkrebs, Eierstockkrebs und Gebärmutterschleimhautkrebs","Schlaganfall, koronare Herzkrankheit (bei späterem Beginn)","Gallenblasenerkrankungen","Wahrscheinliche Demenz bei Beginn nach 65 Jahren"]},"schwangerschaft":"Nicht angezeigt; bei Eintritt einer Schwangerschaft sofort absetzen.","stillzeit":"Nicht angezeigt.","hinweise":["So niedrig dosiert und so kurz wie nötig anwenden; die Behandlung mindestens jährlich ärztlich überprüfen lassen.","Bei Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Sehstörungen oder starken Kopfschmerzen sofort ärztliche Hilfe holen.","Vor geplanten Operationen ärztlich besprechen, ob die Behandlung pausiert werden soll.","Regelmässige Brustkontrollen und Mammografie; ungewöhnliche Blutungen abklären lassen."],"darreichung":["Filmtabletten","Transdermales Pflaster"]},"estriol":{"wirkmechanismus":"Ersetzt lokal das in den Wechseljahren fehlende Östrogen und baut so die dünn gewordene Scheidenhaut wieder auf. Estriol ist ein kurz wirksames natürliches Östrogen, das an die Östrogenrezeptoren der Scheiden- und Harnröhrenschleimhaut bindet. Es fördert die Vermehrung und Reifung der Epithelzellen, normalisiert den sauren pH-Wert und begünstigt die Ansiedlung von Milchsäurebakterien, was die Widerstandskraft gegen Infektionen erhöht. Wegen der kurzen Bindung am Rezeptor und der geringen Aufnahme ins Blut wird die Gebärmutterschleimhaut bei vaginaler Anwendung kaum stimuliert.","nebenwirkungen":{"unbekannt":["Lokale Reizung, Brennen oder Juckreiz in der Scheide","Brustspannen oder Brustschmerzen","Schmierblutungen nach den Wechseljahren","Vermehrter Ausfluss aus der Scheide","Übelkeit","Grippeähnliche Beschwerden","Wassereinlagerungen (Ödeme)"]},"schwangerschaft":"In der Schwangerschaft nicht angezeigt. Tritt unter der Behandlung eine Schwangerschaft ein, soll die Anwendung sofort beendet werden.","stillzeit":"In der Stillzeit nicht angezeigt: Estriol geht in die Muttermilch über und kann die Milchbildung vermindern.","hinweise":["Am besten abends vor dem Schlafengehen tief in die Scheide einführen.","Nach Abklingen der Beschwerden auf die niedrigste wirksame Erhaltungsdosis reduzieren; Nutzen und Risiken mindestens jährlich ärztlich überprüfen lassen.","Unerwartete Blutungen aus der Scheide, Knoten in der Brust oder Zeichen einer Thrombose (geschwollenes, schmerzendes Bein, plötzliche Atemnot) sofort ärztlich abklären lassen.","Regelmässige gynäkologische Kontrollen und Brustuntersuchungen wahrnehmen."],"darreichung":["Vaginalcreme","Vaginalzäpfchen (Ovula)","Vaginaltabletten (Kombination mit Milchsäurebakterien)"]},"etanercept":{"wirkmechanismus":"Bremst Entzündungen, indem es einen zentralen Entzündungsbotenstoff abfängt. Etanercept ist ein gentechnisch hergestelltes Fusionsprotein aus zwei menschlichen TNF-Rezeptoren und dem Fc-Teil eines Antikörpers. Es wirkt wie ein löslicher Köder-Rezeptor, bindet TNF-alpha (und Lymphotoxin-alpha) und verhindert dessen Andocken an Zellrezeptoren. Dadurch nehmen Gelenk- und Hautentzündung ab, zugleich wird aber auch die Infektabwehr geschwächt.","nebenwirkungen":{"sehrHaeufig":["Infektionen (Atemwege, Blase, Haut)","Reaktionen an der Einstichstelle (Rötung, Juckreiz, Schmerzen, Schwellung)"],"haeufig":["Allergische Reaktionen","Bildung von Autoantikörpern","Juckreiz, Hautausschlag","Fieber"],"gelegentlich":["Schwere Infektionen (z. B. Lungenentzündung, Sepsis, Hautinfektionen)","Thrombozytopenie, Anämie, Leukopenie, Neutropenie","Nicht-melanozytärer Hautkrebs","Neu auftretende oder verschlechterte Psoriasis, Angioödem, Nesselsucht","Uveitis, Skleritis (Augenentzündungen)","Interstitielle Lungenerkrankung","Chronisch entzündliche Darmerkrankung","Vaskulitis (Gefässentzündung), erhöhte Leberwerte"],"selten":["Tuberkulose und opportunistische Infektionen","Lymphome, Melanom","Panzytopenie","Demyelinisierende Erkrankungen des Zentralnervensystems (z. B. Multiple Sklerose, Sehnerventzündung), Krampfanfälle","Verschlechterung einer Herzinsuffizienz","Lupus-ähnliches Syndrom, autoimmune Hepatitis, Sarkoidose","Stevens-Johnson-Syndrom, Erythema multiforme","Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Aplastische Anämie","Toxische epidermale Nekrolyse (schwerste Hautreaktion)","Periphere demyelinisierende Erkrankungen (z. B. Guillain-Barré-Syndrom)"],"unbekannt":["Hepatitis-B-Reaktivierung","Listeriose","Merkelzellkarzinom (seltener Hautkrebs), Kaposi-Sarkom, Leukämie","Makrophagenaktivierungssyndrom","Verschlechterung einer Dermatomyositis"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung. Etanercept passiert die Plazenta; Säuglinge, die im Mutterleib exponiert waren, sollen in den ersten Lebensmonaten keine Lebendimpfungen erhalten.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Stillen nur nach ärztlicher Nutzen-Risiko-Abwägung.","hinweise":["Vor Beginn auf Tuberkulose und Hepatitis B testen und den Impfstatus vervollständigen lassen.","Bei Fieber, anhaltendem Husten, Gewichtsverlust oder anderen Infektzeichen rasch ärztlich abklären lassen.","Regelmässige Hautkontrollen (Hautkrebs); Sonnenschutz.","Im Kühlschrank lagern; vor dem Spritzen 15–30 Minuten Raumtemperatur annehmen lassen."],"darreichung":["Injektionslösung (Fertigspritze, Fertigpen)","Pulver zur Herstellung einer Injektionslösung"]},"etelcalcetid":{"wirkmechanismus":"Senkt die Ausschüttung des Nebenschilddrüsenhormons (Parathormon), indem es den Nebenschilddrüsen einen höheren Calciumspiegel vortäuscht. Etelcalcetid ist ein synthetisches Peptid, das an den Calcium-sensitiven Rezeptor (CaSR) der Nebenschilddrüsenzellen bindet und ihn aktiviert (allosterische Aktivierung). Dadurch sinken Parathormon, Calcium und Phosphat im Blut. Es wird dreimal wöchentlich am Ende der Hämodialyse intravenös gegeben.","nebenwirkungen":{"sehrHaeufig":["Erniedrigtes Calcium im Blut (Laborwert)","Muskelkrämpfe","Durchfall","Übelkeit"],"haeufig":["Hypokalzämie mit Beschwerden (Kribbeln, Taubheitsgefühl, Muskelzuckungen)","Hyperkaliämie (erhöhtes Kalium)","Hypophosphatämie (tiefes Phosphat)","Kopfschmerzen","Verschlechterung einer Herzinsuffizienz","QT-Verlängerung im EKG","Hypotonie (tiefer Blutdruck)","Erbrechen, Muskelschmerzen"],"gelegentlich":["Krampfanfälle"],"unbekannt":["Überempfindlichkeitsreaktionen einschliesslich Anaphylaxie"]},"schwangerschaft":"Keine Erfahrungen beim Menschen. Vorsichtshalber während der Schwangerschaft nicht anwenden.","stillzeit":"Nicht bekannt, ob Etelcalcetid beim Menschen in die Muttermilch übergeht (im Tierversuch ja). Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Wird vom Dialyseteam am Ende der Hämodialyse in den Schlauch der Dialysemaschine gespritzt.","Kribbeln um den Mund oder in den Fingern, Muskelkrämpfe, Herzklopfen oder einen Krampfanfall sofort melden (Zeichen eines Calciummangels).","Calcium und Parathormon werden regelmässig kontrolliert."],"darreichung":["Injektionslösung"]},"ethambutol":{"wirkmechanismus":"Hemmt das Wachstum von Tuberkulosebakterien, indem es den Aufbau ihrer Zellwand stört. Ethambutol hemmt die Arabinosyltransferasen (EmbA, EmbB, EmbC), die Arabinogalaktan und Lipoarabinomannan herstellen – wichtige Bausteine der Mykobakterien-Zellwand. Es wirkt vorwiegend bakteriostatisch und verhindert in der Kombinationstherapie, dass sich resistente Erreger durchsetzen.","nebenwirkungen":{"unbekannt":["Optikusneuritis mit verminderter Sehschärfe, Rot-Grün-Sehstörung und Gesichtsfeldausfällen (dosisabhängig, nach Absetzen meist rückbildungsfähig)","Periphere Neuropathie (Kribbeln, Taubheit in Händen und Füssen)","Hyperurikämie (erhöhte Harnsäure), Gichtanfall","Übelkeit, Erbrechen, Bauchschmerzen, Appetitlosigkeit","Überempfindlichkeitsreaktionen (Ausschlag, Juckreiz, Fieber, Gelenkschmerzen) bis Anaphylaxie","Erhöhte Leberwerte, Hepatitis","Thrombozytopenie, Leukopenie","Verwirrtheit, Halluzinationen, Kopfschmerzen, Schwindel"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; bisher keine Hinweise auf Fruchtschädigung beim Menschen. Ethambutol gehört zur üblichen Tuberkulosetherapie in der Schwangerschaft.","stillzeit":"Geht in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Vor Beginn und regelmässig während der Behandlung Sehschärfe und Farbsehen augenärztlich prüfen lassen.","Bei verschwommenem Sehen, Farbsehstörungen oder Gesichtsfeldausfällen sofort ärztlich melden – frühes Absetzen verhindert bleibende Schäden.","Aluminiumhaltige Säurebinder nur mit zeitlichem Abstand einnehmen."],"darreichung":["Tabletten"]},"ethinylestradiol-chlormadinon":{"wirkmechanismus":"Verhindert eine Schwangerschaft, indem sie den Eisprung unterdrückt. Ethinylestradiol und das Gestagen Chlormadinonacetat hemmen gemeinsam die Ausschüttung von FSH und LH aus der Hirnanhangsdrüse und damit die Follikelreifung. Zusätzlich wird der Schleim im Gebärmutterhals für Spermien schwer durchlässig und die Gebärmutterschleimhaut für eine Einnistung ungeeignet. Chlormadinonacetat hemmt ausserdem die Wirkung männlicher Hormone (antiandrogene Wirkung).","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Ausfluss (Fluor vaginalis)","Regelschmerzen (Dysmenorrhö)","Ausbleiben der Monatsblutung (Amenorrhö)"],"haeufig":["Kopfschmerzen, Migräne","Depressive Verstimmung, Nervosität, Reizbarkeit","Schwindel","Erbrechen","Akne","Brustschmerzen, Zwischenblutungen","Müdigkeit, Wassereinlagerungen, Gewichtszunahme","Blutdruckanstieg"],"gelegentlich":["Bauchschmerzen, Blähungen, Durchfall","Chloasma (bräunliche Hautflecken), Haarausfall, trockene Haut","Vaginale Pilzinfektion","Libidoabnahme","Erhöhte Blutfette"],"selten":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Bindehautentzündung, Kontaktlinsenunverträglichkeit","Hörsturz, Ohrgeräusche (Tinnitus)","Nesselsucht, Ekzem, Juckreiz"],"sehrSelten":["Erythema nodosum (schmerzhafte Knoten unter der Haut)"],"unbekannt":["Meningiom (gutartiger Hirnhauttumor), vor allem bei hohen Dosen und langer Anwendung von Chlormadinonacetat beschrieben"]},"schwangerschaft":"Kontraindiziert. Tritt unter der Einnahme eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Nicht empfohlen: kann die Milchmenge vermindern, kleine Hormonmengen gehen in die Muttermilch über. Bis zum Abstillen anders verhüten.","hinweise":["21 Tage lang täglich zur gleichen Zeit einnehmen, danach 7 Tage Pause.","Bei vergessener Einnahme, Erbrechen oder starkem Durchfall kann der Schutz vermindert sein – Packungsbeilage beachten, gegebenenfalls zusätzlich Kondome verwenden.","Bei Anzeichen einer Thrombose (geschwollenes, schmerzendes Bein, plötzliche Atemnot, Brustschmerzen) oder eines Schlaganfalls sofort ärztliche Hilfe holen.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Filmtabletten"]},"ethinylestradiol-desogestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Östrogen Ethinylestradiol und das Gestagen Desogestrel hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift. Desogestrel ist eine Vorstufe (Prodrug) und wird in Darmwand und Leber zum eigentlichen Wirkstoff Etonogestrel umgewandelt. Zusätzlich verdickt das Gestagen den Schleim am Gebärmutterhals und verändert die Gebärmutterschleimhaut; Ethinylestradiol stabilisiert den Zyklus.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Übelkeit, Bauchschmerzen","Depressive Verstimmung, Stimmungsschwankungen","Brustschmerzen, Brustspannen","Gewichtszunahme","Zwischen- und Schmierblutungen, vor allem in den ersten Monaten"],"gelegentlich":["Migräne","Erbrechen, Durchfall","Verminderte Libido","Wassereinlagerungen (Ödeme)","Hautausschlag, Nesselsucht","Brustvergrösserung"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Überempfindlichkeitsreaktionen","Erythema nodosum oder multiforme (entzündliche Hautknoten bzw. Hautausschlag)","Unverträglichkeit von Kontaktlinsen","Scheidenausfluss, Absonderung aus der Brust","Gesteigerte Libido, Gewichtsabnahme"],"unbekannt":["Blutdruckanstieg","Chloasma (bräunliche Pigmentflecken im Gesicht)","Lebertumoren","Auslösung oder Verschlechterung eines hereditären Angioödems","Leicht erhöhte Häufigkeit von Brustkrebsdiagnosen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft sofort absetzen. Eine versehentliche Einnahme in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne Pille etwa 2, mit Desogestrel-Pillen etwa 9–12 von 10'000 Frauen pro Jahr (mit Levonorgestrel-Pillen 5–7); am höchsten im ersten Anwendungsjahr und nach einer Pause von 4 Wochen oder mehr.","Bei einseitiger Beinschwellung oder Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Lähmungen, Seh- oder Sprachstörungen sofort ärztliche Hilfe holen.","Vergessene Tablette: bei weniger als 12 Stunden Verspätung sofort nachnehmen; bei mehr als 12 Stunden ist der Schutz vermindert – Anleitung der Packungsbeilage befolgen. Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden gilt wie eine vergessene Tablette.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Tabletten"]},"ethinylestradiol-dienogest":{"wirkmechanismus":"Verhindert eine Schwangerschaft, indem sie den Eisprung unterdrückt. Ethinylestradiol und das Gestagen Dienogest hemmen gemeinsam die Ausschüttung von FSH und LH aus der Hirnanhangsdrüse und damit die Follikelreifung. Zusätzlich wird der Schleim im Gebärmutterhals für Spermien schwer durchlässig. Dienogest wirkt ausserdem antiandrogen (hemmt männliche Hormone).","nebenwirkungen":{"haeufig":["Kopfschmerzen","Brustschmerzen, Brustspannen"],"gelegentlich":["Scheidenentzündung, vaginale Pilzinfektion","Appetitsteigerung, Gewichtsveränderungen","Depressive Verstimmung","Schwindel, Migräne","Bluthochdruck oder tiefer Blutdruck","Bauchschmerzen, Übelkeit, Erbrechen, Durchfall","Akne, Haarausfall, Hautausschlag, Juckreiz","Unregelmässige Blutungen, Zwischenblutungen, Regelschmerzen, Eierstockzysten"],"selten":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Harnwegs- und Blasenentzündung","Anämie (Blutarmut)","Schlaflosigkeit","Erhöhte Triglyzeride"],"unbekannt":["Stimmungsschwankungen, Libidoveränderungen","Kontaktlinsenunverträglichkeit","Nesselsucht, Erythema nodosum oder multiforme","Wassereinlagerungen"]},"schwangerschaft":"Kontraindiziert. Tritt unter der Einnahme eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Nicht empfohlen: kann die Milchmenge vermindern, kleine Hormonmengen gehen in die Muttermilch über. Bis zum Abstillen anders verhüten.","hinweise":["21 Tage lang täglich zur gleichen Zeit einnehmen, danach 7 Tage Pause.","Bei vergessener Einnahme, Erbrechen oder starkem Durchfall kann der Schutz vermindert sein – Packungsbeilage beachten, gegebenenfalls zusätzlich Kondome verwenden.","Bei Anzeichen einer Thrombose (geschwollenes, schmerzendes Bein, plötzliche Atemnot, Brustschmerzen) oder eines Schlaganfalls sofort ärztliche Hilfe holen.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Dragées (überzogene Tabletten)"]},"ethinylestradiol-drospirenon":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Östrogen Ethinylestradiol und das Gestagen Drospirenon hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift; zusätzlich verdickt sich der Schleim am Gebärmutterhals. Drospirenon ist mit Spironolacton verwandt: Es blockiert Mineralokortikoid-Rezeptoren (leicht entwässernd, kann Kalium erhöhen) und wirkt antiandrogen. Ethinylestradiol stabilisiert den Zyklus.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Migräne","Stimmungsschwankungen, depressive Verstimmung","Übelkeit","Brustschmerzen, Brustspannen","Zwischen- und Schmierblutungen, Ausbleiben der Abbruchblutung","Scheidenausfluss, Scheidenpilz (vaginale Candidose)"],"gelegentlich":["Depression, Nervosität, Schläfrigkeit, verminderte Libido","Schwindel, Kribbeln (Parästhesien)","Bluthochdruck, tiefer Blutdruck","Erbrechen, Durchfall, Bauchschmerzen, Blähungen","Akne, Juckreiz, Hautausschlag, Ekzem, Haarausfall","Wassereinlagerungen (Ödeme), Gewichtsveränderungen","Brustvergrösserung, Krampfadern"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Überempfindlichkeitsreaktionen, Asthma","Erythema nodosum oder multiforme (entzündliche Hautknoten bzw. Hautausschlag)","Hörminderung","Absonderung aus der Brust"],"unbekannt":["Chloasma (bräunliche Pigmentflecken im Gesicht)","Lebertumoren","Auslösung oder Verschlechterung eines hereditären Angioödems","Erhöhtes Kalium (Hyperkaliämie) bei eingeschränkter Nierenfunktion","Leicht erhöhte Häufigkeit von Brustkrebsdiagnosen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft sofort absetzen. Eine versehentliche Einnahme in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne Pille etwa 2, mit Drospirenon-Pillen etwa 9–12 von 10'000 Frauen pro Jahr (mit Levonorgestrel-Pillen 5–7); am höchsten im ersten Anwendungsjahr und nach einer Pause von 4 Wochen oder mehr.","Bei einseitiger Beinschwellung oder Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Lähmungen, Seh- oder Sprachstörungen sofort ärztliche Hilfe holen.","Vergessene Tablette sofort nachnehmen und die Anleitung der Packungsbeilage befolgen – wie lange eine Verspätung ohne Schutzverlust möglich ist, hängt vom Präparat ab. Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden gilt wie eine vergessene Tablette.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Filmtabletten (21 + 7 bzw. 24 + 4 Tabletten)"]},"ethinylestradiol-etonogestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Der Ring gibt über die Scheidenschleimhaut gleichmässig täglich etwa 120 Mikrogramm Etonogestrel und 15 Mikrogramm Ethinylestradiol ins Blut ab. Die beiden Hormone hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift; zusätzlich verdickt Etonogestrel, der aktive Metabolit von Desogestrel, den Schleim am Gebärmutterhals. Da die Hormone nicht über den Magen-Darm-Trakt aufgenommen werden, beeinträchtigen Erbrechen oder Durchfall die Wirkung nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Migräne","Depression, verminderte Libido","Bauchschmerzen, Übelkeit","Akne","Brustspannen, Brustschmerzen","Juckreiz im Genitalbereich, Scheidenausfluss, Scheidenentzündung oder -infektion","Schmerzhafte Regelblutung, Unterleibsschmerzen","Gewichtszunahme","Fremdkörpergefühl, Herausgleiten des Rings, Beschwerden beim Geschlechtsverkehr"],"gelegentlich":["Stimmungsschwankungen","Schwindel, Gefühlsstörungen der Haut","Sehstörungen","Hitzewallungen, Blutdruckanstieg","Blähungen, Durchfall, Erbrechen, Verstopfung","Haarausfall, Ekzem, Hautausschlag","Rückenschmerzen, Muskelkrämpfe","Blasenentzündung, Harnwegsinfekt","Zwischenblutungen, Ausbleiben der Abbruchblutung","Müdigkeit, Reizbarkeit, Wassereinlagerungen"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Absonderung aus der Brust (Galaktorrhö)"],"unbekannt":["Überempfindlichkeitsreaktionen bis Angioödem, Nesselsucht","Chloasma (bräunliche Pigmentflecken im Gesicht)","Bruch des Rings mit möglicher Verletzung der Scheide","Gewebereaktionen der Scheide am Ring","Beschwerden am Penis des Partners","Auslösung oder Verschlechterung eines hereditären Angioödems"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft den Ring entfernen. Eine versehentliche Anwendung in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne hormonale Verhütung etwa 2, mit dem Etonogestrel-Ring etwa 6–12 von 10'000 Frauen pro Jahr (mit Levonorgestrel-Pillen 5–7); bei Beinschwellung, plötzlicher Atemnot, Brustschmerzen, Lähmungen oder Sehstörungen sofort ärztliche Hilfe holen.","War der Ring in Woche 1 oder 2 länger als 3 Stunden ausserhalb der Scheide, ist der Schutz vermindert: Ring sofort wieder einsetzen und 7 Tage zusätzlich ein Kondom verwenden (in Woche 3 Anleitung der Packungsbeilage befolgen).","Ring nach 3 Wochen am gleichen Wochentag entfernen, nach genau 7 Tagen Pause einen neuen Ring einsetzen; Ringe nicht wiederverwenden.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Vaginalring"]},"ethinylestradiol-gestoden":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Östrogen Ethinylestradiol und das Gestagen Gestoden hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift. Zusätzlich verdickt Gestoden den Schleim am Gebärmutterhals, der für Spermien schwer durchlässig wird, und verändert die Gebärmutterschleimhaut. Ethinylestradiol stabilisiert den Zyklus und sorgt für eine regelmässige Abbruchblutung in der einnahmefreien Zeit.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Übelkeit, Bauchschmerzen","Depressive Verstimmung, Stimmungsschwankungen","Brustschmerzen, Brustspannen","Gewichtszunahme","Zwischen- und Schmierblutungen, vor allem in den ersten Monaten"],"gelegentlich":["Migräne","Erbrechen, Durchfall","Verminderte Libido","Wassereinlagerungen (Ödeme)","Hautausschlag, Nesselsucht","Brustvergrösserung"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Überempfindlichkeitsreaktionen","Erythema nodosum oder multiforme (entzündliche Hautknoten bzw. Hautausschlag)","Unverträglichkeit von Kontaktlinsen","Scheidenausfluss, Absonderung aus der Brust","Gesteigerte Libido, Gewichtsabnahme"],"unbekannt":["Blutdruckanstieg","Chloasma (bräunliche Pigmentflecken im Gesicht)","Lebertumoren","Auslösung oder Verschlechterung eines hereditären Angioödems","Leicht erhöhte Häufigkeit von Brustkrebsdiagnosen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft sofort absetzen. Eine versehentliche Einnahme in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne Pille etwa 2, mit Gestoden-Pillen etwa 9–12 von 10'000 Frauen pro Jahr (mit Levonorgestrel-Pillen 5–7); am höchsten im ersten Anwendungsjahr und nach einer Pause von 4 Wochen oder mehr.","Bei einseitiger Beinschwellung oder Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Lähmungen, Seh- oder Sprachstörungen sofort ärztliche Hilfe holen.","Vergessene Tablette: bei weniger als 12 Stunden Verspätung sofort nachnehmen; bei mehr als 12 Stunden ist der Schutz vermindert – Anleitung der Packungsbeilage befolgen. Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden gilt wie eine vergessene Tablette.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Tabletten (Einphasen- und Dreiphasenpräparate)"]},"ethinylestradiol-levonorgestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Östrogen Ethinylestradiol und das Gestagen Levonorgestrel hemmen über die Hirnanhangdrüse die Ausschüttung von FSH und LH, sodass keine Eizelle heranreift. Zusätzlich verdickt Levonorgestrel den Schleim am Gebärmutterhals, der für Spermien schwer durchlässig wird, und verändert die Gebärmutterschleimhaut. Ethinylestradiol stabilisiert den Zyklus und sorgt für eine regelmässige Abbruchblutung in der einnahmefreien Zeit.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Übelkeit, Bauchschmerzen","Depressive Verstimmung, Stimmungsschwankungen","Brustschmerzen, Brustspannen","Gewichtszunahme","Zwischen- und Schmierblutungen, vor allem in den ersten Monaten"],"gelegentlich":["Migräne","Erbrechen, Durchfall","Verminderte Libido","Wassereinlagerungen (Ödeme)","Hautausschlag, Nesselsucht","Brustvergrösserung"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Überempfindlichkeitsreaktionen","Erythema nodosum oder multiforme (entzündliche Hautknoten bzw. Hautausschlag)","Unverträglichkeit von Kontaktlinsen","Scheidenausfluss, Absonderung aus der Brust","Gesteigerte Libido, Gewichtsabnahme"],"unbekannt":["Blutdruckanstieg","Chloasma (bräunliche Pigmentflecken im Gesicht)","Lebertumoren","Auslösung oder Verschlechterung eines hereditären Angioödems","Leicht erhöhte Häufigkeit von Brustkrebsdiagnosen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft sofort absetzen. Eine versehentliche Einnahme in der Frühschwangerschaft erhöht das Fehlbildungsrisiko nach heutigem Wissen nicht.","stillzeit":"Nicht empfohlen: Östrogene können die Milchmenge vermindern, und geringe Mengen gehen in die Muttermilch über. In der Stillzeit sind östrogenfreie Methoden besser geeignet.","hinweise":["Thromboserisiko: ohne Pille etwa 2, mit Levonorgestrel-Pillen etwa 5–7 von 10'000 Frauen pro Jahr; am höchsten im ersten Anwendungsjahr und nach einer Pause von 4 Wochen oder mehr.","Bei einseitiger Beinschwellung oder Wadenschmerzen, plötzlicher Atemnot, Brustschmerzen, Lähmungen, Seh- oder Sprachstörungen sofort ärztliche Hilfe holen.","Vergessene Tablette: bei weniger als 12 Stunden Verspätung sofort nachnehmen; bei mehr als 12 Stunden ist der Schutz vermindert – Anleitung der Packungsbeilage befolgen. Erbrechen oder starker Durchfall innerhalb von 3–4 Stunden gilt wie eine vergessene Tablette.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Tabletten (Einphasen- und Dreiphasenpräparate, Langzyklus)"]},"ethinylestradiol-norelgestromin":{"wirkmechanismus":"Verhindert eine Schwangerschaft, indem es den Eisprung unterdrückt. Das Pflaster gibt Ethinylestradiol und das Gestagen Norelgestromin (wirksamer Metabolit von Norgestimat) gleichmässig über die Haut ins Blut ab. Die Hormone hemmen die Ausschüttung von FSH und LH aus der Hirnanhangsdrüse und damit die Follikelreifung; zusätzlich wird der Schleim im Gebärmutterhals für Spermien schwer durchlässig. Die Östrogenbelastung ist höher als bei einer Pille mit 30 µg Ethinylestradiol.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Brustspannen und Brustschmerzen"],"haeufig":["Hautreaktionen an der Klebestelle (Rötung, Reizung, Juckreiz)","Stimmungsschwankungen, depressive Verstimmung, Angst","Schwindel, Migräne","Bauchschmerzen, Erbrechen, Durchfall","Akne, Hautausschlag, Juckreiz","Regelschmerzen, Zwischenblutungen","Vaginale Pilzinfektion","Gewichtszunahme"],"gelegentlich":["Bluthochdruck","Wassereinlagerungen (Ödeme)","Schlaflosigkeit, Libidoabnahme","Haarausfall","Lichtempfindlichkeit der Haut, Nesselsucht","Erhöhte Blutfette"],"selten":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Arterielle Thromboembolie (Herzinfarkt, Schlaganfall)","Gallensteine, Gallenblasenentzündung","Lebertumoren, Brustkrebs","Angioödem, Erythema nodosum","Kontaktlinsenunverträglichkeit"]},"schwangerschaft":"Kontraindiziert. Tritt unter der Anwendung eine Schwangerschaft ein, das Pflaster sofort entfernen; nach versehentlicher Anwendung ist kein erhöhtes Fehlbildungsrisiko bekannt.","stillzeit":"Nicht empfohlen: kann die Milchmenge vermindern, kleine Hormonmengen gehen in die Muttermilch über. Bis zum Abstillen anders verhüten.","hinweise":["Jede Woche am gleichen Wochentag ein neues Pflaster auf saubere, trockene Haut kleben (Gesäss, Bauch, Oberarm-Aussenseite oder Oberkörper, nicht auf die Brust); nach 3 Wochen folgt eine pflasterfreie Woche.","Täglich prüfen, ob das Pflaster gut haftet; bei Ablösung oder verspätetem Wechsel die Packungsbeilage beachten und gegebenenfalls zusätzlich Kondome verwenden.","Bei Anzeichen einer Thrombose (geschwollenes, schmerzendes Bein, plötzliche Atemnot, Brustschmerzen) oder eines Schlaganfalls sofort ärztliche Hilfe holen.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Transdermales Pflaster"]},"ethosuximid":{"wirkmechanismus":"Dämpft die übermässige, rhythmische Aktivität bestimmter Nervenzellen im Gehirn, die Absencen auslöst. Ethosuximid hemmt spannungsabhängige T-Typ-Calciumkanäle in Nervenzellen des Thalamus und unterbricht so die für Absencen typischen 3-Hz-Spike-Wave-Entladungen zwischen Thalamus und Hirnrinde. Gegen grosse (tonisch-klonische) Anfälle wirkt es nicht.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Bauchschmerzen","Appetitlosigkeit, Gewichtsabnahme","Schluckauf (Singultus)","Durchfall","Kopfschmerzen","Müdigkeit, Schläfrigkeit","Schwindel, Gangunsicherheit (Ataxie)"],"unbekannt":["Psychische Veränderungen (Reizbarkeit, Angst, Schlafstörungen, Psychosen)","Blutbildveränderungen bis zu Agranulozytose (Fehlen weisser Blutkörperchen) und aplastischer Anämie","Hautausschlag, Stevens-Johnson-Syndrom (schwere Hautreaktion)","Medikamentös ausgelöster Lupus erythematodes"]},"schwangerschaft":"Nur nach sorgfältiger ärztlicher Abwägung; eine wirksame Behandlung nicht eigenmächtig absetzen. Eine Schwangerschaft möglichst vorher mit der Ärztin oder dem Arzt planen (Folsäure).","stillzeit":"Geht in erheblicher Menge in die Muttermilch über. Stillen nur nach ärztlicher Abwägung und unter Beobachtung des Säuglings (Schläfrigkeit, Trinkschwäche).","hinweise":["Mit oder nach dem Essen einnehmen, das mildert Magen-Darm-Beschwerden.","Nicht abrupt absetzen – Gefahr gehäufter Anfälle.","Bei Fieber, Halsschmerzen, Mundgeschwüren, Hautausschlag oder Blutungen sofort ärztlich abklären; Blutbild und Leberwerte werden regelmässig kontrolliert.","Kann Reaktionsvermögen und Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Kapseln"]},"etilefrin":{"wirkmechanismus":"Hebt einen zu tiefen Blutdruck an, indem es das Herz anregt und die Blutgefässe verengt. Etilefrin ist ein direkt wirkendes Sympathomimetikum, das Alpha-1- und Beta-1-Rezeptoren stimuliert. Über Beta-1-Rezeptoren steigen Schlagkraft und Herzzeitvolumen, über Alpha-1-Rezeptoren nimmt der Gefässtonus, besonders der Venen, zu; dadurch fliesst mehr Blut zum Herzen zurück.","nebenwirkungen":{"unbekannt":["Herzklopfen (Palpitationen), Herzrasen (Tachykardie)","Herzrhythmusstörungen, Brustschmerzen (Angina pectoris)","Blutdruckanstieg","Unruhe, Angst, Schlafstörungen, Zittern","Kopfschmerzen, Schwindel","Übelkeit","Schwitzen"]},"schwangerschaft":"Im ersten Schwangerschaftsdrittel kontraindiziert; danach nur nach strenger ärztlicher Abwägung, da die Durchblutung der Gebärmutter vermindert werden kann.","stillzeit":"Nicht bekannt, ob Etilefrin in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Zuerst nicht-medikamentöse Massnahmen nutzen: genügend trinken, langsam aufstehen, Bewegung, gegebenenfalls Kompressionsstrümpfe.","Die letzte Einnahme nicht spät abends (Unruhe, Schlafstörungen).","Bei Herzklopfen, Brustschmerzen oder starkem Kopfschmerz ärztlich abklären lassen."],"darreichung":["Tropfen zum Einnehmen"]},"etomidat":{"wirkmechanismus":"Führt innerhalb von etwa einer Minute zum Einschlafen; die Wirkung hält nur wenige Minuten an. Etomidat verstärkt die Wirkung des hemmenden Botenstoffs GABA am GABA-A-Rezeptor. Herz und Kreislauf werden im Vergleich zu anderen Narkosemitteln wenig beeinträchtigt. Etomidat wirkt nicht schmerzstillend und hemmt vorübergehend die Cortisolbildung in der Nebennierenrinde (Enzym 11-Beta-Hydroxylase).","nebenwirkungen":{"sehrHaeufig":["Myoklonien (unwillkürliche Muskelzuckungen) und andere Bewegungsstörungen"],"haeufig":["Venenschmerzen bei der Injektion","Übelkeit, Erbrechen","Blutdruckabfall","Kurzer Atemstillstand (Apnoe), Hyperventilation","Hautausschlag"],"gelegentlich":["Schluckauf, Husten","Bradykardie, Herzrhythmusstörungen","Laryngospasmus (Stimmritzenkrampf)","Muskelsteifigkeit","Venenentzündung"],"unbekannt":["Vorübergehend verminderte Cortisolbildung (Nebennierenrindeninsuffizienz)","Anaphylaxie (schwere allergische Reaktion)","Krampfanfälle","Herzstillstand"]},"schwangerschaft":"Nur bei klarer Notwendigkeit; Etomidat gelangt zum Ungeborenen und kann beim Neugeborenen vorübergehend die Cortisolbildung senken.","stillzeit":"Etomidat geht in die Muttermilch über; nach der Gabe 24 Stunden lang nicht stillen.","hinweise":["Wird nur durch Anästhesiefachpersonen mit Überwachung und Beatmungsmöglichkeit verabreicht.","Bekannte Erdnuss- oder Sojaallergie vor der Narkose angeben.","Nach der Narkose mindestens 24 Stunden kein Fahrzeug lenken, keine Maschinen bedienen und keinen Alkohol trinken."],"darreichung":["Emulsion zur Injektion"]},"etonogestrel":{"wirkmechanismus":"Verhindert eine Schwangerschaft vor allem, indem der Eisprung unterdrückt wird. Das Stäbchen gibt gleichmässig das Gestagen Etonogestrel ab, den aktiven Metaboliten von Desogestrel. Etonogestrel bindet an Progesteronrezeptoren, hemmt über die Hirnanhangdrüse den Eisprung auslösenden LH-Anstieg und verdickt den Schleim am Gebärmutterhals, sodass Spermien kaum durchdringen. Die Freisetzung nimmt über die Zeit langsam ab.","nebenwirkungen":{"sehrHaeufig":["Unregelmässige Blutungen (seltener, häufiger, länger oder ausbleibend)","Kopfschmerzen","Akne","Brustspannen, Brustschmerzen","Gewichtszunahme","Scheideninfektion"],"haeufig":["Stimmungsschwankungen, depressive Verstimmung, Nervosität, verminderte Libido","Gesteigerter Appetit, Gewichtsabnahme","Schwindel, Hitzewallungen","Bauchschmerzen, Übelkeit, Blähungen","Haarausfall","Schmerzhafte Regelblutung, Eierstockzysten","Schmerzen oder Reaktionen an der Einlagestelle","Müdigkeit, grippeähnliche Beschwerden"],"gelegentlich":["Angst, Schlaflosigkeit, Schläfrigkeit, Migräne","Erbrechen, Verstopfung, Durchfall","Juckreiz, Hautausschlag, vermehrte Behaarung","Rücken-, Gelenk- und Muskelschmerzen","Blasenentzündung, Beschwerden beim Wasserlösen","Scheidenausfluss, Brustvergrösserung, Absonderung aus der Brust","Wassereinlagerungen (Ödeme), Fieber"],"unbekannt":["Überempfindlichkeitsreaktionen, Nesselsucht, Angioödem","Blutdruckanstieg","Chloasma (Pigmentflecken)","Wanderung des Implantats (selten bis in Blutgefässe oder Lunge), nicht tastbares Implantat","Nerven- oder Gefässverletzung beim Einlegen oder Entfernen","Blutgerinnsel (Thrombose, Embolie) in Einzelfällen"]},"schwangerschaft":"Kontraindiziert; bei Eintritt einer Schwangerschaft das Implantat entfernen. Eine versehentliche Exposition erhöht das Fehlbildungsrisiko nach bisherigen Daten nicht.","stillzeit":"Erlaubt: Milchmenge und -qualität werden nicht beeinträchtigt; geringe Mengen gehen in die Muttermilch über. Einlage in der Regel ab der 4. Woche nach der Geburt.","hinweise":["Das Stäbchen wird von einer geschulten Ärztin oder einem Arzt eingelegt und spätestens nach 3 Jahren entfernt bzw. ersetzt; es sollte unter der Haut tastbar sein.","Das Blutungsmuster ist nicht vorhersehbar und kann sich im Verlauf ändern.","Ist das Implantat nicht tastbar, bis zur Bestätigung der richtigen Lage zusätzlich verhüten.","Schützt nicht vor HIV und anderen sexuell übertragbaren Infektionen."],"darreichung":["Implantat (Hormonstäbchen zum Einlegen unter die Haut)"]},"etoposid":{"wirkmechanismus":"Verhindert, dass Krebszellen ihr Erbgut korrekt verdoppeln und sich teilen. Etoposid hemmt das Enzym Topoisomerase II, das DNA-Stränge vorübergehend schneidet und wieder verbindet; der Enzym-DNA-Komplex wird stabilisiert, sodass Strangbrüche bestehen bleiben. Die Zellen werden in der späten S- und G2-Phase blockiert und sterben ab. Etoposidphosphat (Etopophos) ist eine gut wasserlösliche Vorstufe, die im Blut rasch zu Etoposid umgewandelt wird.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung: Leukopenie, Neutropenie, Thrombozytopenie, Anämie","Übelkeit und Erbrechen","Appetitlosigkeit, Bauchschmerzen, Verstopfung","Haarausfall","Verfärbung der Haut (Pigmentierung)","Erhöhte Leberwerte und Bilirubin","Schwäche (Asthenie), Unwohlsein"],"haeufig":["Akute Leukämie als Zweiterkrankung","Anaphylaktische (schwere allergische) Reaktionen","Schwindel","Herzrhythmusstörungen, Herzinfarkt","Blutdruckabfall bei rascher Infusion, Bluthochdruck","Mukositis (Schleimhautentzündung) einschliesslich Stomatitis und Ösophagitis, Durchfall","Hautausschlag, Juckreiz, Nesselsucht, Venenreizung an der Infusionsstelle"],"gelegentlich":["Periphere Neuropathie (Nervenschäden)","Blutungen"],"selten":["Krampfanfälle","Sehnerventzündung, vorübergehende Erblindung","Interstitielle Lungenentzündung, Lungenfibrose","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Strahlen-Recall-Dermatitis (Hautreaktion in früher bestrahlten Bereichen)","Fieber","Geschmacksstörungen, Schluckbeschwerden"],"unbekannt":["Infektionen","Angioödem, Bronchospasmus (Verkrampfung der Atemwege)","Tumorlyse-Syndrom","Unfruchtbarkeit"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; in der Schwangerschaft nur bei zwingender Indikation. Frauen und Männer sollen während und mindestens 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – Etoposid geht in die Muttermilch über; abstillen.","hinweise":["Vor jeder Behandlung wird das Blutbild kontrolliert; bei Fieber oder Infektzeichen sofort ärztliche Hilfe holen.","Kapseln unzerkaut schlucken.","Etoposid kann die Fruchtbarkeit beeinträchtigen – vor Behandlungsbeginn über das Einfrieren von Samen- oder Eizellen beraten lassen.","Während der Behandlung keine Lebendimpfungen."],"darreichung":["Kapseln","Konzentrat zur Herstellung einer Infusionslösung","Pulver zur Herstellung einer Injektions- oder Infusionslösung (Etoposidphosphat)"]},"etoricoxib":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen und schont dabei die Magenschleimhaut etwas mehr als herkömmliche NSAR. Etoricoxib hemmt selektiv die Cyclooxygenase-2 (COX-2) und damit die Bildung entzündungsfördernder Prostaglandine; COX-1 und die Blutplättchen werden in therapeutischer Dosis kaum beeinflusst. Es wird vorwiegend über CYP3A4 abgebaut und hat eine lange Halbwertszeit, sodass eine Einnahme pro Tag genügt.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen"],"haeufig":["Alveoläre Ostitis (Entzündung nach Zahnziehen)","Ödeme (Wassereinlagerungen)","Schwindel, Kopfschmerzen","Herzklopfen, Herzrhythmusstörungen, Bluthochdruck","Bronchospasmus (Verkrampfung der Atemwege)","Verstopfung, Blähungen, Sodbrennen, Gastritis, Durchfall, Übelkeit, Erbrechen","Erhöhte Leberwerte, Blutergüsse","Müdigkeit, grippeähnliche Beschwerden"],"gelegentlich":["Herzinsuffizienz, Vorhofflimmern, Angina pectoris, Herzinfarkt","Schlaganfall, transitorische ischämische Attacke (TIA), hypertensive Krise","Magen-Darm-Geschwüre mit Blutung oder Durchbruch, Pankreatitis (Bauchspeicheldrüsenentzündung)","Anämie (Blutarmut), Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Angst, Depression, Schlaflosigkeit, Halluzinationen, Geschmacksstörungen","Hautausschlag, Juckreiz, Nesselsucht, Gesichtsödem","Nierenversagen, erhöhte Nierenwerte, Hyperkaliämie (erhöhtes Kalium)","Infekte der Atem- und Harnwege, Atemnot, Nasenbluten"],"selten":["Angioödem und Anaphylaxie (schwere allergische Reaktion)","Verwirrtheit, Unruhe","Hepatitis, Leberversagen, Gelbsucht","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"]},"schwangerschaft":"Kontraindiziert.","stillzeit":"Kontraindiziert.","hinweise":["Blutdruck vor Behandlungsbeginn, in den ersten zwei Wochen und danach regelmässig kontrollieren.","Die Höchstdosis von 120 mg pro Tag nur beim akuten Gichtanfall und höchstens 8 Tage lang.","Ersetzt keine Acetylsalicylsäure zum Herzschutz; so kurz und niedrig dosiert wie möglich.","Kann Schwindel und Müdigkeit verursachen – Vorsicht beim Autofahren."],"darreichung":["Filmtabletten"]},"etranacogen-dezaparvovec":{"wirkmechanismus":"Bringt eine funktionierende Bauanleitung für Gerinnungsfaktor IX in die Leberzellen, sodass der Körper den Faktor selbst herstellt. Der nicht vermehrungsfähige Adeno-assoziierte Virusvektor vom Serotyp 5 (AAV5) enthält das Gen für eine besonders aktive Faktor-IX-Variante (Padua) unter einem leberspezifischen Promotor. Die eingebrachte DNA bleibt überwiegend ausserhalb der Chromosomen in den Leberzellen; dadurch steigt die Faktor-IX-Aktivität anhaltend und regelmässige Faktorinjektionen werden meist überflüssig.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Leberwerte (ALT)","Kopfschmerzen","Grippeähnliche Beschwerden"],"haeufig":["Infusionsbedingte Reaktionen (z. B. Schüttelfrost, Juckreiz, Hautrötung)","Erhöhte Leberwerte (AST) und erhöhtes Bilirubin","Erhöhte Kreatinkinase (Muskelenzym)","Schwindel","Übelkeit","Müdigkeit, Unwohlsein","Fieber"]},"schwangerschaft":"Nicht für die Anwendung bei Frauen bestimmt. Männer sollen nach der Behandlung 12 Monate lang mit Kondom verhüten und keinen Samen spenden.","stillzeit":"Nicht für die Anwendung bei Frauen bestimmt; keine Daten.","hinweise":["Einmalige Infusion in einem spezialisierten Zentrum; danach anfangs wöchentliche, später regelmässige Kontrollen von Leberwerten und Faktor-IX-Aktivität.","Alkohol und leberschädigende Medikamente möglichst meiden, besonders im ersten Jahr nach der Behandlung.","Kein Blut, keine Organe, Gewebe oder Zellen spenden; 12 Monate lang mit Kondom verhüten."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"etrasimod":{"wirkmechanismus":"Verhindert, dass bestimmte Abwehrzellen aus den Lymphknoten in die entzündete Darmschleimhaut wandern. Etrasimod bindet an die Sphingosin-1-Phosphat-Rezeptoren S1P1, S1P4 und S1P5 und bewirkt die Internalisierung von S1P1 auf Lymphozyten. Die Lymphozytenzahl im Blut sinkt dadurch etwa um die Hälfte und erholt sich nach dem Absetzen innerhalb weniger Wochen.","nebenwirkungen":{"haeufig":["Harnwegsinfekte und Infektionen der unteren Atemwege","Lymphopenie (Mangel an Lymphozyten)","Kopfschmerzen, Schwindel","Sehstörungen","Pulsverlangsamung (Bradykardie)","Bluthochdruck","Erhöhtes Cholesterin","Erhöhte Leberwerte"],"gelegentlich":["Makulaödem (Schwellung der Netzhautmitte)","AV-Block 1. oder 2. Grades"],"unbekannt":["Gürtelrose und andere schwere Infektionen","PML (progressive multifokale Leukenzephalopathie)","Hautkrebs","PRES (posteriores reversibles Enzephalopathie-Syndrom)"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während und mindestens 14 Tage nach dem Absetzen zuverlässig verhüten.","stillzeit":"Nicht stillen während der Behandlung.","hinweise":["Einmal täglich ohne einschleichende Dosierung; vor Beginn EKG, bei Herzkrankheiten Überwachung nach der ersten Dosis.","Blutbild, Leberwerte und Blutdruck regelmässig kontrollieren; bei Sehstörungen Augenuntersuchung.","Bei Fieber oder Infektzeichen ärztlich abklären lassen; keine Lebendimpfungen."],"darreichung":["Filmtabletten"]},"etravirin":{"wirkmechanismus":"Hemmt die Vermehrung des HI-Virus, indem es ein Schlüsselenzym des Virus blockiert. Etravirin bindet direkt an die Reverse Transkriptase von HIV-1 in der Nähe des aktiven Zentrums und verhindert so, dass die virale RNA in DNA umgeschrieben wird. Dank seiner flexiblen Molekülstruktur bleibt es gegen viele Viren wirksam, die gegen ältere NNRTI wie Efavirenz oder Nevirapin resistent sind. Gegen HIV-2 wirkt es nicht.","nebenwirkungen":{"sehrHaeufig":["Hautausschlag (meist leicht bis mässig, in den ersten Behandlungswochen)"],"haeufig":["Übelkeit, Durchfall, Erbrechen, Bauchschmerzen, Reflux","Kopfschmerzen, periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Schlafstörungen, Angst","Erhöhte Blutfette und Blutzucker, Diabetes mellitus","Anämie (Blutarmut), Thrombozytopenie (Mangel an Blutplättchen)","Bluthochdruck, Herzinfarkt","Nierenversagen","Müdigkeit, Nachtschweiss"],"gelegentlich":["Überempfindlichkeitsreaktionen, Angioödem (Schwellung von Haut und Schleimhäuten)","Immunrekonstitutionssyndrom","Krampfanfälle, Verwirrtheit, Ohnmacht","Vorhofflimmern, Angina pectoris","Pankreatitis (Bauchspeicheldrüsenentzündung)","Hepatitis, Fettleber","Gynäkomastie (Brustvergrösserung beim Mann)"],"selten":["Stevens-Johnson-Syndrom","Hämorrhagischer Schlaganfall (Hirnblutung)"],"sehrSelten":["Toxische epidermale Nekrolyse","Erythema multiforme"],"unbekannt":["Schwere Überempfindlichkeitsreaktion mit Organbeteiligung (DRESS)"]},"schwangerschaft":"Begrenzte Erfahrungen; Anwendung nur nach ärztlicher Abwägung, wenn der Nutzen das mögliche Risiko überwiegt. Die HIV-Therapie in der Schwangerschaft soll von einem HIV-Zentrum begleitet werden.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Nach einer Mahlzeit einnehmen – nüchtern wird deutlich weniger Wirkstoff aufgenommen. Wer Tabletten nicht schlucken kann, darf sie in einem Glas Wasser auflösen.","Bei Hautausschlag mit Fieber, Blasen, Schleimhautbeteiligung oder starkem Unwohlsein sofort ärztliche Hilfe holen.","Regelmässig und ohne Unterbruch einnehmen; vor jedem neuen Medikament – auch Johanniskraut und anderen pflanzlichen Mitteln – Wechselwirkungen prüfen lassen."],"darreichung":["Tabletten"]},"everolimus":{"wirkmechanismus":"Hemmt einen zentralen Schalter für Zellwachstum und -teilung. Everolimus bindet an das Protein FKBP-12; dieser Komplex hemmt die Kinase mTOR (mTORC1). Dadurch werden Proteinsynthese, Zellteilung, Gefässneubildung im Tumor und Glukosestoffwechsel gebremst. In Immunzellen verhindert die mTOR-Hemmung die durch Interleukin-2 ausgelöste Vermehrung aktivierter T-Lymphozyten, was die Abstossung eines Transplantats unterdrückt.","nebenwirkungen":{"sehrHaeufig":["Infektionen","Stomatitis (Mundschleimhautentzündung)","Anämie","Hyperglykämie (erhöhter Blutzucker), erhöhte Blutfette (Cholesterin, Triglyzeride)","Appetitlosigkeit, Geschmacksstörungen, Durchfall, Übelkeit","Pneumonitis, Husten, Atemnot, Nasenbluten","Hautausschlag, trockene Haut, Juckreiz, Nagelveränderungen","Müdigkeit, Schwäche, periphere Ödeme, Gewichtsverlust"],"haeufig":["Thrombozytopenie, Neutropenie, Leukopenie, Lymphopenie","Hypophosphatämie, Hypokaliämie, Hypokalzämie, Diabetes mellitus","Bluthochdruck, Blutungen","Erbrechen, Mundtrockenheit, Bauchschmerzen, Dyspepsie","Erhöhte Leberwerte (ALT, AST)","Nierenversagen, Proteinurie (Eiweiss im Urin)","Kopfschmerzen, Schlaflosigkeit, Bindehautentzündung","Unregelmässige Menstruation, Akne, Gelenkschmerzen, Fieber"],"gelegentlich":["Herzschwäche","Tiefe Venenthrombose, Lungenembolie","Wundheilungsstörungen","Panzytopenie (Mangel an allen Blutzellen)","Akutes Atemnotsyndrom (ARDS)"],"selten":["Angioödem","Erythroblastopenie (Ausfall der Bildung roter Blutkörperchen)"],"unbekannt":["Hepatitis-B-Reaktivierung","Verstärkte Strahlenreaktionen, Strahlen-Recall-Reaktion"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Indikation (im Tierversuch fruchtschädigend). Frauen müssen während und bis mindestens 8 Wochen nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung und mindestens 2 Wochen nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich (Certican zweimal täglich) immer zur gleichen Zeit und immer gleich – stets mit oder stets ohne Mahlzeit – einnehmen; Grapefruit meiden.","Bei Mundentzündung alkohol- und peroxidfreie Mundspülungen verwenden; eine dexamethasonhaltige Mundspülung kann vorbeugen.","Blutbild, Blutzucker, Blutfette und Nierenwerte werden regelmässig kontrolliert; bei Transplantation und tuberöser Sklerose auch der Blutspiegel.","Keine Lebendimpfungen; Husten, Atemnot oder Fieber sofort melden."],"darreichung":["Tabletten","Tabletten zur Herstellung einer Suspension zum Einnehmen"]},"evolocumab":{"wirkmechanismus":"Senkt das LDL-Cholesterin stark, indem es dafür sorgt, dass die Leber mehr «Cholesterin-Fänger» behält. Evolocumab ist ein humaner monoklonaler IgG2-Antikörper, der das im Blut zirkulierende Protein PCSK9 (Proproteinkonvertase Subtilisin/Kexin Typ 9) bindet. PCSK9 bewirkt normalerweise, dass LDL-Rezeptoren in der Leberzelle abgebaut werden; ist es blockiert, kehren mehr Rezeptoren an die Zelloberfläche zurück und entfernen LDL-Cholesterin aus dem Blut. Das LDL-Cholesterin sinkt dadurch um mehr als die Hälfte. Als Eiweiss wird Evolocumab wie körpereigene Antikörper abgebaut, nicht über Leberenzyme.","nebenwirkungen":{"haeufig":["Grippe (Influenza), Nasen-Rachen-Entzündung, Infekte der oberen Atemwege","Überempfindlichkeitsreaktionen, Hautausschlag","Übelkeit","Rückenschmerzen, Gelenkschmerzen, Muskelschmerzen","Reaktionen an der Injektionsstelle (z. B. Rötung, Schmerzen, Bluterguss)"],"gelegentlich":["Nesselsucht (Urtikaria)","Grippeähnliche Beschwerden"],"selten":["Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)"]},"schwangerschaft":"Nicht anwenden, ausser der Zustand der Frau erfordert eine Behandlung – keine ausreichenden Erfahrungen; Antikörper gelangen vor allem im letzten Drittel zum Ungeborenen.","stillzeit":"Ein Risiko für den gestillten Säugling ist nicht auszuschliessen – ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Im Kühlschrank (2–8 °C) lagern, nicht einfrieren; vor dem Spritzen etwa 30 Minuten Raumtemperatur annehmen lassen. Ausserhalb des Kühlschranks (bis 25 °C) höchstens 1 Monat haltbar.","Unter die Haut von Bauch, Oberschenkel oder Oberarm spritzen und die Stelle wechseln.","Keine bekannten Wechselwirkungen mit anderen Medikamenten; Statin und Ernährungsmassnahmen weiterführen."],"darreichung":["Injektionslösung im Fertigpen"]},"exemestan":{"wirkmechanismus":"Senkt den Östrogenspiegel nach den Wechseljahren stark, sodass hormonabhängige Tumoren nicht mehr angeregt werden. Exemestan ähnelt dem natürlichen Substrat der Aromatase (Androstendion) und bindet irreversibel an das Enzym, das dadurch dauerhaft inaktiviert wird («Suizidhemmer»). Die Östrogenspiegel sinken um etwa 90 %. Exemestan hat zudem eine schwache androgene Wirkung.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Schlaflosigkeit, Depression","Kopfschmerzen, Schwindel","Vermehrtes Schwitzen","Gelenk- und Muskelschmerzen","Müdigkeit, Schmerzen","Übelkeit, Bauchschmerzen","Erhöhte Leber- und Bilirubinwerte"],"haeufig":["Appetitlosigkeit","Karpaltunnelsyndrom, Kribbeln","Erbrechen, Durchfall, Verstopfung, Verdauungsbeschwerden","Haarausfall, Hautausschlag, Nesselsucht, Juckreiz","Osteoporose, Knochenbrüche","Ödeme, Schwäche","Leukopenie, Thrombozytopenie"],"gelegentlich":["Überempfindlichkeitsreaktionen"],"selten":["Schläfrigkeit","Hepatitis, cholestatische Hepatitis","Akute generalisierte exanthematische Pustulose (schwere Hautreaktion)"]},"schwangerschaft":"Kontraindiziert.","stillzeit":"Kontraindiziert.","hinweise":["Einmal täglich nach einer Mahlzeit einnehmen.","Knochendichte und Vitamin-D-Spiegel kontrollieren; ausreichend Calcium und Bewegung.","Bei Müdigkeit, Schwindel oder Schläfrigkeit nicht Auto fahren."],"darreichung":["Dragées","Filmtabletten"]},"exenatid":{"wirkmechanismus":"Ahmt ein Darmhormon nach, das nach dem Essen die Insulinausschüttung anregt. Exenatid ist ein synthetisches Peptid (ursprünglich im Speichel der Gila-Krustenechse entdeckt), das den GLP-1-Rezeptor aktiviert. Es steigert blutzuckerabhängig die Insulinfreisetzung, hemmt die Glucagonausschüttung, verlangsamt die Magenentleerung und vermindert den Appetit. Bydureon ist eine Depotform mit Mikrokügelchen, die den Wirkstoff über Wochen gleichmässig abgibt.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erbrechen (vor allem mit Byetta)","Knötchen an der Injektionsstelle (Bydureon)","Hypoglykämie (Unterzuckerung) in Kombination mit Sulfonylharnstoffen"],"haeufig":["Appetitminderung","Kopfschmerzen, Schwindel","Bauchschmerzen, Verdauungsbeschwerden, Sodbrennen","Obstipation (Verstopfung)","Müdigkeit, Schwächegefühl","Juckreiz und Rötung an der Injektionsstelle","Vermehrtes Schwitzen, Zittrigkeit"],"gelegentlich":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Dehydratation (Flüssigkeitsmangel)","Verschlechterung der Nierenfunktion bis zum akuten Nierenversagen","Verzögerte Magenentleerung","Geschmacksstörung","Haarausfall"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Darmverschluss","Medikamentenbedingte Thrombozytopenie (Mangel an Blutplättchen)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)","Gallensteine, Gallenblasenentzündung"]},"schwangerschaft":"Nicht anwenden; in der Schwangerschaft wird Insulin verwendet. Bydureon wegen der langen Wirkdauer mindestens 3 Monate vor einer geplanten Schwangerschaft absetzen.","stillzeit":"Nicht anwenden, da nicht bekannt ist, ob Exenatid in die Muttermilch übergeht.","hinweise":["Byetta innerhalb von 60 Minuten vor dem Morgen- und Abendessen spritzen, nicht nach der Mahlzeit; Bydureon einmal wöchentlich am gleichen Wochentag, unabhängig von den Mahlzeiten.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen (mögliche Pankreatitis).","Bei Erbrechen oder Durchfall ausreichend trinken, um die Nieren zu schützen.","Vor Operationen, Magenspiegelungen oder Narkosen die Behandlung angeben."],"darreichung":["Injektionslösung im Fertigpen (zweimal täglich)","Retard-Injektionssuspension im Fertigpen (einmal wöchentlich)"]},"ezetimib":{"wirkmechanismus":"Senkt das Cholesterin, indem es dessen Aufnahme aus dem Darm bremst. Ezetimib hemmt das Transportprotein Niemann-Pick C1-Like 1 (NPC1L1) in der Dünndarmwand, über das Cholesterin aus Nahrung und Galle sowie Pflanzensterine aufgenommen werden. Dadurch gelangt weniger Cholesterin zur Leber; diese bildet mehr LDL-Rezeptoren und senkt so das LDL-Cholesterin im Blut. Zusammen mit einem Statin, das die Cholesterinbildung in der Leber hemmt, ergänzen sich die beiden Wirkprinzipien. Ezetimib wird zu einem ebenfalls wirksamen Glucuronid umgewandelt und nicht über CYP-Enzyme abgebaut.","nebenwirkungen":{"haeufig":["Bauchschmerzen, Durchfall, Blähungen","Müdigkeit","In Kombination mit einem Statin: Kopfschmerzen, Muskelschmerzen, erhöhte Transaminasen (Leberwerte)"],"gelegentlich":["Erhöhte Leberwerte (Gamma-GT, Transaminasen) und CK (Muskelenzym) unter Ezetimib allein","Husten","Verdauungsbeschwerden, Sodbrennen (Reflux), Übelkeit","Gelenkschmerzen, Muskelkrämpfe, Nackenschmerzen","Verminderter Appetit","Hitzewallungen, Bluthochdruck","Brustschmerzen, Schmerzen"],"unbekannt":["Überempfindlichkeitsreaktionen: Anaphylaxie, Angioödem, Ausschlag, Nesselsucht; Erythema multiforme","Thrombozytopenie (Mangel an Blutplättchen)","Myopathie, Rhabdomyolyse (Muskelzerfall)","Hepatitis, Gallensteine, Gallenblasenentzündung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Schwindel, Kribbeln, Depression","Atemnot, Verstopfung, Schwäche"]},"schwangerschaft":"Allein nur bei eindeutiger Notwendigkeit (keine ausreichenden Daten); zusammen mit einem Statin kontraindiziert.","stillzeit":"Nicht anwenden – nicht bekannt, ob Ezetimib in die Muttermilch übergeht; zusammen mit einem Statin kontraindiziert.","hinweise":["Einmal täglich zu beliebiger Tageszeit, mit oder ohne Essen.","Bei Colestyramin oder Colesevelam Abstand einhalten: Ezetimib 2 Stunden vorher oder 4 Stunden nachher.","Cholesterinarme Ernährung und Bewegung fortsetzen; Blutfette und Leberwerte regelmässig kontrollieren.","Unerklärliche Muskelschmerzen oder -schwäche ärztlich melden."],"darreichung":["Tabletten"]}});
